content:
name: KQL Validations
run-name: KQL Validations running on ${{ github.ref_name }}
on:
    pull_request:
        branches:
            - master
    # Allows to run workflow manually from the Actions tab
    workflow_dispatch:
jobs:
    KqlValidations:
      runs-on: ubuntu-22.04
      env:
        buildConfiguration: Release
        dotnetSdkVersion: 6.0.x
        PRNUM: ${{ github.event.pull_request.number }}
      steps:
      - uses: actions/checkout@v4
        with:
          fetch-depth: 2  # Need HEAD and parent for git diff
      - name: Use .NET Core SDK ${{ env.dotnetSdkVersion }}
        uses: actions/setup-dotnet@v4
        with:
          dotnet-version: ${{ env.dotnetSdkVersion }}
      - name: Run KQL Validation tests
        run: dotnet test .script/tests/KqlvalidationsTests/Kqlvalidations.Tests.csproj --configuration ${{ env.buildConfiguration }}
        env:
          GITHUBAPPID: ${{ secrets.APPLICATION_ID }}
          GITHUBAPPINSTALLATIONID: ${{ secrets.APPLICATION_INSTALLATION_ID }}
          GITHUBAPPPRIVATEKEY: ${{ secrets.APPLICATION_PRIVATE_KEY }}
          SYSTEM_PULLREQUEST_ISFORK: ${{ github.event.pull_request.head.repo.fork }}

# THIS WORKFLOW WILL RUN WHEN WE ADD SLASH COMMAND LIKE '/arm-ttk', '/ARM-TTK', '/Arm-Ttk', 'armttk' or 'ARMTTK'
name: Slash Command ARM-TTK Tests

on:
  issue_comment:
    types: [created, edited]

permissions:
  contents: read
  issues: read
  pull-requests: read

jobs:
  run-arm-ttk:
    runs-on: ubuntu-latest
    if: ${{ github.actor != 'dependabot[bot]' && !github.event.pull_request.head.repo.fork && github.event.issue.pull_request && contains(fromJson('["/armttk", "/Armttk", "/ARM-TTK", "/ARMTTK", "/arm-ttk", "/ArmTtk"]'), github.event.comment.body) }}
    outputs:
      solutionName: ${{ steps.step1.outputs.solutionName }}
      mainTemplateChanged: ${{ steps.step1.outputs.mainTemplateChanged }}
      createUiChanged: ${{ steps.step1.outputs.createUiChanged }}
    steps:
      - name: Get PR details and validate
        id: get-pr
        uses: actions/github-script@v7
        with:
          script: |
            const { data: pr } = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.issue.number
            });

            // Check if this is a fork PR
            const isFork = pr.head.repo.full_name !== context.repo.owner + '/' + context.repo.repo;
            if (isFork) {
              core.notice('ARM-TTK tests cannot be run on fork PRs for security reasons');
              core.setOutput('is_fork', 'true');
              return;
            }

            core.setOutput('is_fork', 'false');
            core.setOutput('head_sha', pr.head.sha);
            core.setOutput('head_repo', pr.head.repo.full_name);

      - name: Checkout PR (secure)
        if: steps.get-pr.outputs.is_fork == 'false'
        uses: actions/checkout@11bd71901bbe5b1630ceea73d27597364c9af683 # v4.2.2
        with:
          fetch-depth: 10
          ref: ${{ steps.get-pr.outputs.head_sha }}
          persist-credentials: false
      - shell: pwsh
        if: steps.get-pr.outputs.is_fork == 'false'
        id: step1
        name: Identify Changes in PR
        run: |
          try {
            Set-PSRepository PSGallery -InstallationPolicy Trusted
            Install-Module powershell-yaml -Force
            ./.script/package-automation/arm-ttk-tests.ps1
          }
          catch {
            Write-Error "Failed to run ARM-TTK tests: $_"
            exit 1
          }

      - uses: docker/build-push-action@4f58ea79222b3b9dc2c8bbdd6debcef730109a75 # v6.9.0
        id: publishGithubPackage
        name: Run ARM-TTK
        if: ${{ steps.get-pr.outputs.is_fork == 'false' && success() && steps.step1.outputs.solutionName != '' && (steps.step1.outputs.mainTemplateChanged == 'true' || steps.step1.outputs.createUiChanged == 'true') }}
        with:
          context: .
          file: ./.github/actions/Dockerfile
          push: false
          provenance: false
          build-args: |
            SolutionName=${{ steps.step1.outputs.solutionName }}
            mainTemplateChanged=${{ steps.step1.outputs.mainTemplateChanged }}
            createUiChanged=${{ steps.step1.outputs.createUiChanged }}

name: Block PR merging on blocked labels

on:
  pull_request_target:
    types: [labeled, unlabeled]
    branches:
      - dev
      - release

jobs:
  block-merge:
    runs-on: ubuntu-latest
    steps:
      - name: Check blocked labels
        uses: actions/github-script@v7
        with:
          script: |
            const labels = context.payload.pull_request.labels.map(label => label.name);
            const blockedLabels = ["do-not-merge", "needs-author-feedback"];

            if (labels.some(label => blockedLabels.includes(label))) {
              console.log(`It is not allowed to merge a PR with any blocked labels: ${blockedLabels}`);
              process.exit(1); // Exit with a non-zero status code to block merge
            } else {
              console.log("It is allowed to merge the PR.");
            }

name: CCOA

on:
  pull_request_target:
    types:
      - opened
      - reopened
    branches:
      - dev

permissions:
  pull-requests: write

jobs:
  add_label_and_comment:
    runs-on: ubuntu-latest

    steps:
      - name: Check current date securely
        id: date_check
        run: |
          # Define the block date (Jan 7, 2025)
          BLOCK_DATE=$(date -d "2025-01-07" +%s)

          # Get the current date in seconds
          CURRENT_DATE=$(date +%s)

          # Validate the dates and safely output the result
          if [ "$CURRENT_DATE" -lt "$BLOCK_DATE" ]; then
            echo "continue=true" >> "$GITHUB_OUTPUT"
          else
            echo "continue=false" >> "$GITHUB_OUTPUT"
          fi

      - name: Comment on PR
        if: steps.date_check.outputs.continue == 'true'
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            // Fetch existing comments
            const comments = await github.rest.issues.listComments({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
            });

            // Check if the specific comment already exists
            const existingComment = comments.data.find(comment =>
              comment.body.includes("⚠️**Your changes in this PR will be released on Jan 14, 2025 due to CCOA (extend to Jan 6, 2025)**")
            );

            if (existingComment) {
              console.log("Comment already exists. Skipping...");
            } else {
              console.log("No comment found. Adding a new one...");
              // Add a new comment
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.issue.number,
                body: "⚠️**Your changes in this PR will be released on Jan 14, 2025 due to CCOA (extend to Jan 6, 2025)**",
              });
            }

name: Label New Issues

on:
  issues:
    types: [opened]

permissions:
  issues: write
  contents: read

jobs:
  label-issue:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout private action repository
        uses: actions/checkout@v4
        with:
          repository: NVIDIA/goggles_action
          path: ./.github/actions/goggles_action # local path to store the action
          ref: v1.3.0

      - name: AI Label Issue
        uses: ./.github/actions/goggles_action/actions/llm_label
        with:
          ACTION_TOKEN: ${{ secrets.GITHUB_TOKEN }}
          LLM_MODEL_NAME: ${{ secrets.LLM_MODEL_NAME }}
          LLM_TOKEN_SERVER_URL: ${{ secrets.LLM_TOKEN_SERVER_URL }}
          LLM_TOKEN_CLIENT_ID: ${{ secrets.LLM_TOKEN_CLIENT_ID }}
          LLM_TOKEN_CLIENT_SECRET: ${{ secrets.LLM_TOKEN_CLIENT_SECRET }}
          LLM_GENERATE_URL: ${{ secrets.LLM_GENERATE_URL }}
          LLM_TOKEN_SCOPE: ${{ secrets.LLM_TOKEN_SCOPE }}
          REPO_OWNER: ${{ github.repository_owner }}
          REPO_NAME: ${{ github.event.repository.name }}
          ISSUE_NUMBER: ${{ github.event.issue.number }}
          ISSUE_TITLE: ${{ github.event.issue.title }}
          ISSUE_BODY: ${{ github.event.issue.body }}
          GITHUB_API_URL: ${{ github.api_url }}
          ACTIONS_STEP_VERBOSE: false
          EXCLUDED_LABELS: "Investigating,internal-bug-tracked,stale,triaged,wontfix"
          LLM_SYSTEM_PROMPT: |
            You are an expert GitHub issue labeler. Your task is to analyze the provided issue title, issue body, and a list of available labels with their descriptions.
            Based on this information, select the single most appropriate label from the list that best captures the primary issue or request.
            Prefer selecting only one label that represents the main topic or problem. Only suggest multiple labels if the issue genuinely spans multiple distinct areas that are equally important.
            Respond with ONLY the chosen label name (e.g., 'bug', 'feature-request') or comma-separated names if multiple are truly needed.
            If no labels seem appropriate, respond with 'NONE'.
            Do not add any other text, explanation, or markdown formatting.

name: auto-assign
on:
  issues:
    types:
      - labeled

jobs:
  assign_issue:
    # Only run on module label colors.
    if: ${{ github.event.label.color == '00611d' }}
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v6

      - name: Get assignee
        uses: actions/github-script@v8
        id: get-assignee
        with:
          github-token: ${{secrets.GITHUB_TOKEN}}
          script: |
            const fs = require('fs');

            // Read configuration file
            const config = JSON.parse(fs.readFileSync('.github/workflows/module-owners.json', 'utf8'));

            // Find matching label in config
            for (const [configLabel, users] of Object.entries(config)) {
              if (configLabel == "${{ github.event.label.name}}") {
                // Select Randomly
                const index = Math.floor(Math.random() * users.length)
                const assignee = users[index % users.length];
                return assignee
              }
            }
            // Returning empty string in case a valid assignee is not found.
            return ""
          result-encoding: string

      - name: Assign
        run: gh issue edit ${{ github.event.issue.number }} --add-label "triaged" --add-label "investigating" --add-assignee ${{ steps.get-assignee.outputs.result }}
        env:
          GH_TOKEN: ${{ secrets.GITHUB_TOKEN }}

name: Label New Issues

on:
  issues:
    types: [opened]

permissions:
  issues: write
  contents: read

jobs:
  label-issue:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout private action repository
        uses: actions/checkout@v6
        with:
          repository: NVIDIA/goggles_action
          path: ./.github/actions/goggles_action # local path to store the action
          ref: v1.3.0

      - name: AI Label Issue
        uses: ./.github/actions/goggles_action/actions/llm_label
        with:
          ACTION_TOKEN: ${{ secrets.GITHUB_TOKEN }}
          LLM_MODEL_NAME: ${{ secrets.GOGGLES_LLM_MODEL_NAME }}
          LLM_TOKEN_SERVER_URL: ${{ secrets.GOGGLES_LLM_TOKEN_SERVER_URL }}
          LLM_TOKEN_CLIENT_ID: ${{ secrets.GOGGLES_LLM_TOKEN_CLIENT_ID }}
          LLM_TOKEN_CLIENT_SECRET: ${{ secrets.GOGGLES_LLM_TOKEN_CLIENT_SECRET }}
          LLM_GENERATE_URL: ${{ secrets.GOGGLES_LLM_GENERATE_URL }}
          LLM_TOKEN_SCOPE: ${{ secrets.GOGGLES_LLM_TOKEN_SCOPE }}
          REPO_OWNER: ${{ github.repository_owner }}
          REPO_NAME: ${{ github.event.repository.name }}
          ISSUE_NUMBER: ${{ github.event.issue.number }}
          ISSUE_TITLE: ${{ github.event.issue.title }}
          ISSUE_BODY: ${{ github.event.issue.body }}
          GITHUB_API_URL: ${{ github.api_url }}
          ACTIONS_STEP_VERBOSE: false
          EXCLUDED_LABELS: "bug,Community want to contribute,Community Engagement,duplicate,help wanted,Investigating,need more info,question,roadmap,stale,waiting for feedback,wontfix"
          LLM_SYSTEM_PROMPT: |
            You are an expert GitHub issue labeler. Your task is to analyze the provided issue title, issue body, and a list of available labels with their descriptions.
            Based on this information, select the single most appropriate label from the list that best captures the primary issue or request.
            Prefer selecting only one label that represents the main topic or problem. Only suggest multiple labels if the issue genuinely spans multiple distinct areas that are equally important.
            Respond with ONLY the chosen label name (e.g., 'bug', 'feature-request') or comma-separated names if multiple are truly needed.
            If no labels seem appropriate, respond with 'NONE'.
            If the issue is a bug (the 'bug' label may be applied separately and is excluded here), output ONLY the applicable secondary labels from this exact allowlist: Customized kernels, Decoding, Disaggregated serving, Doc, Frontend, General perf, Inference runtime, Infra, LLM API, Model customization, Model optimization, OOTB, Pytorch, Scale-out, Speculative Decoding, Testing, Triton backend, Windows. Use exact casing; if none apply, respond with 'NONE'. Do not output 'bug'.
            Do not add any other text, explanation, or markdown formatting.

name: Manage Waiting for Feedback Label

on:
  issue_comment:
    types: [created]
  pull_request_review_comment:
    types: [created]

permissions:
  issues: write
  pull-requests: write

jobs:
  manage-waiting-for-feedback:
    runs-on: ubuntu-latest
    if: github.repository == 'NVIDIA/TensorRT-LLM'
    steps:
      - name: Check membership and manage label
        uses: actions/github-script@v8
        with:
          script: |
            const commenter = context.payload.comment.user.login;
            const commenterType = context.payload.comment.user.type;
            const label = 'waiting for feedback';

            // Ignore bots and CI accounts
            const ignoredAccounts = ['tensorrt-cicd'];
            if (commenterType === 'Bot' || ignoredAccounts.includes(commenter)) {
              console.log(`Ignoring comment from ${commenter} (type: ${commenterType}). Skipping.`);
              return;
            }

            // Handle both issue_comment and pull_request_review_comment events
            // context.issue.number is only available for issue_comment events
            const issueNumber = context.issue?.number || context.payload.pull_request?.number;
            const issue = context.payload.issue || context.payload.pull_request;
            const author = issue?.user?.login;
            const isAuthor = (commenter === author);

            if (!issueNumber) {
              console.log('Could not determine issue/PR number. Skipping.');
              return;
            }

            console.log(`Comment by ${commenter} on #${issueNumber} (author: ${author})`);
            const owner = context.repo.owner;
            const repo = context.repo.repo;

            // Check if commenter is repository member
            let isMember = false;
            try {
              await github.rest.repos.checkCollaborator({
                owner,
                repo,
                username: commenter
              });
              isMember = true;
            } catch (error) {
              if (error.status === 404) {
                isMember = false;
              } else if (error.status === 302) {
                console.log(`Cannot determine membership for ${commenter} (insufficient token permissions)`);
                return;
              } else {
                console.error(`Error checking membership: ${error.message}`);
                throw error;
              }
            }

            // Logic:
            // - Author responds → remove label (feedback provided)
            // - NVIDIA non-author comments → add label (team is waiting for response)
            // - External non-author comments → remove label (someone provided feedback)

            if (isAuthor) {
              // Author responded - remove 'waiting for feedback' label
              console.log(`${commenter} is the author. Removing '${label}' label if present.`);

              try {
                await github.rest.issues.removeLabel({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: issueNumber,
                  name: label
                });
                console.log(`Successfully removed '${label}' label from #${issueNumber}`);
              } catch (error) {
                if (error.status === 404) {
                  console.log(`Label '${label}' was not present on #${issueNumber}. No action needed.`);
                } else {
                  throw error;
                }
              }

            } else if (isMember) {
              // NVIDIA non-author commented - add 'waiting for feedback' label
              console.log(`${commenter} is an NVIDIA member (not author). Adding '${label}' label.`);

              await github.rest.issues.addLabels({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: issueNumber,
                labels: [label]
              });

              console.log(`Successfully added '${label}' label to #${issueNumber}`);

            } else {
              // External non-author commented - remove 'waiting for feedback' label
              console.log(`${commenter} is external (not author). Removing '${label}' label if present.`);

              try {
                await github.rest.issues.removeLabel({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: issueNumber,
                  name: label
                });
                console.log(`Successfully removed '${label}' label from #${issueNumber}`);
              } catch (error) {
                if (error.status === 404) {
                  console.log(`Label '${label}' was not present on #${issueNumber}. No action needed.`);
                } else {
                  throw error;
                }
              }
            }

