name: Synchronize Linked Issues

on:
  pull_request_target:
    # Run this action when a PR is opened or edited
    # Issues do not have a graphQL connection to linked PRs so we can't use that event
    types: [edited]

env:
 ORG: ${{ github.event.repository.owner.login }}
 PR_NUMBER: ${{ github.event.pull_request.number }}
 REPO: ${{ github.event.repository.name }}

 # The environment vars below are hard-coded from external queries to save time + complexity here
 # Note: PVT means Project V2, not "Private"
 PROJECT_ID: "PVT_kwDOABpemM4AEhOI"
 STATUS_FIELD_ID: "PVTSSF_lADOABpemM4AEhOIzgCmnYc"
 WORKING_SPRINT_FIELD_ID: "PVTIF_lADOABpemM4AEhOIzgJlRho"
 START_SPRINT_FIELD_ID: "PVTIF_lADOABpemM4AEhOIzgJlRhU"

jobs:
  query_and_mutate_project_fields:
    if: github.repository == 'NVIDIA/cccl'
    runs-on: ubuntu-latest

    steps:
      - name: Generate token
        id: generate_token
        uses: tibdex/github-app-token@v1.8.0
        with:
          app_id: ${{ secrets.CCCL_AUTH_APP_ID }}
          private_key: ${{ secrets.CCCL_AUTH_APP_PEM }}

      - name: Get PR Project ID
        id: get_pr_id
        env:
          GITHUB_TOKEN: ${{ steps.generate_token.outputs.token }}
        run: |
            # Query up to 10 projects for the PR
            gh api graphql -f query='
              query {
                organization(login: "${{ env.ORG }}") {
                  repository(name: "${{ env.REPO }}") {
                    issueOrPullRequest(number: ${{ env.PR_NUMBER }}) {
                      ... on PullRequest {
                        id
                        projectItems(first: 10) {
                          edges {
                            node {
                              id
                              project {
                                id
                              }
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }' > project_data.json

            # Filter the json result to only the project-specific ID for the PR
            # A PR can be in multiple projects so we need to filter by the project ID we want
            pr_id=$(jq -r '.data.organization.repository.issueOrPullRequest.projectItems.edges[] |
                           select(.node.project.id == "${{ env.PROJECT_ID }}") |
                           .node.id' project_data.json)
            echo "PR_ID=$pr_id" >> $GITHUB_ENV
        continue-on-error: true

      - name: Get Status, Start Sprint, and Working Sprint Fields from the PR
        id: get_pr_status
        env:
          GITHUB_TOKEN: ${{ steps.generate_token.outputs.token }}
        run: |
            # Query the PR's status from the project
            gh api graphql -f query='
              query {
                node(id: "${{ env.PR_ID }}") {
                  ... on ProjectV2Item {
                    id
                    fieldValueByName(name: "Status") {
                      ... on ProjectV2ItemFieldSingleSelectValue {
                        optionId
                      }
                    }
                  }
                }
              }' > status_field_data.json
            status_option_id=$(jq -r '.data.node.fieldValueByName.optionId' status_field_data.json)
            echo "STATUS_OPTION_ID=$status_option_id" >> $GITHUB_ENV

            # Query the PR's start sprint from the project
            gh api graphql -f query='
              query {
                node(id: "${{ env.PR_ID }}") {
                  ... on ProjectV2Item {
                    id
                    fieldValueByName(name: "Start Sprint") {
                      ... on ProjectV2ItemFieldIterationValue {
                        iterationId
                      }
                    }
                  }
                }
              }' > start_sprint_data.json
            start_sprint_iteration_id=$(jq -r '.data.node.fieldValueByName.iterationId' start_sprint_data.json)
            echo "START_SPRINT_ITERATION_ID=$start_sprint_iteration_id" >> $GITHUB_ENV

            # Query the PR's working sprint from the project
            gh api graphql -f query='
              query {
                node(id: "${{ env.PR_ID }}") {
                  ... on ProjectV2Item {
                    id
                    fieldValueByName(name: "Working Sprint") {
                      ... on ProjectV2ItemFieldIterationValue {
                        iterationId
                      }
                    }
                  }
                }
              }' > working_sprint_data.json
            working_sprint_iteration_id=$(jq -r '.data.node.fieldValueByName.iterationId' working_sprint_data.json)
            echo "WORKING_SPRINT_ITERATION_ID=$working_sprint_iteration_id" >> $GITHUB_ENV

        continue-on-error: true

      - name: Sync Linked Issues
        id: update_linked_issues
        env:
          GITHUB_TOKEN: ${{ steps.generate_token.outputs.token }}
        run: |
            gh api graphql -f query='
              query {
                organization(login: "${{ env.ORG }}") {
                  repository(name: "${{ env.REPO }}") {
                    issueOrPullRequest(number: ${{ env.PR_NUMBER }}) {
                      ... on PullRequest {
                        id
                        closingIssuesReferences(first: 10) {
                          edges {
                            node {
                              id
                              projectItems(first: 10) {
                                nodes {
                                  id
                                }
                                edges {
                                  node {
                                    id
                                    project {
                                      id
                                    }
                                  }
                                }
                              }
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }' > project_data.json
            issue_ids=$(jq -r '.data.organization.repository.issueOrPullRequest.closingIssuesReferences.edges[].node.projectItems.edges[] |
                               select(.node.project.id == "${{ env.PROJECT_ID }}") |
                               .node.id' project_data.json)

            for issue_id in $issue_ids; do
              # The query below is constructed differently than the others due to bash variable syntax + github actions syntax interactions
              # Update Status
              QUERY="mutation {
                updateProjectV2ItemFieldValue(
                  input: {
                    projectId: \"$PROJECT_ID\"
                    itemId: \"$issue_id\"
                    fieldId: \"$STATUS_FIELD_ID\"
                  value: {
                      singleSelectOptionId: \"$STATUS_OPTION_ID\"
                      }
                    }
                  ) {
                    projectV2Item {
                      id
                    }
                  }
                }"
              gh api graphql --field query="$QUERY"

              # Update Start Sprint
              QUERY="mutation {
                updateProjectV2ItemFieldValue(
                  input: {
                    projectId: \"$PROJECT_ID\"
                    itemId: \"$issue_id\"
                    fieldId: \"$START_SPRINT_FIELD_ID\"
                  value: {
                      iterationId: \"$START_SPRINT_ITERATION_ID\"
                      }
                    }
                  ) {
                    projectV2Item {
                      id
                    }
                  }
                }"
              gh api graphql --field query="$QUERY"

              # Update Working Sprint
              QUERY="mutation {
                updateProjectV2ItemFieldValue(
                  input: {
                    projectId: \"$PROJECT_ID\"
                    itemId: \"$issue_id\"
                    fieldId: \"$WORKING_SPRINT_FIELD_ID\"
                  value: {
                      iterationId: \"$WORKING_SPRINT_ITERATION_ID\"
                      }
                    }
                  ) {
                    projectV2Item {
                      id
                    }
                  }
                }"
              gh api graphql --field query="$QUERY"

            done
        continue-on-error: true

name: Auto Label Issues

on:
  issues:
    types: [opened]

jobs:
  add-labels:
    runs-on: ubuntu-latest
    permissions:
      issues: write
    steps:
      - name: Add component label
        uses: actions/github-script@v7
        with:
          script: |
            const issue = context.payload.issue;
            const body = issue.body || '';

            // Parse the issue body to find the component selection
            // GitHub renders dropdown selections as "### {label}\n\n{selection}"
            // Check for both bug report and feature request dropdown labels
            const bugComponentMatch = body.match(/### Which component has the problem\?\s*\n\s*\n\s*(.+?)(?:\n|$)/);
            const featureComponentMatch = body.match(/### Which component requires the feature\?\s*\n\s*\n\s*(.+?)(?:\n|$)/);

            const componentMatch = bugComponentMatch || featureComponentMatch;

            if (componentMatch) {
              const component = componentMatch[1].trim();
              let label = '';

              // Map component selections to labels
              switch(component) {
                case 'CuTe DSL':
                  label = 'CuTe DSL';
                  break;
                case 'CUTLASS C++':
                  label = 'CUTLASS C++';
                  break;
              }

              if (label) {
                await github.rest.issues.addLabels({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: issue.number,
                  labels: [label]
                });
                console.log(`Added label: ${label}`);
              }
            }

name: Labels

# https://docs.github.com/en/actions/using-workflows/workflow-syntax-for-github-actions#permissions
permissions:
  actions: none
  checks: none
  contents: none
  deployments: none
  id-token: none
  # This action can update/close issues
  issues: write
  discussions: none
  packages: none
  pages: none
  # This action can update/close pull requests
  pull-requests: write
  repository-projects: none
  security-events: none
  statuses: none

on:
  pull_request_target:
    types: [labeled]
  issues:
    types: [labeled]

jobs:
  handle-labels:
    if: github.repository_owner == 'NVIDIA'
    runs-on: ubuntu-latest
    steps:
      - uses: actions/github-script@v7
        with:
          github-token: ${{secrets.GITHUB_TOKEN}}
          script: |
            // NOTE: The following section is JavaScript. Note that backticks will need to be escaped within
            // the multiline comment strings in the following config. When editing this file, using JavaScript
            // syntax highlighting might be easier.
            //
            // This script has intentionally been inlined instead of using third-party Github actions for both
            // security and performance reasons.
            const allConfig = {
              pullRequests: {
                'needs linting': {
                  close: false,
                  comment: `
                    Thanks for your pull request! Before this pull request can be merged, it must pass the checks of our automated linting tools.

                    We use \`black\` to ensure the consistent format of our code. This can be run from the root directory of garak:

                    \`\`\`
                    black garak
                    \`\`\`

                    Please update your branch after these have been made, and reach out if you have any problems.
                  `
                },
                'needs unique branch': {
                  close: true,
                  comment: `
                    Thanks for your pull request! We require for all contributed code to come from a **from a unique branch** in your repository before it can be merged.

                    Please create a new branch in your fork of garak and resubmit this from that branch.

                    If you are using Git on the command line that may look like:

                    \`\`\`
                    # Checkout the main branch
                    git checkout main

                    # Create a new branch for your feature
                    git checkout -b <BRANCH_NAME>

                    # Add your new files
                    git add plugins/my-cool-new-plugin

                    # Commit your changes with a relevant message
                    git commit

                    # Push your changes to GitHub
                    git push origin <BRANCH_NAME>

                    # Now browse to the following URL and create your pull request!
                    # - https://github.com/NVIDIA/garak/pulls
                    \`\`\`

                    This helps protect the process, ensure users are aware of commits on the branch being considered for merge, allows for a location for more commits to be offered without mingling with other contributor changes and allows contributors to make progress while a PR is still being reviewed.

                    Please do resubmit from a unique branch, we greatly value your contribution! :tada:
                  `
                },
                'needs testing environment': {
                  close: false,
                  comment: `
                    Thanks for your pull request! As part of our landing process, we manually verify that all plugins work as expected.

                    We have been unable to test this plugin successfully. This may be due to software or hardware requirements we cannot replicate.

                    To help unblock this pull request, please:

                    - Comment with links to documentation on how to set up an environment, and provide exact software version numbers to use
                    - Or comment guided steps on how to set up our environment for testing this plugin

                    Once there's a clear path for testing and evaluating this code, we can progress with this further.
                  `
                },
                'needs pull request template': {
                  close: false,
                  comment: `
                    When creating a pull request, please ensure that the default pull request template has been updated with the required details.
                  `
                },
              },
              issues: {
                'needs more information': {
                  close: false,
                  comment: `
                    It looks like there's not enough information to replicate this issue. Please provide any relevant output and logs which may be useful in diagnosing the issue.

                    This includes:

                    - All of the item points within this [template](https://github.com/NVIDIA/garak/blob/master/.github/ISSUE_TEMPLATE/bug_report.md)
                    - Screenshots showing the issues you're having
                    - Exact replication steps

                    The easier it is for us to replicate and debug an issue means there's a higher chance of this issue being resolved.
                  `
                },
                // Used for issues that have zero effort applied, potentially bot related
                potato: {
                  close: true,
                  comment: `
                    When creating an issue, please ensure that the default issue template has been updated with the required details:
                    https://github.com/NVIDIA/garak/issues/new/choose

                    Closing this issue. If you believe this issue has been closed in error, please provide any relevant output and logs which may be useful in diagnosing the issue.
                  `
                },
              }
            };

            const issueType = context.eventName === 'issues' ? 'issues' : 'pullRequests';
            const config = allConfig[issueType][context.payload.label.name];
            if (!config) {
              return;
            }

            if (config.comment) {
              const precedingWhitespaceLength = config.comment.split("\n")[1].search(/\S/);
              const commentWithoutPrecedingWhitespace = config.comment.split("\n").map(line => line.substring(precedingWhitespaceLength)).join("\n").trim();
              await github.rest.issues.createComment({
                issue_number: context.issue.number,
                owner: context.repo.owner,
                repo: context.repo.repo,
                body: commentWithoutPrecedingWhitespace
              });
            }
            if (config.close) {
              await github.rest.issues.update({
                  issue_number: context.issue.number,
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  state: 'closed'
              });
            }

name: '[docker] build docker image'

on:
  workflow_dispatch:
    inputs:
      images:
        description: 'Images (separated by commas)'
        required: true
      tag:
        description: 'TAG'
        default: 'latest'
        required: true
  push:
    branches:
      - master
      - main
    tags-ignore:
      - '**'
    paths:
      - 'buildconfig/docker/**'

jobs:
  changed_images:
    runs-on: ubuntu-latest
    outputs:
      changed_images: ${{ steps.changed_images.outputs.changed_images }}
    steps:
      - name: Get changed images
        id: changed_images
        uses: actions/github-script@v6
        with:
          script: |
            const { basename, sep } = require('path');
            const { appendFileSync } = require('fs');
            const { EOL } = require('os');
            const { eventName } = context;
            const { repos } = github.rest;
            const push = context.payload;

            const changedImages = new Set();

            if (eventName === 'workflow_dispatch') {
              '${{ github.event.inputs.images }}'.split(',').forEach(image => changedImages.add(image.trim()));
            } else if (eventName === 'push') {
              const files = await github.paginate(repos.compareCommits, {
                ...context.repo,
                base: push.before,
                head: push.after,
                per_page: 100
              });

              files.filter(({ status, filename }) =>
                (status === 'added' || status === 'modified' || status === 'changed' || status === 'copied' || status === 'renamed')
                && basename(filename) === 'Dockerfile').forEach(({ filename }) => {
                  changedImages.add(filename.split(sep).slice(-2)[0]);
              });
            }

            appendFileSync(process.env.GITHUB_OUTPUT, `changed_images=${JSON.stringify(Array.from(changedImages))}${EOL}`, { encoding: 'utf8' });

  build_images:
    needs: changed_images
    runs-on: ${{ github.repository == 'Tencent/Hippy' && fromJson('[''self-hosted'', ''linux'', ''shared'']') || 'ubuntu-latest' }}
    strategy:
      matrix:
        images: ${{ fromJson(needs.changed_images.outputs.changed_images) }}
    steps:
      - name: Checkout repo
        uses: actions/checkout@v3
        with:
          fetch-depth: 0
      - name: Log in
        uses: docker/login-action@v2
        with:
          registry: ghcr.io
          username: ${{ github.repository_owner }}
          password: ${{ secrets.GITHUB_TOKEN }}
      - name: Get repo owner(in lowercase)
        id: get_owner
        uses: ASzc/change-string-case-action@v2
        with:
          string: ${{ github.repository_owner }}
      - name: Make & Push to ghcr.io
        uses: docker/build-push-action@v4
        with:
          context: buildconfig/docker/${{ matrix.images }}
          push: true
          tags: ghcr.io/${{ steps.get_owner.outputs.lowercase }}/${{ matrix.images }}:${{ github.event.inputs.tag || 'latest' }}

name: '[gh] action approve checks'

on:
  pull_request_target:
    branches:
      - master
      - main
      - v3.0-dev
      - v3.0
    types:
      - labeled

jobs:
  call_approval_checks_run:
    if: github.event.label.name == 'action(approve-checks)' && github.repository == 'Tencent/Hippy'
    uses: ./.github/workflows/reuse_approve_checks_run.yml
    with:
      pull_request_number: ${{ github.event.pull_request.number }}
      pull_request_head_sha: ${{ github.event.pull_request.head.sha }}

  approve_checks_action:
    needs: call_approval_checks_run
    runs-on: ubuntu-latest
    steps:
    - name: Token
      uses: navikt/github-app-token-generator@v1
      id: get-token
      with:
        private-key: ${{ secrets.ACTION_PRIVATE_KEY }}
        app-id: ${{ secrets.ACTION_APP_ID }}
    - name: Action
      uses: actions/github-script@v6.3.3
      env:
        COMMENT_MESSAGE: |
          :lock: The current `approve-checks` action execution requires privilege escalation.

          Please wait for approval of admin team member ...

          @${{ github.event.sender.login }}
        WECHAT_WORK_MESSAGE: |
          [${{ github.event.sender.login }}](https://github.com/${{ github.event.sender.login }}) requested privilege escalation action on [#${{ github.event.pull_request.number }}](${{ github.event.pull_request.html_url }}) pull request.
          > ${{ github.event.pull_request.title }}
          > [${{ github.event.pull_request.html_url }}](${{ github.event.pull_request.html_url }})
        PRIVILEGE_ESCALATION: ${{ needs.call_approval_checks_run.outputs.included_risk_files }}
      with:
        github-token: ${{ steps.get-token.outputs.token }}
        script: |
          const { pull_request } = context.payload;
          const { issues } = github.rest;

          const p = [];
          if (process.env.PRIVILEGE_ESCALATION == 'true') {
            p.push(issues.createComment({
              issue_number: pull_request.number,
              body: process.env.COMMENT_MESSAGE,
              ...context.repo
            }));
            p.push(github.request("POST ${{ secrets.WECHAT_WORK_BOT_WEBHOOK }}", {
              headers: {
                "content-type": "application/json"
              },
              data: {
                chatid: "${{ secrets.WECHAT_WORK_ADMIN_CHAT_ID }}",
                msgtype: "markdown",
                markdown: {
                  content: process.env.WECHAT_WORK_MESSAGE,
                  attachments: [{
                    callback_id: "approve",
                    actions: [{
                      name: "approve_btn",
                      text: "Mark as Approved",
                      type: "button",
                      value: "Mark as Approved",
                      replace_text: "Already approved",
                      border_color: "2c974b",
                      text_color: "2c974b"
                    }, {
                      name: "reject_btn",
                      text: "Mark as Rejected",
                      type: "button",
                      value: "Mark as Rejected",
                      replace_text: "Already Rejected",
                      border_color: "cf222e",
                      text_color: "cf222e"
                    }, {
                      name: "ignored_btn",
                      text: "Mark as Ignored",
                      type: "button",
                      value: "Mark as Ignored",
                      replace_text: "Already Ignored",
                      border_color: "6e7781",
                      text_color: "6e7781"
                    }]
                  }]
                }
              }
            }));
          } else {
            p.push(issues.removeLabel({
              issue_number: pull_request.number,
              name: 'action(approve-checks)',
              ...context.repo,
            }).catch(e => {
              console.error('issues.removeLabel', e);
            }));
          }

          await Promise.all(p);

  call_approval_checks_run_privileged:
    needs: [ call_approval_checks_run, approve_checks_action ]
    if: needs.call_approval_checks_run.outputs.included_risk_files == 'true'
    uses: ./.github/workflows/reuse_approve_checks_run.yml
    with:
      pull_request_number: ${{ github.event.pull_request.number }}
      pull_request_head_sha: ${{ github.event.pull_request.head.sha }}
      requied_privilege_escalation: true

  approve_checks_action_privileged:
    needs: call_approval_checks_run_privileged
    runs-on: ubuntu-latest
    steps:
    - name: Token
      uses: navikt/github-app-token-generator@v1
      id: get-token
      with:
        private-key: ${{ secrets.ACTION_PRIVATE_KEY }}
        app-id: ${{ secrets.ACTION_APP_ID }}
    - name: Action
      uses: actions/github-script@v6.3.3
      with:
        github-token: ${{ steps.get-token.outputs.token }}
        script: |
          const { pull_request } = context.payload;
          const { issues } = github.rest;

          await issues.removeLabel({
            issue_number: pull_request.number,
            name: 'action(approve-checks)',
            ...context.repo,
          }).catch(e => {
            console.error('issues.removeLabel', e);
          });

name: '[gh] action merge'

on:
  pull_request_target:
    branches:
      - master
      - main
      - v3.0-dev
      - v3.0
    types:
      - labeled

env:
  OUTPUT_FUNCTION: |
    function output {
      if [ $1 -ne 0 ]; then
          if [[ -z "$2" ]]; then
            echo "failed_result=(empty response)" >> $GITHUB_OUTPUT
          else
            echo "failed_result<<EOF" >> $GITHUB_OUTPUT
            echo "$2" >> $GITHUB_OUTPUT
            echo "EOF" >> $GITHUB_OUTPUT
          fi
          exit 0
      fi
    }

jobs:
  call_classify_commits:
    if: github.repository == 'Tencent/Hippy' && (github.event.label.name == 'action(squash-merge)' || github.event.label.name == 'action(rebase-merge)')
    uses: ./.github/workflows/reuse_classify_commits.yml
    with:
      pull_request_number: ${{ github.event.pull_request.number }}

  squash_merge_action:
    needs: call_classify_commits
    if: github.event.label.name == 'action(squash-merge)'
    runs-on: ubuntu-latest
    steps:
    - name: Token
      uses: navikt/github-app-token-generator@v1
      id: get-token
      with:
        private-key: ${{ secrets.ACTION_PRIVATE_KEY }}
        app-id: ${{ secrets.ACTION_APP_ID }}
    - name: Reset
      if: "contains(github.event.pull_request.labels.*.name, 'action(squash-merge): failed')"
      uses: actions-ecosystem/action-remove-labels@v1.3.0
      with:
        github_token: ${{ steps.get-token.outputs.token }}
        labels: "action(squash-merge): failed"
    - name: Checkout
      if: needs.call_classify_commits.outputs.normal_commits_count > 1
      uses: actions/checkout@v3
      with:
        fetch-depth: 0
    - name: Setup
      if: needs.call_classify_commits.outputs.normal_commits_count > 1
      uses: actions/setup-node@v3
      with:
        node-version: 16.x
        cache: 'npm'
        cache-dependency-path: package-lock.json
    - name: Install
      if: needs.call_classify_commits.outputs.normal_commits_count > 1
      run: |
        npm install commitlint-plugin-function-rules@1.6.0 @commitlint/cli@16.2.1 @commitlint/config-conventional@16.2.1 @commitlint/lint@16.2.1 @commitlint/prompt-cli@16.2.1
    - name: Commitlint
      id: commitlint
      env:
        PULL_REQUEST_TITLE: ${{ github.event.pull_request.title }}
      shell: bash {0}
      run: |
        ${{ env.OUTPUT_FUNCTION }}
        if [ ${{ needs.call_classify_commits.outputs.normal_commits_count }} -gt 1 ]; then
          result=`echo $PULL_REQUEST_TITLE | npx commitlint -c false 2>&1`
          output $? "$result"
        fi
    - name: Squash
      id: squash
      if: ${{ !steps.commitlint.outputs.failed_result && github.event.pull_request.user.login != github.event.sender.login }}
      env:
        GH_TOKEN: ${{ steps.get-token.outputs.token }}
      shell: bash {0}
      run: |
        ${{ env.OUTPUT_FUNCTION }}
        result=`gh pr merge ${{ github.event.pull_request.number }} --disable-auto --repo $GITHUB_REPOSITORY 2>&1`
        output $? "$result"
        result=`gh pr merge ${{ github.event.pull_request.number }} --squash --auto --repo $GITHUB_REPOSITORY 2>&1`
        output $? "$result"
    - name: Comment
      uses: actions/github-script@v6.3.3
      env:
        SQUASH_RESULT: ${{ steps.squash.outputs.failed_result }}
        CHECK_RESULT: ${{ steps.commitlint.outputs.failed_result }}
        FAILED_MESSAGE: |
          :warning: `squash-merge` action execution failed, because of **%s**.

          Please check the following details:
          <details open>

          ```
          %s
          ```

          </details>

          ${{ github.event.sender.type == 'User' && format('@{0}', github.event.sender.login) || '#help' }}
      with:
        github-token: ${{ steps.get-token.outputs.token }}
        script: |
          const { pull_request, sender } = context.payload;
          const { issues } = github.rest;
          const util = require('util');
          const os = require('os');

          let body;
          if (process.env.CHECK_RESULT) {
            body = util.format(process.env.FAILED_MESSAGE, 'pull request title does not meet the [Convention Commit](https://conventionalcommits.org/) guideline', process.env.CHECK_RESULT);
          } else if (process.env.SQUASH_RESULT) {
            body = util.format(process.env.FAILED_MESSAGE, 'auto squash and merge failed', process.env.SQUASH_RESULT);
          } else if (pull_request.user.login === sender.login) {
            body = util.format(process.env.FAILED_MESSAGE, 'cannot squash and merge your own pull request', `(empty response)`);
          }

          const p = [];
          p.push(issues.removeLabel({
            issue_number: pull_request.number,
            name: 'action(squash-merge)',
            ...context.repo,
          }).catch(e => {
            console.log('issues.removeLabel', e);
          }));
          if (body) {
            p.push(issues.createComment({
              issue_number: pull_request.number,
              body: body,
              ...context.repo
            }));
            p.push(issues.addLabels({
              issue_number: pull_request.number,
              labels: [ 'action(squash-merge): failed' ],
              ...context.repo
            }));
          }
          await Promise.all(p);

  rebase_merge_action_preparation:
    needs: call_classify_commits
    if: github.event.label.name == 'action(rebase-merge)'
    runs-on: ubuntu-latest
    outputs:
      permission: ${{ steps.get-permission.outputs.permission }}
    steps:
    - name: Permission
      id: get-permission
      uses: actions/github-script@v6.3.3
      with:
        script: |
          const { repos } = github.rest;
          const fs = require('fs');
          const os = require('os');

          const { data: { permission } } = await repos.getCollaboratorPermissionLevel({
            ...context.repo,
            username: "${{ github.event.sender.login }}"
          });
          fs.appendFileSync(process.env.GITHUB_OUTPUT, `permission=${permission}${os.EOL}`, { encoding: 'utf8' });
    - name: Token
      uses: navikt/github-app-token-generator@v1
      if: steps.get-permission.outputs.permission != 'admin' && needs.call_classify_commits.outputs.normal_commits_count > 1
      id: get-token
      with:
        private-key: ${{ secrets.ACTION_PRIVATE_KEY }}
        app-id: ${{ secrets.ACTION_APP_ID }}
    - name: Comment
      if: steps.get-token.outputs.token
      env:
        COMMENT_MESSAGE: |
          :lock: `rebase-merge` action execution needs privilege escalation.

          Please wait for admin team member approval ...

          ${{ github.event.sender.type == 'User' && format('@{0}', github.event.sender.login) || '' }}
        WECHAT_WORK_MESSAGE: |
          [${{ github.event.sender.login }}](https://github.com/${{ github.event.sender.login }}) requested privilege escalation action on [#${{ github.event.pull_request.number }}](${{ github.event.pull_request.html_url }}) pull request.
          > ${{ github.event.pull_request.title }}
          > [${{ github.event.pull_request.html_url }}](${{ github.event.pull_request.html_url }})
      uses: actions/github-script@v6.3.3
      with:
        github-token: ${{ steps.get-token.outputs.token }}
        script: |
          const { pull_request } = context.payload;
          const { issues } = github.rest;
          const util = require('util');

          const p = [];

          p.push(issues.createComment({
            issue_number: pull_request.number,
            body: process.env.COMMENT_MESSAGE,
            ...context.repo
          }));

          p.push(github.request("POST ${{ secrets.WECHAT_WORK_BOT_WEBHOOK }}", {
            headers: {
              "content-type": "application/json"
            },
            data: {
              chatid: "${{ secrets.WECHAT_WORK_ADMIN_CHAT_ID }}",
              msgtype: "markdown",
              markdown: {
                content: process.env.WECHAT_WORK_MESSAGE,
                attachments: [{
                  callback_id: "approve",
                  actions: [{
                    name: "approve_btn",
                    text: "Mark as Approved",
                    type: "button",
                    value: "Mark as Approved",
                    replace_text: "Already approved",
                    border_color: "2c974b",
                    text_color: "2c974b"
                  }, {
                    name: "reject_btn",
                    text: "Mark as Rejected",
                    type: "button",
                    value: "Mark as Rejected",
                    replace_text: "Already Rejected",
                    border_color: "cf222e",
                    text_color: "cf222e"
                  }, {
                    name: "ignored_btn",
                    text: "Mark as Ignored",
                    type: "button",
                    value: "Mark as Ignored",
                    replace_text: "Already Ignored",
                    border_color: "6e7781",
                    text_color: "6e7781"
                  }]
                }]
              }
            }
          }));

          await Promise.all(p);

  rebase_merge_action:
    needs: [ rebase_merge_action_preparation, call_classify_commits ]
    runs-on: ubuntu-latest
    environment: ${{ (needs.rebase_merge_action_preparation.outputs.permission != 'admin' && needs.call_classify_commits.outputs.normal_commits_count > 1) && 'github-actions-privileged' || '' }}
    steps:
    - name: Token
      uses: navikt/github-app-token-generator@v1
      id: get-token
      with:
        private-key: ${{ secrets.ACTION_PRIVATE_KEY }}
        app-id: ${{ secrets.ACTION_APP_ID }}
    - name: Check
      if: "contains(github.event.pull_request.labels.*.name, 'action(rebase-merge): failed')"
      uses: actions-ecosystem/action-remove-labels@v1.3.0
      with:
        github_token: ${{ steps.get-token.outputs.token }}
        labels: "action(rebase-merge): failed"
    - name: Rebase
      id: rebase
      env:
        GH_TOKEN: ${{ steps.get-token.outputs.token }}
      shell: bash {0}
      run: |
        ${{ env.OUTPUT_FUNCTION }}
        result=`gh pr merge ${{ github.event.pull_request.number }} --disable-auto --repo $GITHUB_REPOSITORY 2>&1`
        output $? "$result"
        result=`gh pr merge ${{ github.event.pull_request.number }} --rebase --auto --repo $GITHUB_REPOSITORY 2>&1`
        output $? "$result"
    - name: Comment
      uses: actions/github-script@v6.3.3
      env:
        REBASE_RESULT: ${{ steps.rebase.outputs.failed_result }}
        FAILED_MESSAGE: |
          :warning: `rebase-merge` action execution failed, because of **%s**.

          Please check the following details:
          <details open>

          ```
          %s
          ```

          </details>

          ${{ github.event.sender.type == 'User' && format('@{0}', github.event.sender.login) || '#help' }}
      with:
        github-token: ${{ steps.get-token.outputs.token }}
        script: |
          const { pull_request } = context.payload;
          const { issues } = github.rest;
          const util = require('util');

          const p = [];
          p.push(issues.removeLabel({
            issue_number: pull_request.number,
            name: 'action(rebase-merge)',
            ...context.repo,
          }).catch(e => {
            console.log('issues.removeLabel', e);
          }));
          if (process.env.REBASE_RESULT) {
            p.push(issues.createComment({
              issue_number: pull_request.number,
              body: util.format(process.env.FAILED_MESSAGE, 'auto rebase and merge failed', process.env.REBASE_RESULT),
              ...context.repo
            }));
            p.push(issues.addLabels({
              issue_number: pull_request.number,
              labels: [ 'action(rebase-merge): failed' ],
              ...context.repo
            }));
          }
          await Promise.all(p);

  rebase_merge_action_rejected:
    needs: [ rebase_merge_action ]
    if: failure()
    runs-on: ubuntu-latest
    steps:
    - name: Token
      uses: navikt/github-app-token-generator@v1
      id: get-token
      with:
        private-key: ${{ secrets.ACTION_PRIVATE_KEY }}
        app-id: ${{ secrets.ACTION_APP_ID }}
    - name: Label
      uses: actions/github-script@v6.3.3
      with:
        github-token: ${{ steps.get-token.outputs.token }}
        script: |
          const { pull_request } = context.payload;
          const { issues } = github.rest;

          const p = [];
          p.push(issues.removeLabel({
            issue_number: pull_request.number,
            name: 'action(rebase-merge)',
            ...context.repo,
          }).catch(e => {
            console.log('issues.removeLabel', e);
          }));
          p.push(issues.addLabels({
            issue_number: pull_request.number,
            labels: [ 'action(rebase-merge): failed' ],
            ...context.repo
          }));

          await Promise.all(p);

name: '[gh] issue crash report'

on:
  issues:
    types:
      - opened

env:
  greetings_message: |
    🙇 Thank you for making us aware of the issue.

    Don\'t worry about it, our collaborators will handle it asap.

    If you have any additional information, you can add a new comment in this issue.
  translates_addresses_message: |
    I will try to translate addresses to human readable format, please wait a moment.
  fetch_symbol_failed_message: |
    I have searched the artifacts store database, but found no artifacts with version %s and %s architecture.
  no_backtrace_message: |
    It looks like there is no backtrace addresses in the crash log that needs to be translated.
  translate_success_message: |
    After my translation, the result is as follows.
    ```
    %s
    ```
  translate_failed_message: |
    Sorry, the addresses translation encountered an error.

jobs:
  triage:
    if: github.repository == 'Tencent/Hippy' && contains(github.event.issue.title, 'crash')
    runs-on: [self-hosted, linux, shared]
    container:
      image: node:latest
    outputs:
      version: ${{ steps.triage-result.outputs.version }}
      platform: ${{ steps.triage-result.outputs.platform }}
      architecture: ${{ steps.triage-result.outputs.architecture }}
      logs: ${{ steps.triage-result.outputs.logs }}
      setps: ${{ steps.triage-result.outputs.setps }}
      additional: ${{ steps.triage-result.outputs.additional }}
      repository_owner: ${{ steps.triage-result.outputs.repository_owner }}
    steps:
    - name: Greetings
      uses: actions/github-script@v6.3.3
      with:
        script: |
          const { owner, repo } = context.repo;
          const { issues, reactions } = github.rest;

          const { data: { id } } = await issues.createComment({
            owner,
            repo,
            issue_number: ${{ github.event.issue.number }},
            body: process.env.greetings_message
          });
          await reactions.createForIssue({
            owner,
            repo,
            issue_number: ${{ github.event.issue.number }},
            content: '+1'
          });
    - run: npm install markdown-it
    - name: Triage
      id: triage-result
      uses: actions/github-script@v6.3.3
      env:
        issue_body: ${{ github.event.issue.body }}
      with:
        script: |
          const MarkdownIt = require('markdown-it');
          const os = require('os');
          const path = require('path');
          const fs = require('fs');

          function parse(markdown) {
            const tokens = (new MarkdownIt()).parse(markdown, {});
            const result = {};

            let inHeading = true;
            let key = [];
            let value = [];
            tokens.forEach((token, index) => {
              if (token.type === 'heading_open' && token.markup === '###') {
                if (key.length > 0) {
                  result[key.join(os.EOL)] = value.join(os.EOL);
                }
                key = [];
                value = [];
                inHeading = true;
              } else if (token.type === 'heading_close' && token.markup === '###') {
                inHeading = false;
              } else {
                const { content } = token;
                if (content) {
                  if (inHeading) {
                    key.push(content);
                  } else {
                    value.push(content);
                  }
                }
              }

              if (index === tokens.length - 1) {
                result[key.join(os.EOL)] = value.join(os.EOL);
              }
            });
            return result;
          }

          const info = parse(process.env.issue_body);
          ['Version', 'Platform', 'Architecture', 'Logs', 'Reproduce Condition', 'Additional Information'].forEach(key => {
            let value = info[key];
            if (value) {
              if (['Version', 'Platform', 'Architecture'].includes(key)) {
                value = value.replaceAll(/[^0-9a-z\-_\.]/ig, '');
              }
              fs.appendFileSync(process.env.GITHUB_OUTPUT, `${key.toLowerCase()}<<EOF${os.EOL}`, { encoding: 'utf8' });
              fs.appendFileSync(process.env.GITHUB_OUTPUT, value + os.EOL, { encoding: 'utf8' });
              fs.appendFileSync(process.env.GITHUB_OUTPUT, `EOF${os.EOL}`, { encoding: 'utf8' });
            }
          });

          fs.appendFileSync(process.env.GITHUB_OUTPUT, `repository_owner=${'${{ github.repository_owner }}'.toLowerCase()}${os.EOL}`, { encoding: 'utf8' });

  android-translates-addresses:
    needs:
      - triage
    if: |
      needs.triage.outputs.platform == 'Android'
      && needs.triage.outputs.version
      && needs.triage.outputs.logs
      && (needs.triage.outputs.architecture == 'arm'
        || needs.triage.outputs.architecture == 'arm64'
        || needs.triage.outputs.architecture == 'x86'
        || needs.triage.outputs.architecture == 'x86_64')
    runs-on: [self-hosted, linux, shared]
    container:
      image: ghcr.io/${{ needs.triage.outputs.repository_owner }}/android-release:latest
    steps:
    - name: Token
      uses: navikt/github-app-token-generator@v1
      id: get-token
      with:
        private-key: ${{ secrets.BOT_APP_KEY }}
        app-id: ${{ secrets.BOT_APP_ID }}
    - name: Backtrace
      id: backtrace_parsed
      uses: actions/github-script@v6.3.3
      env:
        triage_logs: ${{ needs.triage.outputs.logs }}
      with:
        github-token: ${{ steps.get-token.outputs.token }}
        script: |
          const { owner, repo } = context.repo;
          const { issues } = github.rest;
          const { appendFileSync } = require('fs');
          const { EOL } = require('os');

          function parse(log) {
            const stack = [];
            for (const [_, pc, file, func] of log.matchAll(/#[0-9a-f]+\s+pc\s+(?:0x)?([0-9a-f]{${{ contains(needs.triage.outputs.architecture, '64') && 16 || 8}}})\s+([^\s]+)(?:\s+\(([^\+]+\+[0-9]+)\))*/ig)) {
              stack.push({pc, func, file});
            }
            return stack;
          }

          const backtrace = parse(process.env.triage_logs);
          if (backtrace.length > 0) {
            appendFileSync(process.env.GITHUB_OUTPUT, `backtrace=${JSON.stringify(backtrace)}${EOL}`, { encoding: 'utf8' });
          }

          await issues.createComment({
            owner,
            repo,
            issue_number: ${{ github.event.issue.number }},
            body: process.env[backtrace.length > 0 ? 'translates_addresses_message' : 'no_backtrace_message']
          });
    - name: Symbols
      id: symbols_fetched
      if: steps.backtrace_parsed.outputs.backtrace
      continue-on-error: true
      shell: bash
      run: |
        if [[ "${{ needs.triage.outputs.architecture }}" == "arm" ]]; then
          ZIP_FILE="armeabi-v7a.zip"
        elif [[ "${{ needs.triage.outputs.architecture }}" == "arm64" ]]; then
          ZIP_FILE="arm64-v8a.zip"
        elif [[ "${{ needs.triage.outputs.architecture }}" == "x86" ]]; then
          ZIP_FILE="x86.zip"
        elif [[ "${{ needs.triage.outputs.architecture }}" == "x86_64" ]]; then
          ZIP_FILE="x86_64.zip"
        else
          echo "Unknown architecture(${{ needs.triage.outputs.architecture }})"
          exit 1
        fi
        curl -Of https://artifacts-store.openhippy.com/hippy/android/hippy-common/${{ needs.triage.outputs.version }}/symbols/$ZIP_FILE
        mkdir symbols
        unzip -d symbols $ZIP_FILE
        rm $ZIP_FILE
        echo "success=1" >> $GITHUB_OUTPUT
    - uses: actions/github-script@v6.3.3
      if: steps.symbols_fetched.result == 'success' && !steps.symbols_fetched.outputs.success
      with:
        github-token: ${{ steps.get-token.outputs.token }}
        script: |
          const { owner, repo } = context.repo;
          const { issues } = github.rest;
          const util = require('util');

          await issues.createComment({
            owner,
            repo,
            issue_number: ${{ github.event.issue.number }},
            body: util.format(process.env.fetch_symbol_failed_message, '${{ needs.triage.outputs.version }}', '${{ needs.triage.outputs.architecture }}')
          });
    - name: Translates
      if: steps.symbols_fetched.outputs.success
      uses: actions/github-script@v6.3.3
      with:
        github-token: ${{ steps.get-token.outputs.token }}
        script: |
          const { owner, repo } = context.repo;
          const { issues, reactions } = github.rest;
          const { execSync } = require('child_process');
          const path = require('path');
          const fs = require('fs');
          const os = require('os');
          const util = require('util');

          const bin = path.join(process.env['ANDROID_NDK_HOME'], 'toolchains/llvm/prebuilt/linux-x86_64/bin/llvm-addr2line');
          function addr2line(lib, pc) {
            const [ func, source ] = execSync(`${bin} -C -f -e ${lib} ${pc}`, { encoding: 'utf8' }).split(os.EOL);
            return { func, source };
          }

          const backtrace = JSON.parse('${{ steps.backtrace_parsed.outputs.backtrace }}');

          let body;
          let error;
          try {
            const symbols = fs.readdirSync('symbols');
            const formatted = backtrace.map(stack => {
              const lib = path.basename(stack.file);
              if (symbols.includes(lib)) {
                const { func, source} = addr2line(path.join("symbols", lib), stack.pc);
                return {
                  pc: stack.pc,
                  file: stack.file,
                  func,
                  source
                }
              }

              return stack;
            }).map(({ pc, func, file, source }, i) => {
              return `#${i} PC ${pc}  ${file} ${func ? `(${func})` : ''}${source ? ` [${source}]` : ''}`;
            });

            body = util.format(process.env.translate_success_message, [`translated backtrace:`, ...formatted.map(line => `  ${line}`)].join(os.EOL));
          } catch (e) {
            body = process.env.translate_failed_message;
            error = e;
          }

          const { data: { id } } = await issues.createComment({
            owner,
            repo,
            issue_number: ${{ github.event.issue.number }},
            body
          });

          if (error) {
            throw error;
          }

          await reactions.createForIssueComment({
            owner,
            repo,
            comment_id: id,
            content: 'eyes'
          });

name: '[gh] pull request auto merger'

on:
  workflow_run:
    workflows:
      - \[gh\] pull request review
    types: [ completed ]

env:
 GREETINGS_MESSAGE: ':tada: It seems that this pull request has been approved by all required reviewers.'
 AUTO_MERGE_MESSAGE: As it only contains one normal commit, I will rebase and merge it automatically via add `action(rebase-merge)` label.
 MANUAL_MERGE_MESSAGE: But it has more than one normal commit, I will notify admin team member to merge it manually, please wait a moment.
 MERGE_SHA_MESSAGE: |
  <details>

    * SHA: {0}

  </details>

jobs:
  call_get_workflow_output:
    if: github.repository == 'Tencent/Hippy' && github.event.action == 'completed' && github.event.workflow_run.conclusion == 'success'
    uses: ./.github/workflows/reuse_get_workflow_output.yml
    with:
      workflow_run: ${{ github.event.workflow_run.id }}

  get_decision:
    needs: call_get_workflow_output
    runs-on: ubuntu-latest
    outputs:
      review_decision: ${{ steps.decision.outputs.review_decision }}
      pull_request_number: ${{ steps.parse_workflow_output.outputs.pull_request_number }}
      pull_request_title: ${{ steps.parse_workflow_output.outputs.pull_request_title }}
      pull_request_url: ${{ steps.parse_workflow_output.outputs.pull_request_url }}
      pull_request_sha: ${{ steps.parse_workflow_output.outputs.pull_request_sha }}
    steps:
    - name: Parse
      id: parse_workflow_output
      env:
        RAW: ${{ needs.call_get_workflow_output.outputs.raw }}
      shell: python
      run: |
        import json
        import os

        raw = os.getenv("RAW")
        data = json.loads(raw)
        with open(os.getenv("GITHUB_OUTPUT"), 'w', encoding='utf-8') as file:
          file.write("review_state=%s\n" % data["review"]["state"])
          file.write("pull_request_number=%s\n" % data["pull_request"]["number"])
          file.write("pull_request_title=%s\n" % data["pull_request"]["title"])
          file.write("pull_request_url=%s\n" % data["pull_request"]["html_url"])
          file.write("pull_request_sha=%s\n" % data["pull_request"]["head"]["sha"])
    - name: Decision
      id: decision
      if: steps.parse_workflow_output.outputs.review_state == 'approved'
      uses: actions/github-script@v6
      with:
        script: |
          const fs = require('fs');
          const os = require('os');

          const query = `query($owner:String!, $repo:String!, $number:Int!) {
              repository(name: $repo, owner: $owner) {
                pullRequest(number: $number) {
                  reviewDecision
                }
              }
          }`;
          const variables = {
            ...context.repo,
            number: ${{ steps.parse_workflow_output.outputs.pull_request_number }}
          };
          const { repository: { pullRequest: { reviewDecision } } } = await github.graphql(query, variables);
          if (reviewDecision === 'APPROVED' || !reviewDecision) {
            fs.appendFileSync(process.env.GITHUB_OUTPUT, `review_decision=APPROVED${os.EOL}`, { encoding: 'utf8' });
          }

  call_classify_commits:
    needs: get_decision
    if: needs.get_decision.outputs.review_decision == 'APPROVED'
    uses: ./.github/workflows/reuse_classify_commits.yml
    with:
      pull_request_number: ${{ fromJSON(needs.get_decision.outputs.pull_request_number) }}

  auto_merge:
    needs: [ get_decision, call_classify_commits ]
    if: needs.call_classify_commits.outputs.normal_commits_count == 1
    runs-on: ubuntu-latest
    steps:
    - name: Token
      uses: navikt/github-app-token-generator@v1
      id: get-token
      with:
        private-key: ${{ secrets.BOT_APP_KEY }}
        app-id: ${{ secrets.BOT_APP_ID }}
    - name: Auto
      uses: actions/github-script@v6
      env:
        COMMENT_MESSAGE: ${{ env.GREETINGS_MESSAGE }} ${{ env.AUTO_MERGE_MESSAGE }} ${{ format(env.MERGE_SHA_MESSAGE, needs.get_decision.outputs.pull_request_sha) }}
      with:
        github-token: ${{ steps.get-token.outputs.token }}
        script: |
          const { issues } = github.rest;

          const comments = await github.paginate(issues.listComments, {
            ...context.repo,
            per_page: 100,
            issue_number: ${{ needs.get_decision.outputs.pull_request_number }}
          });
          if (comments.some((comment) => comment.body.includes(process.env.COMMENT_MESSAGE))) {
            return;
          }

          const p = [];

          p.push(issues.addLabels({
            ...context.repo,
            issue_number: ${{ needs.get_decision.outputs.pull_request_number }},
            labels: [ 'action(rebase-merge)' ]
          }));

          p.push(issues.createComment({
            ...context.repo,
            issue_number: ${{ needs.get_decision.outputs.pull_request_number }},
            body: process.env.COMMENT_MESSAGE
          }));

          await Promise.all(p);

  manual_merge:
    needs: [ get_decision, call_classify_commits ]
    if: needs.call_classify_commits.outputs.normal_commits_count > 1 || !needs.call_classify_commits.outputs.normal_commits_count
    runs-on: ubuntu-latest
    steps:
    - name: Token
      uses: navikt/github-app-token-generator@v1
      id: get-token
      with:
        private-key: ${{ secrets.BOT_APP_KEY }}
        app-id: ${{ secrets.BOT_APP_ID }}
    - name: Manual
      uses: actions/github-script@v6
      env:
        WECHAT_WORK_MESSAGE: |
          [#${{ needs.get_decision.outputs.pull_request_number }}](${{ needs.get_decision.outputs.pull_request_url }}) pull request is met merge requirements.
          > ${{ needs.get_decision.outputs.pull_request_title }}
          > <font color="warning">%s</font> normal commits ahead
        COMMENT_MESSAGE: ${{ env.GREETINGS_MESSAGE }} ${{ env.MANUAL_MERGE_MESSAGE }} ${{ format(env.MERGE_SHA_MESSAGE, needs.get_decision.outputs.pull_request_sha) }}
      with:
        github-token: ${{ steps.get-token.outputs.token }}
        script: |
          const util = require('util');
          const { issues } = github.rest;

          const comments = await github.paginate(issues.listComments, {
            ...context.repo,
            per_page: 100,
            issue_number: ${{ needs.get_decision.outputs.pull_request_number }}
          });
          if (comments.some((comment) => comment.body.includes(process.env.COMMENT_MESSAGE))) {
            return;
          }

          const p = [];

          p.push(issues.createComment({
            ...context.repo,
            issue_number: ${{ needs.get_decision.outputs.pull_request_number }},
            body: process.env.COMMENT_MESSAGE
          }));

          p.push(github.request("POST ${{ secrets.WECHAT_WORK_BOT_WEBHOOK }}", {
            headers: {
              "content-type": "application/json"
            },
            data: {
              chatid: "${{ secrets.WECHAT_WORK_ADMIN_CHAT_ID }}",
              msgtype: "markdown",
              markdown: {
                content: util.format(process.env.WECHAT_WORK_MESSAGE, (Number.parseInt("${{ needs.call_classify_commits.outputs.normal_commits_count }}") || Infinity).toLocaleString()),
                attachments: [{
                  callback_id: "merge",
                  actions: [{
                    name: "merge_btn",
                    text: "Mark as Merged",
                    type: "button",
                    value: "Mark as Merged",
                    replace_text: "Already merged",
                    border_color: "2c974b",
                    text_color: "2c974b"
                  }, {
                    name: "ignore_btn",
                    text: "Mark as Ignored",
                    type: "button",
                    value: "Mark as Ignored",
                    replace_text: "Already ignored",
                    border_color: "6e7781",
                    text_color: "6e7781"
                  }]
                }]
              }
            }
          }));

          await Promise.all(p);

name: '[gh] pull request auto updater'

on:
  pull_request_target:
    types:
      - auto_merge_enabled
  push:

jobs:
  up_to_date:
    if: github.repository == 'Tencent/Hippy'
    runs-on: ubuntu-latest
    steps:
    - name: Updater
      uses: actions/github-script@v6.3.3
      with:
        # Because the Github App Token, Github Token, and Fine-grained PAT
        # cannot obtain the permission to update the workflow files in the head branch,
        # so use classic PAT to avoid failures caused by modification of workflow files.
        # TODO: use Github App Token or Github Token if permission is granted in the future.
        github-token: ${{ secrets.BOT_PAT }}
        script: |
          const { pulls, repos } = github.rest;

          let pull_requests;
          switch (context.eventName) {
            case 'push': {
              pull_requests = (await github.paginate(pulls.list, {
                per_page: 100,
                state: 'open',
                base: '${{ github.ref_name }}',
                ...context.repo
              })).filter(pull => pull.draft === false && pull.auto_merge);
              break;
            }
            case 'pull_request_target': {
              const { pull_request } = context.payload;
              if (pull_request.draft === true) {
                return;
              }
              pull_requests = [pull_request];
              break;
            }
            default: {
              throw new Error(`Unsupported event name: ${context.eventName}`);
              break;
            }
          }

          await Promise.all(
            pull_requests.map(pull =>
              repos.compareCommitsWithBasehead({
                ...context.repo,
                basehead: `${pull.base.label}...${pull.head.label}`,
              }).then(({ data: comparison }) => {
                if (comparison.behind_by > 0) {
                  return pulls.updateBranch({
                    ...context.repo,
                    pull_number: pull.number
                  }).catch(error => console.error(error));
                }
              })
            )
          );

name: '[gh] pull request guide'

on:
  pull_request_target:
    branches:
      - master
      - main
      - v3.0-dev
      - v3.0
    types:
      - opened
  issue_comment:
    types:
      - created

jobs:
  pull_request_greetings:
    if: github.event.action == 'opened' && github.repository == 'Tencent/Hippy'
    runs-on: ubuntu-latest
    env:
      MESSAGE: |
        Hi, @${{ github.event.sender.login }}. Thanks for your PR! :clap:

        :label: You can leave a comment in this PR with **`#help`** tag when you need help (e.g. some status checks run failed due to internal issue), admin team members will help asap.
    steps:
    - name: Token
      uses: navikt/github-app-token-generator@v1
      id: get-token
      with:
        private-key: ${{ secrets.BOT_APP_KEY }}
        app-id: ${{ secrets.BOT_APP_ID }}
    - name: Greetings
      uses: actions/github-script@v6.1.0
      with:
        github-token: ${{ steps.get-token.outputs.token }}
        script: |
          const { owner, repo } = context.repo;
          const { pull_request } = context.payload;
          const { issues } = github.rest;

          await issues.createComment({
            owner,
            repo,
            issue_number: pull_request.number,
            body: process.env.MESSAGE,
          });

  pull_request_help_needed:
    if: github.event.sender.type == 'User' && github.event.issue.pull_request && contains(github.event.comment.body, '#help') && github.repository == 'Tencent/Hippy'
    runs-on: ubuntu-latest
    env:
      MESSAGE: |
        [${{ github.event.sender.login }}](https://github.com/${{ github.event.sender.login }}) needs help on [#${{ github.event.issue.number }}](${{ github.event.comment.html_url }}) pull request.
        > [${{ github.event.comment.html_url }}](${{ github.event.comment.html_url }})
        > ${{ github.event.comment.body }}
    steps:
    - name: Token
      uses: navikt/github-app-token-generator@v1
      id: get-token
      with:
        private-key: ${{ secrets.BOT_APP_KEY }}
        app-id: ${{ secrets.BOT_APP_ID }}
    - name: Action
      uses: actions/github-script@v6.3.3
      with:
        github-token: ${{ steps.get-token.outputs.token }}
        script: |
          const { owner, repo } = context.repo;
          const { issue } = context.payload;
          const { issues } = github.rest;

          const p = [];

          p.push(issues.addLabels({
            issue_number: issue.number,
            labels: [ 'need: help' ],
            ...context.repo,
          }));

          p.push(github.request("POST ${{ secrets.WECHAT_WORK_BOT_WEBHOOK }}", {
            headers: {
              "content-type": "application/json"
            },
            data: {
              chatid: "${{ secrets.WECHAT_WORK_ADMIN_CHAT_ID }}",
              msgtype: "markdown",
              markdown: {
                content: process.env.MESSAGE,
                attachments: [{
                  callback_id: "help_needed",
                  actions: [{
                    name: "help_needed_btn",
                    text: "Mark as Resolved",
                    type: "button",
                    value: "Mark as Resolved",
                    replace_text: "Already resolved",
                    border_color: "2c974b",
                    text_color: "2c974b"
                  }]
                }]
              }
            }
          }));

          await Promise.all(p);

name: '[gh] pull review notification'

on:
  pull_request_target:
    types: [ review_requested ]
  workflow_run:
    workflows:
      - \[gh\] pull request review
    types: [ completed ]
  workflow_dispatch:
  schedule:
    # Run every day at 23:30 UTC(07:30 UTC+08:00).
    - cron: '30 23 * * *'

jobs:
  request_notification:
    if: github.repository == 'Tencent/Hippy' && github.event.action == 'review_requested' && github.event.requested_reviewer.type == 'User'
    runs-on: ubuntu-latest
    steps:
    - name: Notice
      uses: actions/github-script@v6.3.3
      env:
        MESSAGE: |
          [${{ github.event.sender.login }}](https://github.com/${{ github.event.sender.login }}) requested your review on [#${{ github.event.pull_request.number }}](${{ github.event.pull_request.html_url }}) pull request.
          > ${{ github.event.pull_request.title }}
          > [${{ github.event.pull_request.html_url }}](${{ github.event.pull_request.html_url }})
          > [%s changed files](${{ github.event.pull_request.html_url }}/files) with <font color="info">%s additions</font> and <font color="warning">%s deletions</font>

          <@%s>
        WECHAT_WORK_USERS: ${{ secrets.WECHAT_WORK_USERS }}
      with:
        script: |
          const { format } = require("util");

          const userid = JSON.parse(process.env.WECHAT_WORK_USERS)["${{ github.event.requested_reviewer.login }}"];
          if (!userid) {
            console.log("The reviewer ${{ github.event.requested_reviewer.login }} not found in secrets.WECHAT_WORK_USERS");
            return;
          }

          await github.request("POST ${{ secrets.WECHAT_WORK_BOT_WEBHOOK }}", {
            headers: {
              "content-type": "application/json"
            },
            data: {
              chatid: "${{ secrets.WECHAT_WORK_CHAT_ID }}",
              visible_to_user: userid,
              msgtype: "markdown",
              markdown: {
                content: format(process.env.MESSAGE, (${{ github.event.pull_request.changed_files }}).toLocaleString(), (${{ github.event.pull_request.additions }}).toLocaleString(), (${{ github.event.pull_request.deletions }}).toLocaleString(), userid),
                attachments: [{
                  callback_id: "review",
                  actions: [{
                    name: "review_btn",
                    text: "Mark as Reviewed",
                    type: "button",
                    value: "Mark as Reviewed",
                    replace_text: "Already reviewed",
                    border_color: "2c974b",
                    text_color: "2c974b"
                  }, {
                    name: "ignore_btn",
                    text: "Mark as Ignored",
                    type: "button",
                    value: "Mark as Ignored",
                    replace_text: "Already ignored",
                    border_color: "6e7781",
                    text_color: "6e7781"
                  }]
                }]
              }
            }
          });

  call_get_workflow_output:
    if: github.repository == 'Tencent/Hippy' && github.event.action == 'completed' && github.event.workflow_run.conclusion == 'success'
    uses: ./.github/workflows/reuse_get_workflow_output.yml
    with:
      workflow_run: ${{ github.event.workflow_run.id }}

  changes_requested_comment:
    needs: call_get_workflow_output
    if: needs.call_get_workflow_output.outputs.action == 'submitted'
    runs-on: ubuntu-latest
    env:
      MESSAGE: |
        Hi, @{0}, I noticed that our reviewers requested changes to this pull request.
        When you're done, **click the `Re-request review` button in the right sidebar(shown below)** to notify the reviewer.
        ![Re-request review button in the right sidebar](https://docs.github.com/assets/cb-4714/images/help/pull_requests/request-re-review.png)
    steps:
    - name: Parse
      id: parse_workflow_output
      env:
        RAW: ${{ needs.call_get_workflow_output.outputs.raw }}
      shell: python
      run: |
        import json
        import os

        raw = os.getenv("RAW")
        data = json.loads(raw)
        with open(os.getenv("GITHUB_OUTPUT"), 'w', encoding='utf-8') as file:
          file.write("review_state=%s\n" % data["review"]["state"])
          file.write("pull_request_number=%s\n" % data["pull_request"]["number"])
          file.write("pull_request_user=%s\n" % data["pull_request"]["user"]["login"])
    - name: Find
      id: find_comment
      if: steps.parse_workflow_output.outputs.review_state == 'changes_requested'
      uses: peter-evans/find-comment@v2.1.0
      with:
        issue-number: ${{ steps.parse_workflow_output.outputs.pull_request_number }}
        body-includes: ${{ format(env.MESSAGE, steps.parse_workflow_output.outputs.pull_request_user) }}
    - name: Token
      id: get-token
      if: steps.find_comment.outputs.comment-id == '' && steps.parse_workflow_output.outputs.review_state == 'changes_requested'
      uses: navikt/github-app-token-generator@v1
      with:
        private-key: ${{ secrets.BOT_APP_KEY }}
        app-id: ${{ secrets.BOT_APP_ID }}
    - name: Comment
      uses: peter-evans/create-or-update-comment@v2
      if: steps.get-token.outputs.token != ''
      with:
        token: ${{ steps.get-token.outputs.token }}
        issue-number: ${{ steps.parse_workflow_output.outputs.pull_request_number }}
        body: ${{ format(env.MESSAGE, steps.parse_workflow_output.outputs.pull_request_user) }}
        reactions: eyes

  requested_reviewers_notification:
    if: github.event_name == 'schedule' || github.event_name == 'workflow_dispatch'
    runs-on: ubuntu-latest
    steps:
    - name: Notice
      uses: actions/github-script@v6.3.3
      env:
        WECHAT_WORK_USERS: ${{ secrets.WECHAT_WORK_USERS }}
      with:
        script: |
          const { pulls } = github.rest;
          const os = require('os');

          const pull_requests = (await github.paginate(pulls.list, {
            per_page: 100,
            state: 'open',
            ...context.repo
          })).filter(pull => pull.draft === false);

          const requested_reviewers = await Promise.all(
            pull_requests.map(
              pull => pulls.listRequestedReviewers({
                per_page: 100,
                pull_number: pull.number,
                ...context.repo
              }).then(({ data }) => data)
            )
          );

          if (pull_requests.length !== requested_reviewers.length) {
            throw new Error("The length of pull_requests and requested_reviewers is not equal");
          }

          const wechat_work_users = JSON.parse(process.env.WECHAT_WORK_USERS);
          const notification_users = {};

          pull_requests.forEach((pull, index) => {
            requested_reviewers[index].users.forEach(reviewer => {
              if (reviewer.type === 'User') {
                const user_id = wechat_work_users[reviewer.login];
                if (user_id) {
                  (notification_users[user_id] ||= []).push(pull);
                }
              }
            });
          });

          await Promise.all(Object.entries(notification_users).map(([user_id, pulls]) => {
            const content = [];
            content.push(`<font color="warning">${pulls.length}</font> pull requests are waiting on your review.`);
            content.push(...pulls.map(pull => `> [#${pull.number}](${pull.html_url}) ${pull.title}`));
            content.push('');
            content.push(`<@${user_id}>`);

            return github.request("POST ${{ secrets.WECHAT_WORK_BOT_WEBHOOK }}", {
              headers: {
                "content-type": "application/json"
              },
              data: {
                chatid: "${{ secrets.WECHAT_WORK_CHAT_ID }}",
                visible_to_user: user_id,
                msgtype: "markdown",
                markdown: {
                  content: content.join(os.EOL)
                }
              }
            });
          }));

name: '[gh] self-hosted runners monitor'

on:
  workflow_dispatch:
  schedule:
    # Run every 30th minute.
    - cron: '*/30 * * * *'

jobs:
  runners_monitor:
    if: github.repository == 'Tencent/Hippy'
    runs-on: ubuntu-latest
    env:
      cache_file: /tmp/gh_runners_monitor.data
      cache_key: gh_runners_monitor
    steps:
    - name: Token
      uses: navikt/github-app-token-generator@v1
      id: get-token
      with:
        private-key: ${{ secrets.BOT_APP_KEY }}
        app-id: ${{ secrets.BOT_APP_ID }}
    - name: Check
      id: check
      uses: actions/github-script@v6.3.3
      with:
        github-token: ${{ steps.get-token.outputs.token }}
        script: |
          const { actions } = github.rest;
          const os = require('os');
          const fs = require('fs');

          const runners = await github.paginate(actions.listSelfHostedRunnersForRepo, {
            per_page: 100,
            ...context.repo
          });
          const offline_runners = runners.filter(runner => runner.status === 'offline');

          if (offline_runners.length > 0) {
            fs.appendFileSync(process.env.GITHUB_OUTPUT, `total_runners=${runners.length}${os.EOL}`, { encoding: 'utf8' });
            fs.appendFileSync(process.env.GITHUB_OUTPUT, `offline_runners=${JSON.stringify(offline_runners)}${os.EOL}`, { encoding: 'utf8' });
          }
    - name: Cache
      if: steps.check.outputs.offline_runners
      uses: actions/cache@v3
      env:
        prefix: gh_runners_monitor
      with:
        path: ${{ env.cache_file }}
        key: ${{ env.prefix }}-${{ github.run_id }}
        restore-keys: ${{ env.prefix }}
    - name: Notification
      if: steps.check.outputs.offline_runners
      uses: actions/github-script@v6.3.3
      env:
        offline_runners: ${{ steps.check.outputs.offline_runners }}
      with:
        script: |
          const fs = require('fs');
          const os = require('os');

          const offline_runners = JSON.parse(process.env.offline_runners);
          if (offline_runners.length === 0) {
            throw new Error('offline_runners is empty');
          }

          const message = [
            `<font color="warning">${offline_runners.length}/${{ steps.check.outputs.total_runners }}</font> self-hosted runners are offline.`,
            ...offline_runners.map(runner => `> ${runner.name}`)
          ].join(os.EOL);

          try {
            const stored_data = JSON.parse(fs.readFileSync(process.env.cache_file, { encoding: 'utf8'}));
            if (stored_data.message === message && Date.now() - stored_data.timestamp < 6_60_60_000 /* every 6th hour */) {
              return;
            }
          } catch(e) {}

          await github.request("POST ${{ secrets.WECHAT_WORK_BOT_WEBHOOK }}", {
            headers: {
              "content-type": "application/json"
            },
            data: {
              chatid: "${{ secrets.WECHAT_WORK_ADMIN_CHAT_ID }}",
              msgtype: "markdown",
              markdown: {
                content: message
              }
            }
          });

          fs.writeFileSync(process.env.cache_file, JSON.stringify({
            message,
            timestamp: Date.now()
          }), { encoding: 'utf8' });

name: '[gh] webhook retrier'

on:
  workflow_dispatch:
  schedule:
    # Run every 10th minute.
    - cron: '*/10 * * * *'

jobs:
  webhook_retrier:
    if: github.repository == 'Tencent/Hippy'
    runs-on: ubuntu-latest
    steps:
    - name: Action
      uses: actions/github-script@v6
      with:
        github-token: ${{ secrets.BOT_PAT }}
        script: |
          const { repos } = github.rest;
          const os = require('os');
          const fs = require('fs');

          const per_page = 100;

          const hooks = (await github.paginate(repos.listWebhooks, {
            per_page,
            ...context.repo
          })).filter((hook) => hook.last_response && hook.active);

          const retriedDeliveries = (await Promise.all(hooks.map((hook) => repos.listWebhookDeliveries({
            per_page,
            ...context.repo,
            hook_id: hook.id
          })))).map(({ data: deliveries }) => {
            const indexed = {};
            const failedList = new Set();
            deliveries.forEach((delivery) => {
              (indexed[delivery.guid] ||= []).push(delivery);
              if (delivery.status != 'OK') {
                failedList.add(delivery.guid);
              }
            });

            return Array.from(failedList).filter((guid) => {
              const failedGroup = indexed[guid];
              return failedGroup.every((delivery) => delivery.status != 'OK') && failedGroup.length <= 4; // maximum attempts(origin included)
            }).map((guid) => indexed[guid][0]);
          });

          (await Promise.all(retriedDeliveries.map((deliveries, hooksIndex) =>
            Promise.allSettled(deliveries.map((delivery) =>
              repos.redeliverWebhookDelivery({
                ...context.repo,
                hook_id: hooks[hooksIndex].id,
                delivery_id: delivery.id
              })
            ))
          ))).forEach((results, hooksIndex) => {
            if (results.length > 0) {
              const summary = [];

              const hook = hooks[hooksIndex];
              summary.push(`## ${hook.config.url} (#${hook.id})`);
              summary.push('| guid | event | action | redelivery |');
              summary.push('| ---- | ----- | ------ | ---------- |');
              results.forEach((result, deliveriesIndex) => {
                const delivery = retriedDeliveries[hooksIndex][deliveriesIndex];
                summary.push(`| ${delivery.guid} | ${delivery.event} | ${delivery.action || ''} | ${result.status === 'fulfilled' ? ':white_check_mark:' : ':x:'} |`);
              });
              summary.push(os.EOL);

              fs.appendFileSync(process.env.GITHUB_STEP_SUMMARY, summary.join(os.EOL), { encoding: 'utf8' });
            }
          });

name: '[reuse] approve checks run'

on:
  workflow_call:
    inputs:
      pull_request_number:
        description: 'Pull request number'
        required: true
        type: number
      pull_request_head_sha:
        description: 'Pull request head sha'
        required: true
        type: string
      requied_privilege_escalation:
        description: 'Privilege escalation required'
        required: false
        default: false
        type: boolean
    outputs:
      pull_request_number:
        description: 'Pull request number'
        value: ${{ inputs.pull_request_number }}
      pull_request_head_sha:
        description: 'Pull request head sha'
        value: ${{ inputs.pull_request_head_sha }}
      action_required:
        description: "Checks require approve"
        value: ${{ jobs.approve_checks_run.outputs.action_required }}
      included_risk_files:
        description: "Contains risk files"
        value: ${{ jobs.approve_checks_run.outputs.included_risk_files }}

jobs:
  approve_checks_run:
    runs-on: ubuntu-latest
    outputs:
      included_risk_files: ${{ steps.action.outputs.included_risk_files }}
      action_required: ${{ steps.action.outputs.action_required }}
      workflow_runs: ${{ steps.action.outputs.workflow_runs }}
    steps:
    - name: Action
      id: action
      uses: actions/github-script@v6.3.3
      with:
        script: |
          const { actions, pulls } = github.rest;
          const fs = require('fs');
          const os = require('os');

          const per_page = 100;

          let workflow_runs = (await github.paginate(actions.listWorkflowRunsForRepo, {
            per_page,
            event: 'pull_request',
            status: 'action_required',
            ...context.repo
          })).filter(workflow_run => workflow_run.head_sha === '${{ inputs.pull_request_head_sha }}').map(workflow_run => workflow_run.id);
          if (workflow_runs.length === 0) {
            fs.appendFileSync(process.env.GITHUB_OUTPUT, `action_required=false${os.EOL}`, { encoding: 'utf8' });
            return;
          }
          fs.appendFileSync(process.env.GITHUB_OUTPUT, `action_required=true${os.EOL}`, { encoding: 'utf8' });
          fs.appendFileSync(process.env.GITHUB_OUTPUT, `workflow_runs=${JSON.stringify(workflow_runs)}${os.EOL}`, { encoding: 'utf8' });

          const [includedRiskFiles] = await github.paginate(pulls.listFiles, {
            per_page,
            pull_number: ${{ inputs.pull_request_number }},
            ...context.repo
          }, ({ data: files }, done) => {
            if (files.some(file => file.filename.startsWith('.github/workflows'))) {
              done();
              return [true];
            }
            return [];
          });
          fs.appendFileSync(process.env.GITHUB_OUTPUT, `included_risk_files=${includedRiskFiles}${os.EOL}`, { encoding: 'utf8' });

          if (!includedRiskFiles) {
            await Promise.all(workflow_runs.map(workflow_run => actions.approveWorkflowRun({
              run_id: workflow_run,
              ...context.repo
            })));
          }

  approve_checks_run_privileged:
    needs: approve_checks_run
    if: needs.approve_checks_run.outputs.included_risk_files == 'true' && inputs.requied_privilege_escalation == true
    environment: github-actions-privileged
    runs-on: ubuntu-latest
    steps:
    - name: Action
      id: action
      env:
        workflow_runs: ${{ needs.approve_checks_run.outputs.workflow_runs }}
      uses: actions/github-script@v6.1.0
      with:
        script: |
          const { actions } = github.rest;

          const workflow_runs = JSON.parse(process.env.workflow_runs);
          await Promise.all(workflow_runs.map(workflow_run => actions.approveWorkflowRun({
            run_id: workflow_run,
            ...context.repo
          })));

name: '[reuse] classify commits'

on:
  workflow_call:
    inputs:
      pull_request_number:
        description: 'Pull request number'
        required: true
        type: number
    outputs:
      merge_commits_sha:
        description: 'Merge commits sha'
        value: ${{ jobs.classify_commits.outputs.merge_commits_sha }}
      merge_commits_count:
        description: 'Merge commits count'
        value: ${{ jobs.classify_commits.outputs.merge_commits_count }}
      normal_commits_sha:
        description: 'Normal commits sha'
        value: ${{ jobs.classify_commits.outputs.normal_commits_sha }}
      normal_commits_count:
        description: 'Normal commits count'
        value: ${{ jobs.classify_commits.outputs.normal_commits_count }}

jobs:
  classify_commits:
    runs-on: ubuntu-latest
    outputs:
      merge_commits_sha: ${{ steps.action.outputs.merge_commits_sha }}
      merge_commits_count: ${{ steps.action.outputs.merge_commits_count }}
      normal_commits_sha: ${{ steps.action.outputs.normal_commits_sha }}
      normal_commits_count: ${{ steps.action.outputs.normal_commits_count }}
    steps:
    - name: Action
      id: action
      uses: actions/github-script@v6.3.3
      with:
        script: |
          const { pulls } = github.rest;
          const fs = require('fs');
          const os = require('os');

          const commits = (await github.paginate(pulls.listCommits, {
            per_page: 100,
            pull_number: ${{ inputs.pull_request_number }},
            ...context.repo
          }));

          if (commits.length >= 250) { // exceeded maximum of 250 commits per pull request
            return;
          }

          const merge_commits = [];
          const normal_commits = [];
          commits.forEach(commit => commit.parents.length > 1 ? merge_commits.push(commit.sha) : normal_commits.push(commit.sha));

          fs.appendFileSync(process.env.GITHUB_OUTPUT, `merge_commits_sha=${JSON.stringify(merge_commits)}${os.EOL}`, { encoding: 'utf8' });
          fs.appendFileSync(process.env.GITHUB_OUTPUT, `merge_commits_count=${merge_commits.length}${os.EOL}`, { encoding: 'utf8' });
          fs.appendFileSync(process.env.GITHUB_OUTPUT, `normal_commits_sha=${JSON.stringify(normal_commits)}${os.EOL}`, { encoding: 'utf8' });
          fs.appendFileSync(process.env.GITHUB_OUTPUT, `normal_commits_count=${normal_commits.length}${os.EOL}`, { encoding: 'utf8' });

name: '[reuse] get workflow output'

on:
  workflow_call:
    inputs:
      workflow_run:
        description: 'A workflow run id'
        required: true
        type: number
    outputs:
      action:
        description: "A workflow run action field"
        value: ${{ jobs.get_workflow_output.outputs.action }}
      sender:
        description: "A workflow run sender.login field"
        value: ${{ jobs.get_workflow_output.outputs.sender }}
      raw:
        description: "A workflow run raw output"
        value: ${{ jobs.get_workflow_output.outputs.raw }}

jobs:
  get_workflow_output:
    runs-on: ubuntu-latest
    outputs: 
      action: ${{ steps.parse.outputs.action }}
      sender: ${{ steps.parse.outputs.sender }}
      raw: ${{ steps.parse.outputs.raw }}
    steps:
    - name: Pull
      uses: actions/github-script@v6.3.3
      with:
        script: |
          const { actions } = github.rest;
          const fs = require('fs');

          const { data: { artifacts } } = await actions.listWorkflowRunArtifacts({
             run_id: ${{ inputs.workflow_run }},
             ...context.repo
          });
          const [ artifact ] = artifacts.filter((artifact) => {
            return artifact.name == "data"
          });
          if (!artifact) {
            throw new Error("Missing data artifact generated in parent workflow(${{ inputs.workflow_run }})");
          }

          const download = await actions.downloadArtifact({
             artifact_id: artifact.id,
             archive_format: 'zip',
             ...context.repo
          });
          fs.writeFileSync(`${process.env.GITHUB_WORKSPACE}/data.zip`, Buffer.from(download.data));
    - name: Parse
      id: parse
      shell: python
      run: |
        import zipfile
        import json
        import os

        with zipfile.ZipFile("data.zip", "r") as zip_ref:
          buf = zip_ref.read("data")
          data = json.loads(buf)
          with open(os.getenv("GITHUB_OUTPUT"), 'w', encoding='utf-8') as file:
            file.write("action=%s\n" % data["action"])
            file.write("sender=%s\n" % data["sender"]["login"])
            file.write("raw=%s\n" % json.dumps(data))

name: "[security] codeql analyses"

on:
  push:
    branches:
      - v3.0-dev
      - v3.0
  pull_request:
    branches:
      - v3.0-dev
      - v3.0
  schedule:
    # Run every day at 20:00 UTC(04:00 UTC+08:00).
    - cron: '0 20 * * *'
  workflow_dispatch:

concurrency:
  group: ${{ github.workflow }}-${{ github.head_ref || github.run_id }}
  cancel-in-progress: true

permissions:
  actions: read
  contents: read
  security-events: write

jobs:
  triage:
    runs-on: ubuntu-latest
    outputs:
      languages: ${{ steps.action.outputs.languages }}
      group: ${{ steps.action.outputs.group }}
    steps:
    - name: Action
      id: action
      uses: actions/github-script@v6.3.3
      with:
        script: |
          const { pull_request } = context.payload;
          const { pulls } = github.rest;
          const path = require('path');
          const fs = require('fs');
          const os = require('os');

          // Ref: https://codeql.github.com/docs/codeql-overview/supported-languages-and-frameworks/#languages-and-compilers
          const mappings  = {
            "cpp": [".cpp", ".c++", ".cxx", ".hpp", ".hh", ".h++", ".hxx", ".c", ".cc", ".h"],
            // Use only 'java' to analyze code written in Java, Kotlin or both
            "java": [".java", ".kt"], // written in Java, Kotlin or both
            // Use only 'javascript' to analyze code written in JavaScript, TypeScript or both
            "javascript": [".ts", ".tsx", ".js", ".jsx", ".mjs", ".es", ".es6", ".htm", ".html", ".xhtm", ".xhtml", ".vue", ".hbs", ".ejs", ".njk", ".json", ".yaml", ".yml", ".raml", ".xml"]
          };

          const languages = new Set();

          if (pull_request) {
            try {
              const files = await github.paginate(pulls.listFiles, {
                ...context.repo,
                per_page: 100,
                pull_number: pull_request.number
              });

              if (files.length > 3_000) { // The paginated response include a maximum of 3000 files
                Object.keys(mappings).forEach(languages.add, languages);
              } else {
                files.forEach(({ filename }) => {
                  const ext = path.extname(filename);
                  Object.keys(mappings).some((name) => {
                    if (mappings[name].includes(ext)) {
                      languages.add(name);
                      return true;
                    }
                    return false;
                  });
                });
              }
            } catch (e) {
              console.error(e);
              Object.keys(mappings).forEach(languages.add, languages);
            }
          } else {
            Object.keys(mappings).forEach(languages.add, languages);
          }

          if (languages.size > 0) {
            fs.appendFileSync(process.env.GITHUB_OUTPUT, `languages=${JSON.stringify(Array.from(languages))}${os.EOL}`, { encoding: 'utf8' });
          }

  analyze:
    needs: triage
    if: needs.triage.outputs.languages
    runs-on: ${{ github.repository == 'Tencent/Hippy' && fromJson('[''self-hosted'', ''linux'', ''codeql'']') || 'ubuntu-latest' }}
    container:
      image: ghcr.io/tencent/android-release:latest
      options: --user root
    strategy:
      fail-fast: false
      matrix:
        language: ${{ fromJSON(needs.triage.outputs.languages) }}
    steps:
    - name: Checkout
      uses: actions/checkout@v3
      with:
        lfs: true
    - name: Initialize CodeQL
      uses: github/codeql-action/init@v2
      with:
        languages: ${{ matrix.language }}
    - name: Setup Node.js
      if: matrix.language == 'javascript'
      uses: actions/setup-node@v3
      with:
        node-version: latest
    - name: Build Java
      if: matrix.language == 'java'
      env:
        skipCmakeAndNinja: 1
      run: |
        ./gradlew assembleDebug
    - name: Build C++
      if: matrix.language == 'cpp'
      run: |
        ./gradlew buildCMakeDebug -PINCLUDE_ABI_X86=true -PINCLUDE_ABI_X86_64=true
    - name: Perform CodeQL Analysis
      uses: github/codeql-action/analyze@v2

  fallback:
    needs: triage
    if: ${{ !needs.triage.outputs.languages }}
    runs-on: ubuntu-latest
    steps:
    - name: Generate Fake SARIF
      run:
        echo '{"version":"2.1.0","runs":[{"tool":{"driver":{"name":"CodeQL"}},"results":[]}]}' > ./fake.sarif
      # The following step will output a lot of errors(like `The process '/usr/bin/git' failed with exit code 128`),
      # don't worry it's NORMAL because we don't checkout repository.
    - name: Upload Fake SARIF
      uses: github/codeql-action/upload-sarif@v2
      with:
        sarif_file: ./fake.sarif
        category: fake_results_do_not_care

  codeql_finalize:
    needs: [ analyze, fallback ]
    if: always()
    runs-on: ubuntu-latest
    steps:
    - name: Success
      if: contains(needs.*.result, 'success')
      run: |
        echo "CodeQL analysis completed successfully!"
    - name: Failure
      if: ${{ !contains(needs.*.result, 'success') }}
      run: |
        echo "CodeQL analysis completed with errors!"
        exit -1

name: 'Publish Client Dev Preview on PR Merge'

on:
  pull_request_target:
    types: [closed]
    paths:
      - 'packages/client/**'
      - 'packages/cherry-markdown/**'
      - '!packages/cherry-markdown/test/**'

concurrency:
  group: ${{ github.workflow }}-${{ github.event.pull_request.number }}
  cancel-in-progress: true

permissions:
  contents: read
  pull-requests: write
  actions: read
  issues: write

jobs:
  client-preview:
    # 不需要在 fork 仓库的pr中运行, 仅当 pr 合并时运行
    if: github.repository == 'Tencent/cherry-markdown' && github.event.pull_request.merged == true && github.event.pull_request.base.ref == 'dev'
    name: client-${{ matrix.platform_name }}-${{ matrix.arch }}
    runs-on: ${{ matrix.platform }}
    timeout-minutes: 60
    strategy:
      fail-fast: false
      max-parallel: 4
      matrix:
        include:
          - platform: macos-latest
            target: aarch64-apple-darwin
            platform_name: macos
            arch: arm64
            args: '--target aarch64-apple-darwin'
          - platform: macos-latest
            target: x86_64-apple-darwin
            platform_name: macos
            arch: x64
            args: '--target x86_64-apple-darwin'
          - platform: windows-latest
            target: x86_64-pc-windows-msvc
            platform_name: windows
            arch: x64
            args: '--target x86_64-pc-windows-msvc'
          - platform: ubuntu-latest
            target: x86_64-unknown-linux-gnu
            platform_name: linux
            arch: x64
            args: '--target x86_64-unknown-linux-gnu'

    steps:
      - uses: actions/checkout@v4
        with:
          ref: ${{ github.event.pull_request.head.sha }}

      - name: Setup Node
        uses: actions/setup-node@v4
        with:
          node-version: lts/*
          cache: 'yarn'

      - name: Setup Rust
        uses: actions-rust-lang/setup-rust-toolchain@v1
        with:
          target: ${{ matrix.target }}
          toolchain: stable

      - name: Cache Rust Dependencies
        uses: Swatinem/rust-cache@v2
        with:
          workspaces: packages/client/src-tauri -> target
          save-if: false # PR Preview 只读(main)缓存，不保存新缓存

      - name: Install Linux Dependencies
        if: matrix.platform == 'ubuntu-latest'
        run: |
          sudo apt-get update
          sudo apt-get install -y libwebkit2gtk-4.1-dev libappindicator3-dev librsvg2-dev patchelf

      - name: Get Version
        id: version
        shell: bash
        run: |
          VERSION=$(node -p "require('./packages/client/package.json').version")
          echo "version=$VERSION" >> $GITHUB_OUTPUT
          echo "Version: $VERSION"

      - name: Install Dependencies
        run: yarn --network-timeout 100000

      - name: Build Cherry Markdown
        run: yarn build

      - name: Build Tauri Client
        run: yarn build:client ${{ matrix.args }}

      - name: Collect and Upload Artifacts
        id: artifacts
        shell: bash
        run: |
          mkdir -p ./artifact-info
          VERSION="${{ steps.version.outputs.version }}"
          PLATFORM="${{ matrix.platform_name }}"
          ARCH="${{ matrix.arch }}"
          TARGET="${{ matrix.target }}"
          TARGET_DIR="./packages/client/src-tauri/target/$TARGET/release/bundle"

          # 创建产物信息文件
          echo "version=$VERSION" > ./artifact-info/build-info.txt
          echo "platform=$PLATFORM" >> ./artifact-info/build-info.txt
          echo "arch=$ARCH" >> ./artifact-info/build-info.txt
          echo "target=$TARGET" >> ./artifact-info/build-info.txt

          # 收集所有产物文件名
          > ./artifact-info/files.txt
          if [ -d "$TARGET_DIR" ]; then
            find "$TARGET_DIR" -type f \( -name "*.dmg" -o -name "*.msi" -o -name "*.exe" -o -name "*.AppImage" -o -name "*.deb" \) | while read file; do
              basename "$file" >> ./artifact-info/files.txt
            done
            find "$TARGET_DIR" -type d -name "*.app" | while read dir; do
              basename "$dir" >> ./artifact-info/files.txt
            done
          fi

          echo "Build Info:"
          cat ./artifact-info/build-info.txt
          echo "Artifacts:"
          cat ./artifact-info/files.txt

      # macOS: 上传 DMG
      - name: Upload DMG
        if: matrix.platform_name == 'macos'
        uses: actions/upload-artifact@v4
        with:
          name: cherry-markdown-${{ steps.version.outputs.version }}-${{ matrix.platform_name }}-${{ matrix.arch }}-dmg
          path: ./packages/client/src-tauri/target/${{ matrix.target }}/release/bundle/dmg/*.dmg
          retention-days: 7
          if-no-files-found: error

      # macOS: 上传 App
      - name: Upload App
        if: matrix.platform_name == 'macos'
        uses: actions/upload-artifact@v4
        with:
          name: cherry-markdown-${{ steps.version.outputs.version }}-${{ matrix.platform_name }}-${{ matrix.arch }}-app
          path: ./packages/client/src-tauri/target/${{ matrix.target }}/release/bundle/macos/*.app
          retention-days: 7
          if-no-files-found: error

      # Windows: 上传 MSI
      - name: Upload MSI
        if: matrix.platform_name == 'windows'
        uses: actions/upload-artifact@v4
        with:
          name: cherry-markdown-${{ steps.version.outputs.version }}-${{ matrix.platform_name }}-${{ matrix.arch }}-msi
          path: ./packages/client/src-tauri/target/${{ matrix.target }}/release/bundle/msi/*.msi
          retention-days: 7
          if-no-files-found: error

      # Windows: 上传 NSIS Exe
      - name: Upload NSIS Installer
        if: matrix.platform_name == 'windows'
        uses: actions/upload-artifact@v4
        with:
          name: cherry-markdown-${{ steps.version.outputs.version }}-${{ matrix.platform_name }}-${{ matrix.arch }}-exe
          path: ./packages/client/src-tauri/target/${{ matrix.target }}/release/bundle/nsis/*.exe
          retention-days: 7
          if-no-files-found: error

      # Linux: 上传 AppImage
      - name: Upload AppImage
        if: matrix.platform_name == 'linux'
        uses: actions/upload-artifact@v4
        with:
          name: cherry-markdown-${{ steps.version.outputs.version }}-${{ matrix.platform_name }}-${{ matrix.arch }}-appimage
          path: ./packages/client/src-tauri/target/${{ matrix.target }}/release/bundle/appimage/*.AppImage
          retention-days: 7
          if-no-files-found: error

      # Linux: 上传 Deb
      - name: Upload Deb
        if: matrix.platform_name == 'linux'
        uses: actions/upload-artifact@v4
        with:
          name: cherry-markdown-${{ steps.version.outputs.version }}-${{ matrix.platform_name }}-${{ matrix.arch }}-deb
          path: ./packages/client/src-tauri/target/${{ matrix.target }}/release/bundle/deb/*.deb
          retention-days: 7
          if-no-files-found: error

      - name: Upload Artifact Info
        uses: actions/upload-artifact@v4
        with:
          name: artifact-info-${{ matrix.platform_name }}-${{ matrix.arch }}
          path: ./artifact-info/
          retention-days: 7

  post-preview-comment:
    needs: client-preview
    runs-on: ubuntu-latest
    if: github.repository == 'Tencent/cherry-markdown'
    steps:
      - name: Download All Artifact Info
        uses: actions/download-artifact@v4
        with:
          pattern: artifact-info-*
          path: ./artifact-info

      - name: Generate PR Comment with Cherry-Markdown Artifacts
        uses: actions/github-script@v8
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const fs = require('fs');
            const path = require('path');
            const owner = context.repo.owner;
            const repo = context.repo.repo;
            const runId = context.runId;
            const runUrl = `https://github.com/${owner}/${repo}/actions/runs/${runId}`;

            // 获取本次 workflow run 的所有 artifacts
            const { data: artifactList } = await github.rest.actions.listWorkflowRunArtifacts({
              owner,
              repo,
              run_id: runId
            });

            // 构建 artifact 名称到下载链接的映射
            const artifactDownloadUrls = {};
            for (const artifact of artifactList.artifacts) {
              artifactDownloadUrls[artifact.name] = `https://github.com/${owner}/${repo}/actions/runs/${runId}/artifacts/${artifact.id}`;
            }

            // 读取构建信息
            const artifactInfoDir = './artifact-info';
            const buildInfos = [];

            if (fs.existsSync(artifactInfoDir)) {
              const dirs = fs.readdirSync(artifactInfoDir);

              for (const dir of dirs) {
                const buildInfoPath = path.join(artifactInfoDir, dir, 'build-info.txt');

                if (fs.existsSync(buildInfoPath)) {
                  const buildInfo = {};
                  const buildInfoContent = fs.readFileSync(buildInfoPath, 'utf8');
                  buildInfoContent.split('\n').forEach(line => {
                    const [key, value] = line.split('=');
                    if (key && value) {
                      buildInfo[key.trim()] = value.trim();
                    }
                  });
                  buildInfos.push(buildInfo);
                }
              }
            }

            // 生成评论内容
            let body = '## 💻 Cherry-Markdown Client 预览构建已完成\n\n';

            if (buildInfos.length === 0) {
              body += '> ⚠️ 未找到构建产物，请检查构建日志。\n\n';
              body += `[查看构建详情](${runUrl})\n`;
            } else {
              const version = buildInfos[0]?.version || 'unknown';

              // 定义产物类型映射
              const artifactTypes = {
                'macos': [
                  { suffix: 'dmg', label: 'DMG 安装包' },
                  { suffix: 'app', label: 'App 应用' }
                ],
                'windows': [
                  { suffix: 'msi', label: 'MSI 安装包' },
                  { suffix: 'exe', label: 'EXE 安装程序' }
                ],
                'linux': [
                  { suffix: 'appimage', label: 'AppImage' },
                  { suffix: 'deb', label: 'Deb 包' }
                ]
              };

              // 按平台分组
              const platformOrder = ['macOS', 'Windows', 'Linux'];
              const platformMap = { 'macos': 'macOS', 'windows': 'Windows', 'linux': 'Linux' };

              // 生成表格
              body += '| 平台 | 架构 | 产物类型 | 下载 |\n';
              body += '|------|------|----------|------|\n';

              for (const info of buildInfos) {
                const platform = info.platform;
                const arch = info.arch;
                const platformLabel = platformMap[platform] || platform;
                const archLabel = arch === 'arm64' ? 'Apple Silicon' : 'x64';
                const types = artifactTypes[platform] || [];

                for (const type of types) {
                  const artifactName = `cherry-markdown-${version}-${platform}-${arch}-${type.suffix}`;
                  const downloadUrl = artifactDownloadUrls[artifactName] || `${runUrl}`;
                  body += `| ${platformLabel} | ${archLabel} | ${type.label} | [下载](${downloadUrl}) |\n`;
                }
              }

              body += `\n> 📋 版本: \`${version}\` | ⏰ 产物保留 7 天 | [查看所有构建产物](${runUrl})\n`;
            }

            // 查找现有的 Cherry-Markdown Client 预览构建评论
            const { data: comments } = await github.rest.issues.listComments({
              issue_number: context.issue.number,
              owner: owner,
              repo: repo
            });

            const botComment = comments.find(comment => 
              comment.user.type === 'Bot' && 
              comment.body.includes('💻 Cherry-Markdown Client 预览构建')
            );

            if (botComment) {
              // 更新现有评论
              await github.rest.issues.updateComment({
                comment_id: botComment.id,
                owner: owner,
                repo: repo,
                body: body
              });
              console.log(`Updated existing comment: ${botComment.id}`);
            } else {
              // 创建新评论
              await github.rest.issues.createComment({
                issue_number: context.issue.number,
                owner: owner,
                repo: repo,
                body: body
              });
              console.log('Created new comment');
            }

name: code-format-msg

on:
  workflow_run:
    workflows: [code-format]
    types: [completed]

concurrency:
  group: code-format-msg-${{ github.head_ref || github.run_id }}

permissions:
  contents: read
  pull-requests: write

jobs:
  pr-context:
    name: acquire-pr-context
    runs-on: ubuntu-latest
    outputs:
      PR_HEADSHA: ${{ steps.set-pr-context.outputs.head-sha }}
      PR_NUMBER:  ${{ steps.set-pr-context.outputs.number   }}
    if: ${{ github.event.workflow_run.event == 'pull_request' }}
    steps:
    - name: get-pr-context
      id: set-pr-context
      env:
        GH_TOKEN: ${{ github.token }}
        PR_TARGET_REPO: ${{ github.repository }}
        PR_BRANCH: |-
          ${{
            (github.event.workflow_run.head_repository.owner.login != github.event.workflow_run.repository.owner.login)
              && format('{0}:{1}', github.event.workflow_run.head_repository.owner.login, github.event.workflow_run.head_branch)
              || github.event.workflow_run.head_branch
          }}
      run: |
        gh pr view --repo "${PR_TARGET_REPO}" "${PR_BRANCH}" \
          --json 'number,headRefOid' \
          --jq '"number=\(.number)\nhead-sha=\(.headRefOid)"' \
          >> $GITHUB_OUTPUT

  remove-comment-if-success:
    if: ${{ github.event.workflow_run.conclusion == 'success' }}
    runs-on: ubuntu-latest
    needs: [pr-context]
    env:
      PR_HEADSHA: ${{ needs.pr-context.outputs.PR_HEADSHA }}
      PR_NUMBER:  ${{ needs.pr-context.outputs.PR_NUMBER  }}
    steps:
    - name: Remove existing "format check failed" comment
      uses: actions/github-script@v8
      with:
        script: |
          const owner = context.repo.owner;
          const repo = context.repo.repo;
          const { data: comments } = await github.rest.issues.listComments({
            owner,
            repo,
            issue_number: ${{ env.PR_NUMBER }},
          });

          const targetComment = comments.find(comment =>
            comment.body.includes("Please enable github action in **YOUR FORKED REPO** to make code-format workflow work")
          );

          if (targetComment) {
            await github.rest.issues.deleteComment({
              owner,
              repo,
              comment_id: targetComment.id,
            });
            console.log("Removed existing code-format failure comment.");
          } else {
            console.log("No existing format failure comment to remove.");
          }

  post-comment-if-failure:
    if: ${{ github.event.workflow_run.conclusion == 'failure' }}
    runs-on: ubuntu-latest
    needs: [pr-context]
    env:
      PR_HEADSHA: ${{ needs.pr-context.outputs.PR_HEADSHA }}
      PR_NUMBER:  ${{ needs.pr-context.outputs.PR_NUMBER  }}
    steps:
    - name: Post comment on failed code-format if not existing
      uses: actions/github-script@v8
      with:
        script: |
          const owner = context.repo.owner;
          const repo = context.repo.repo;
          const { data: comments } = await github.rest.issues.listComments({
            owner,
            repo,
            issue_number: ${{ env.PR_NUMBER }},
          });

          const existingComment = comments.find(comment =>
            comment.body.includes("Please enable github action in **YOUR FORKED REPO** to make code-format workflow work")
          );

          if (existingComment) {
            console.log("A code-format failure comment already exists.");
          } else {
            await github.rest.issues.createComment({
              owner,
              repo,
              issue_number: ${{ env.PR_NUMBER }},
              body: "Please enable github action in **YOUR FORKED REPO** to make code-format workflow work",
            });
            console.log("Created code-format failure comment.");
          }

name: PREVIEW_PUBLISH

on:
  workflow_run:
    workflows: 
      - PREVIEW_BUILD
    types:
      - completed

jobs:
  preview-context:
    if: github.event.workflow_run.conclusion == 'success'
    runs-on: ubuntu-latest
    outputs: 
      pr_id: ${{ steps.pr.outputs.id }}
      tdesign_vue_next_domain: ${{ steps.tdesign-vue-next-domain.outputs.tdesign_vue_next_domain }}
      tdesign_vue_next_chat_domain: ${{ steps.tdesign-vue-next-chat-domain.outputs.tdesign_vue_next_chat_domain }}
    steps:
      - name: Download pr id
        uses: dawidd6/action-download-artifact@v8
        with:
          workflow: ${{ github.event.workflow_run.workflow_id }}
          run_id: ${{ github.event.workflow_run.id }}
          name: pr-id

      - name: Set pr id
        id : pr
        run: echo "id=$(cat pr-id.txt)" >> $GITHUB_OUTPUT

      - name: tdesign-vue-next-domain
        id: tdesign-vue-next-domain
        run: echo "tdesign_vue_next_domain=https://preview-pr-${{ steps.pr.outputs.id }}-tdesign-vue-next.surge.sh" >> $GITHUB_OUTPUT

      - name: tdesign-vue-next-chat-domain
        id: tdesign-vue-next-chat-domain
        run: echo "tdesign_vue_next_chat_domain=https://preview-pr-${{ steps.pr.outputs.id }}-tdesign-vue-next-chat.surge.sh" >> $GITHUB_OUTPUT

  tdesign-vue-next:
    if: github.event.workflow_run.conclusion == 'success'
    runs-on: ubuntu-latest
    needs: preview-context
    steps:
      - uses: dawidd6/action-download-artifact@v8
        with:
          workflow: ${{ github.event.workflow_run.workflow_id }}
          run_id: ${{ github.event.workflow_run.id }}
          name: tdesign-vue-next-site
      - run: |
          export DEPLOY_DOMAIN=${{ needs.preview-context.outputs.tdesign_vue_next_domain }}
          npx surge --project ./ --domain $DEPLOY_DOMAIN --token ${{ secrets.TDESIGN_SURGE_TOKEN }}  

  tdesign-vue-next-chat:
    if: github.event.workflow_run.conclusion == 'success'
    runs-on: ubuntu-latest
    needs: preview-context
    steps:
      - uses: dawidd6/action-download-artifact@v8
        with:
          workflow: ${{ github.event.workflow_run.workflow_id }}
          run_id: ${{ github.event.workflow_run.id }}
          name: tdesign-vue-next-chat-site
      - run: |
          export DEPLOY_DOMAIN=${{ needs.preview-context.outputs.tdesign_vue_next_chat_domain }}
          npx surge --project ./ --domain $DEPLOY_DOMAIN --token ${{ secrets.TDESIGN_SURGE_TOKEN }}           

  preview-comment:
    if: always()
    needs:
      - preview-context
      - tdesign-vue-next
      - tdesign-vue-next-chat
    runs-on: ubuntu-latest
    steps:
      - name: jobs report
        id: report
        uses: actions/github-script@v7
        with:
          script: |
            const pr_id = ${{ needs.preview-context.outputs.pr_id }};
            const tdesign_vue_next_domain = "${{ needs.preview-context.outputs.tdesign_vue_next_domain }}";
            const tdesign_vue_next_chat_domain = "${{ needs.preview-context.outputs.tdesign_vue_next_chat_domain }}";

            const { data: { jobs } } = await github.rest.actions.listJobsForWorkflowRun({
              owner: context.repo.owner,
              repo: context.repo.repo,
              run_id: context.runId,
              per_page: 100
            })

            const tdesign = {
              "tdesign-vue-next": { status: "", report_url: "" },
              "tdesign-vue-next-chat": { status: "", report_url: "" },
            };
            const preview_success = `<img width="300" alt="完成" src="https://user-images.githubusercontent.com/15634204/150816437-9f5bb788-cd67-4cbc-9897-b82d74e9aa65.png" />`;
            const preview_failure = `<img width="300" alt="失败" src="https://user-images.githubusercontent.com/5378891/75333447-1e63a280-58c1-11ea-975d-235367fd1522.png" />`;
            jobs
              .filter((job) => job.name.startsWith("tdesign-"))
              .map((job) => {
                tdesign[job.name].status = preview_failure;
                tdesign[job.name].report_url = job.html_url;

                if (job.conclusion === "success") {
                  tdesign[job.name].status = preview_success;
                  if (job.name === "tdesign-vue-next") {

                    tdesign[job.name].report_url = tdesign_vue_next_domain;
                  }
                  if (job.name === "tdesign-vue-next-chat") {
                    tdesign[job.name].report_url = tdesign_vue_next_chat_domain;
                  }
                }
              });

            const runUrl = `${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId}`;

            const comment = `
              # TDesign Component Site Preview [Open](${runUrl})
              | Component | Preview |
              | --------- | :--: |
              ${Object.keys(tdesign)
                .map((component) => {
                  const preview_text = `[${tdesign[component].status}](${tdesign[component].report_url})`;
                  let package_name = component;
                  if (component === "tdesign-vue-next-chat") {
                    package_name = "@tdesign-vue-next/chat";
                  }

                  return `| ${package_name} | ${preview_text} | `;
                })
                .join("\n")}

              <!-- AUTO_PREVIEW_HOOK -->
              `;

            core.setOutput('comment', comment);

      - name: comment
        uses: actions-cool/maintain-one-comment@v3
        with:
            token: ${{ secrets.TDESIGN_BOT_TOKEN }}
            number: ${{needs.preview-context.outputs.pr_id}}
            body: ${{ steps.report.outputs.comment }}
            body-include: '<!-- AUTO_PREVIEW_HOOK -->'

name: Security Report
on:
  workflow_run:
    workflows: ["Security Guardian"]
    types: [completed]

jobs:
  report:
    runs-on: ubuntu-latest
    permissions:
      checks: write
      pull-requests: write
      actions: read
    env:
      CHECK_NAME_STATIC: 'Security Guardian Results'
      CHECK_NAME_RESOLVED: 'Security Guardian Results with resolved templates'
    steps:
      - name: Download artifacts
        uses: actions/download-artifact@v7
        with:
          name: security-guardian-reports
          path: test-results/
          github-token: ${{ secrets.GITHUB_TOKEN }}
          run-id: ${{ github.event.workflow_run.id }}
          repository: ${{ github.repository }}

      - name: Get PR info
        id: pr_info
        run: |
          echo "pr_number=$(cat test-results/pr_number)" >> "$GITHUB_OUTPUT"
          echo "pr_sha=$(cat test-results/pr_sha)" >> "$GITHUB_OUTPUT"
          echo "PR: $(cat test-results/pr_number), SHA: $(cat test-results/pr_sha)"
      - name: Publish Security Test Results 
        id: junit_static
        uses: mikepenz/action-junit-report@v6
        if: always()
        with:
          report_paths: 'test-results/**/cfn-guard-static.xml'
          check_name: ${{ env.CHECK_NAME_STATIC }}
          exclude_sources: 'node_modules,dist'
          commit: ${{ steps.pr_info.outputs.pr_sha }}
          check_annotations: true
          comment: true
          pr_id: ${{ steps.pr_info.outputs.pr_number }}
          detailed_summary: true
          include_passed: false
          fail_on_failure: false
          group_suite: true
          include_skipped: false
          check_title_template: '{{TEST_NAME}}'
          include_empty_in_summary: false

      - name: Add disclaimer to static results comment
        uses: actions/github-script@v8
        if: steps.junit_static.outcome == 'success'
        env:
          PR_NUMBER: ${{ steps.pr_info.outputs.pr_number }}
          CHECK_NAME: ${{ env.CHECK_NAME_STATIC }}
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const prNumber = process.env.PR_NUMBER;
            const checkName = process.env.CHECK_NAME;
            const comments = await github.rest.issues.listComments({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber,
            });

            const botComment = comments.data.find(comment => 
              comment.user.type === 'Bot' && 
              comment.body.includes(checkName) &&
              !comment.body.includes('resolved templates')
            );

            if (botComment) {
              const disclaimer = '⚠️ **Experimental Feature**: This security report is currently in experimental phase. Results may include false positives and the rules are being actively refined. \n**Please try `merge from main` to avoid findings unrelated to the PR.**\n\n---\n\n';
              await github.rest.issues.updateComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                comment_id: botComment.id,
                body: disclaimer + botComment.body
              });
            }

      - name: Publish Security Test Results for resolved templates
        id: junit_resolved
        uses: mikepenz/action-junit-report@v6
        if: always()
        with:
          report_paths: 'test-results/**/cfn-guard-resolved.xml'
          check_name: ${{ env.CHECK_NAME_RESOLVED }}
          exclude_sources: 'node_modules,dist'
          commit: ${{ steps.pr_info.outputs.pr_sha }}
          check_annotations: true
          comment: true
          pr_id: ${{ steps.pr_info.outputs.pr_number }}
          detailed_summary: true
          include_passed: false
          fail_on_failure: false
          group_suite: true
          include_skipped: false
          check_title_template: '{{TEST_NAME}}'
          include_empty_in_summary: false

      - name: Add disclaimer to resolved results comment
        uses: actions/github-script@v8
        if: steps.junit_resolved.outcome == 'success'
        env:
          PR_NUMBER: ${{ steps.pr_info.outputs.pr_number }}
          CHECK_NAME: ${{ env.CHECK_NAME_RESOLVED }}
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const prNumber = process.env.PR_NUMBER;
            const checkName = process.env.CHECK_NAME;
            const comments = await github.rest.issues.listComments({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber,
            });

            const botComment = comments.data.find(comment => 
              comment.user.type === 'Bot' && 
              comment.body.includes(checkName)
            );

            if (botComment) {
              const disclaimer = '⚠️ **Experimental Feature**: This security report is currently in experimental phase. Results may include false positives and the rules are being actively refined. \n**Please try `merge from main` to avoid findings unrelated to the PR.**\n\n---\n\n';
              await github.rest.issues.updateComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                comment_id: botComment.id,
                body: disclaimer + botComment.body
              });
            }

# Apply potential regression label on issues
name: issue-regression-label
on:
  issues:
    types: [opened, edited]

  workflow_dispatch:  # Allows manual triggering of the workflow

jobs:
  add-regression-label:
    runs-on: ubuntu-latest
    permissions:
      issues: write
    steps:
    - name: Fetch template body
      id: check_regression
      uses: actions/github-script@v7
      env: 
        GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
        TEMPLATE_BODY: ${{ github.event.issue.body }}
      with:
        script: |
          const regressionPattern = /\[x\] Select this option if this issue appears to be a regression\./i;
          const template = `${process.env.TEMPLATE_BODY}`
          const match = regressionPattern.test(template);
          core.setOutput('is_regression', match);

    - name: Add label on regression
      if: steps.check_regression.outputs.is_regression == 'true'
      id: add_label
      uses: actions/github-script@v6
      with:
        github-token: ${{ secrets.GITHUB_TOKEN }}
        script: |
          await github.issues.addLabels({
          owner: context.repo.owner,
          repo: context.repo.repo,
          issue_number: context.issue.number,
          labels: ['potential-regression'],
          });

    - name: Remove label on regression
      if: steps.check_regression.outputs.is_regression == 'false'
      id: remove_label
      uses: actions/github-script@v7
      with:
        github-token: ${{ secrets.GITHUB_TOKEN }}
        script: |
          try {
            await github.rest.issues.removeLabel({
            owner: context.repo.owner,
            repo: context.repo.repo,
            issue_number: context.issue.number,
            name: 'potential-regression',
            });
          } catch (error) {
            console.log('Label does not exist or cannot be removed:', error.message);
          }

name: Comment PR with bin sizes

on:
  workflow_run:
    workflows: ["Compute bin sizes"]
    types:
      - completed

jobs:
  comment_bin_size:
    runs-on: ubuntu-latest
    steps:
      - name: Download artifacts
        uses: actions/github-script@v6
        with:
          script: |
            let allArtifacts = await github.rest.actions.listWorkflowRunArtifacts({
               owner: context.repo.owner,
               repo: context.repo.repo,
               run_id: context.payload.workflow_run.id,
            });
            let matchArtifact = allArtifacts.data.artifacts.filter((artifact) => {
              return artifact.name == "pr_number_and_bin_sizes"
            })[0];
            let download = await github.rest.actions.downloadArtifact({
               owner: context.repo.owner,
               repo: context.repo.repo,
               artifact_id: matchArtifact.id,
               archive_format: 'zip',
            });
            let fs = require('fs');
            fs.writeFileSync(`${process.env.GITHUB_WORKSPACE}/artifacts.zip`, Buffer.from(download.data));

      - name: Unzip artifacts
        run: unzip artifacts.zip

      - name: Calculate size change
        id: diff
        uses: actions/github-script@v6
        with:
          result-encoding: string
          script: |
            let fs = require('fs');
            let sizes_raw = fs.readFileSync('sizes.json');
            let sizes = JSON.parse(sizes_raw)

            const diff = (old, cur) => {
              const res = (cur-old)/old * 100;
              return res.toFixed(2); // 2 decimal places.
            };

            const lastRelease = '${{ steps.latestrelease.outputs.VERSION_TAG }}';
            let msg = `
              🍕 Here are the new binary sizes!

              | Name | New size (kiB) | ${lastRelease} size (kiB) | Delta (%) |
              |:--   |:---            |:---                    |:--    |
            `;

            let shouldAcknowledgeSize = false;
            for (const os of Object.keys(sizes)) {
              for (const arch of Object.keys(sizes[os])) {
                const delta = diff(sizes[os][arch].old, sizes[os][arch].cur);
                if (delta > 10) {
                  shouldAcknowledgeSize = true;
                }

                let symbol = "❤️ ";
                if (delta > 5) {
                  symbol = "😭 +";
                } else if (delta > 1) {
                  symbol = "🥺 +"
                } else if (delta > 0) {
                  symbol = "+";
                }
                msg += `| ${os} (${arch}) | ${sizes[os][arch].cur} | ${sizes[os][arch].old} | ${symbol}${delta} |` + "\n";
              }
            }

            if (shouldAcknowledgeSize) {
              msg += "**The binary size increased more than expected! Applying the `do-not-merge` label.**\n"
              github.rest.issues.addLabels({
                issue_number: context.issue.number,
                owner: context.repo.owner,
                repo: context.repo.repo,
                labels: ['do-not-merge']
              });
            }
            return msg;

      - name: Find PR number
        id: find-pr-number
        run: |
          echo "PR_NUMBER=$(cat pr_number)" >> $GITHUB_OUTPUT

      - name: Find comment
        uses: peter-evans/find-comment@v2
        id: fc
        with:
          issue-number: ${{ steps.find-pr-number.outputs.PR_NUMBER }}
          comment-author: 'github-actions[bot]'
          body-includes: 'Here are the new binary sizes'

      - name: Create or update comment
        uses: peter-evans/create-or-update-comment@v2
        with:
          comment-id: ${{ steps.fc.outputs.comment-id }}
          issue-number: ${{ steps.find-pr-number.outputs.PR_NUMBER }}
          body: ${{ steps.diff.outputs.result }}
          edit-mode: replace

name: Deploy Website Preview to Amplify
on:
  workflow_run:
    workflows: [ WebsitePreviewTrigger ]
    types: [ completed ]
jobs:
  preview:
    permissions:
      id-token: write
      contents: read
      pull-requests: write
      statuses: write
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@8e8c483db84b4bee98b60c0593521ed34d9990e8 # v6.0.1
      - uses: ./.github/actions/download-artifact
      - id: website-metadata
        run: |
          pr_number="$(head -n 1 /tmp/artifacts/website-metadata.txt)"
          pr_commit="$(tail -n 1 /tmp/artifacts/website-metadata.txt)"
          {
            echo PR_COMMIT="$pr_commit"
            echo PR_NUMBER="$pr_number"
            echo BRANCH_NAME="pr-$pr_number"
          } >> "$GITHUB_ENV"
      - uses: actions/checkout@8e8c483db84b4bee98b60c0593521ed34d9990e8 # v6.0.1
        with:
          ref: ${{ env.PR_COMMIT }}
      - uses: ./.github/actions/commit-status/start
        with:
          name: "${{ github.workflow }} / ${{ github.job }} (pull_request_review)"
          git_ref: ${{ env.PR_COMMIT }}
      - name: Configure AWS credentials
        uses: aws-actions/configure-aws-credentials@61815dcd50bd041e203e49132bacad1fd04d2708 # v5.1.1
        with:
          role-to-assume: arn:aws:iam::${{ vars.RELEASE_PREVIEW_ACCOUNT_ID }}:role/${{ vars.WEBSITE_ROLE_NAME }}
          aws-region: ${{ vars.AMPLIFY_REGION }}
      - name: Get preview URL
        run: |
          APP_DOMAIN=$(aws amplify get-app --app-id ${{ vars.AMPLIFY_APP_ID_PREVIEW }} --query 'app.defaultDomain' --output text)
          PREVIEW_URL="https://${{ env.BRANCH_NAME }}.$APP_DOMAIN"
          echo PREVIEW_URL="$PREVIEW_URL" >> "$GITHUB_ENV"
      - name: Deploy website
        uses: ./.github/actions/deploy-website
        with:
          role: arn:aws:iam::${{ vars.RELEASE_PREVIEW_ACCOUNT_ID }}:role/${{ vars.WEBSITE_ROLE_NAME }}
          region: ${{ vars.AMPLIFY_REGION }}
          amplify-app-id: ${{ vars.AMPLIFY_APP_ID_PREVIEW }}
          amplify-branch-name: ${{ env.BRANCH_NAME }}
          s3-bucket: ${{ vars.AMPLIFY_S3_BUCKET_BETA }}
          s3-prefix: pr-${{ env.PR_NUMBER }}/
          hugo-base-url: ${{ env.PREVIEW_URL }}
      - uses: actions/github-script@ed597411d8f924073f98dfc5c65a23a2325f34cd # v8.0.0
        env:
          PREVIEW_URL: ${{ env.PREVIEW_URL }}
          PR_COMMIT: ${{ env.PR_COMMIT }}
        with:
          script: |
            const commentBody = `**Preview deployment ready!**

            **Preview URL:** ${process.env.PREVIEW_URL}

            Built from commit \`${process.env.PR_COMMIT}\``;

            const existingComment = (await github.rest.issues.listComments({
              issue_number: process.env.PR_NUMBER,
              owner: context.repo.owner,
              repo: context.repo.repo,
            })).data.find(comment => 
              comment.user.login === 'github-actions[bot]' && 
              comment.body.includes('**Preview deployment ready!**')
            );

            if (existingComment) {
              await github.rest.issues.updateComment({
                comment_id: existingComment.id,
                owner: context.repo.owner,
                repo: context.repo.repo,
                body: commentBody
              });
            } else {
              await github.rest.issues.createComment({
                issue_number: process.env.PR_NUMBER,
                owner: context.repo.owner,
                repo: context.repo.repo,
                body: commentBody
              });
            }
      - if: always()
        uses: ./.github/actions/commit-status/end
        with:
          name: "${{ github.workflow }} / ${{ github.job }} (pull_request_review)"
          git_ref: ${{ env.PR_COMMIT }}

name: Security Monitoring

on:
  schedule:
    - cron: '0 16 * * *'

concurrency:
  group: ${{ github.workflow }}-${{ github.run_id }}
  cancel-in-progress: true

permissions:
  id-token: write

jobs:
  check-code-scanning-alerts:
    runs-on: ubuntu-latest
    outputs:
      code_scanning_alert_status: ${{ steps.check-code-scanning-alerts.outputs.code_scanning_alert_status }}
    steps:
      - name: Check for security alerts
        id: check-code-scanning-alerts
        uses: actions/github-script@60a0d83039c74a4aee543508d2ffcb1c3799cdea
        with:
          github-token: ${{ secrets.GH_PAT }}
          script: |
            async function checkAlerts() {
              const owner = '${{ github.repository_owner }}';
              const repo = '${{ github.event.repository.name }}';
              const ref = 'refs/heads/master';

              const codeScanningAlerts = await github.rest.codeScanning.listAlertsForRepo({
                owner,
                repo,
                ref: ref
              });
              const activeCodeScanningAlerts = codeScanningAlerts.data.filter(alert => alert.state === 'open');
              core.setOutput('code_scanning_alert_status', activeCodeScanningAlerts.length > 0 ? '1': '0');
            }
            await checkAlerts();

  check-dependabot-alerts:
    runs-on: ubuntu-latest
    outputs:
      dependabot_alert_status: ${{ steps.check-dependabot-alerts.outputs.dependabot_alert_status }}
    steps:
      - name: Check for dependabot alerts
        id: check-dependabot-alerts
        uses: actions/github-script@60a0d83039c74a4aee543508d2ffcb1c3799cdea
        with:
          github-token: ${{ secrets.GH_PAT }}
          script: |
            async function checkAlerts() {
              const owner = '${{ github.repository_owner }}';
              const repo = '${{ github.event.repository.name }}';

              const dependabotAlerts = await github.rest.dependabot.listAlertsForRepo({
                owner,
                repo,
                headers: {
                  'accept': 'applications/vnd.github+json'
                }
              }); 
              const activeDependabotAlerts = dependabotAlerts.data.filter(alert => alert.state === 'open');
              core.setOutput('dependabot_alert_status', activeDependabotAlerts.length > 0 ? '1': '0');
            }
            await checkAlerts();

  check-secret-scanning-alerts:
    runs-on: ubuntu-latest
    outputs:
      secret_scanning_alert_status: ${{ steps.check-secret-scanning-alerts.outputs.secret_scanning_alert_status }}
    steps:
      - name: Check for secret scanning alerts
        id: check-secret-scanning-alerts
        uses: actions/github-script@60a0d83039c74a4aee543508d2ffcb1c3799cdea
        with:
          github-token: ${{ secrets.GH_PAT }}
          script: |
            async function checkAlerts() {
              const owner = '${{ github.repository_owner }}';
              const repo = '${{ github.event.repository.name }}';

              const secretScanningAlerts = await github.rest.secretScanning.listAlertsForRepo({
                owner,
                repo,
              }); 
              const activeSecretScanningAlerts = secretScanningAlerts.data.filter(alert => alert.state === 'open');
              core.setOutput('secret_scanning_alert_status', activeSecretScanningAlerts.length > 0 ? '1': '0');
            }
            await checkAlerts();

  put-metric-data:
    runs-on: ubuntu-latest
    needs: [check-code-scanning-alerts, check-dependabot-alerts, check-secret-scanning-alerts]
    steps:
      - name: Configure AWS Credentials
        uses: aws-actions/configure-aws-credentials@12e3392609eaaceb7ae6191b3f54bbcb85b5002b
        with:
          role-to-assume: ${{ secrets.MONITORING_ROLE_ARN }}
          aws-region: us-west-2
      - name: Put Code Scanning Alert Metric Data
        run: |
          if [ "${{ needs.check-code-scanning-alerts.outputs.code_scanning_alert_status }}" == "1" ]; then
            aws cloudwatch put-metric-data --metric-name CodeScanningAlert --namespace SecurityMonitoringMetrics --value 1 --unit Count --dimensions ProjectName=sagemaker-python-sdk
          else
            aws cloudwatch put-metric-data --metric-name CodeScanningAlert --namespace SecurityMonitoringMetrics --value 0 --unit Count --dimensions ProjectName=sagemaker-python-sdk
          fi
      - name: Put Dependabot Alert Metric Data
        run: |
          if [ "${{ needs.check-dependabot-alerts.outputs.dependabot_alert_status }}" == "1" ]; then
            aws cloudwatch put-metric-data --metric-name DependabotAlert --namespace SecurityMonitoringMetrics --value 1 --unit Count --dimensions ProjectName=sagemaker-python-sdk
          else
            aws cloudwatch put-metric-data --metric-name DependabotAlert --namespace SecurityMonitoringMetrics --value 0 --unit Count --dimensions ProjectName=sagemaker-python-sdk
          fi
      - name: Put Secret Scanning Alert Metric Data
        run: |
          if [ "${{ needs.check-secret-scanning-alerts.outputs.secret_scanning_alert_status }}" == "1" ]; then
            aws cloudwatch put-metric-data --metric-name SecretScanningAlert --namespace SecurityMonitoringMetrics --value 1 --unit Count --dimensions ProjectName=sagemaker-python-sdk
          else
            aws cloudwatch put-metric-data --metric-name SecretScanningAlert --namespace SecurityMonitoringMetrics --value 0 --unit Count --dimensions ProjectName=sagemaker-python-sdk
          fi

name: PR Issue Link Checker

on:
  pull_request:
    types: [opened, edited, reopened, synchronize]

jobs:
  check-issue-link:
    runs-on: ubuntu-latest
    steps:
      - name: Check for Linked Issue
        uses: actions/github-script@v6
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { owner, repo, number } = context.issue;

            // Get the PR details
            const pr = await github.rest.pulls.get({
              owner,
              repo,
              pull_number: number
            });

            // Check PR body for issue links
            const body = pr.data.body || '';

            // Regular expressions to match different formats of issue links
            const issueRegexes = [
              /#(\d+)/,                                  // #123
              /[Cc]loses #(\d+)/,                        // Closes #123
              /[Ff]ixes #(\d+)/,                         // Fixes #123
              /[Rr]esolves #(\d+)/,                      // Resolves #123
              /[Cc]lose #(\d+)/,                         // Close #123
              /[Ff]ix #(\d+)/,                           // Fix #123
              /[Rr]esolve #(\d+)/,                       // Resolve #123
              /[Cc]loses: #(\d+)/,                       // Closes: #123
              /[Ff]ixes: #(\d+)/,                        // Fixes: #123
              /[Rr]esolves: #(\d+)/,                     // Resolves: #123
              /[Cc]lose: #(\d+)/,                        // Close: #123
              /[Ff]ix: #(\d+)/,                          // Fix: #123
              /[Rr]esolve: #(\d+)/,                      // Resolve: #123
              /(?:issues?|closes?|fixes?|resolves?)[ ]*?(?:\/|#)(\d+)/i // Various other formats
            ];

            let hasIssueLink = false;

            // Also check if the PR is linked to issues through GitHub's UI
            const linkedIssues = await github.rest.issues.listEventsForTimeline({
              owner,
              repo,
              issue_number: number
            });

            const crossReferences = linkedIssues.data.filter(event => 
              event.event === 'cross-referenced' && 
              event.source?.issue?.html_url.includes(`/${owner}/${repo}/issues/`)
            );

            if (crossReferences.length > 0) {
              hasIssueLink = true;
            }

            // Check for issue links in PR body
            if (!hasIssueLink) {
              for (const regex of issueRegexes) {
                if (regex.test(body)) {
                  hasIssueLink = true;
                  break;
                }
              }
            }

            if (!hasIssueLink) {
              core.setFailed('Pull request must be linked to an issue. Please add a reference to an issue in your PR description (e.g., "Fixes #123") or link an issue through the GitHub UI.');
            }

name: ASH Security Scan - Post Comments

on:
  workflow_run:
    workflows: ["ASH Security Scan"]
    types:
      - completed

permissions:
  pull-requests: write
  actions: read

jobs:
  comment:
    runs-on: ubuntu-latest
    if: github.event.workflow_run.event == 'pull_request'
    steps:
      - name: Download artifacts
        uses: actions/download-artifact@v4
        with:
          name: ash-security-results
          path: /tmp/ash-results
          run-id: ${{ github.event.workflow_run.id }}
          github-token: ${{ secrets.GITHUB_TOKEN }}

      - name: Get PR information
        id: pr-info
        run: |
          if [ -f /tmp/ash-results/pr_number.txt ]; then
            PR_NUMBER=$(cat /tmp/ash-results/pr_number.txt)
            echo "pr_number=${PR_NUMBER}" >> $GITHUB_OUTPUT
            echo "Found PR number: ${PR_NUMBER}"
          else
            echo "No PR number found in artifacts"
            exit 1
          fi

          if [ -f /tmp/ash-results/pr_sha.txt ]; then
            PR_SHA=$(cat /tmp/ash-results/pr_sha.txt)
            echo "pr_sha=${PR_SHA}" >> $GITHUB_OUTPUT
            echo "Found PR SHA: ${PR_SHA}"
          fi

      - name: Post comment on PR
        if: steps.pr-info.outputs.pr_number
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const fs = require('fs');
            const commentPath = '/tmp/ash-results/pr_comment.md';

            if (!fs.existsSync(commentPath)) {
              console.log('No comment file found in artifacts');
              return;
            }

            const commentBody = fs.readFileSync(commentPath, 'utf8');
            const prNumber = parseInt('${{ steps.pr-info.outputs.pr_number }}');
            const prSha = '${{ steps.pr-info.outputs.pr_sha }}';

            if (!prNumber) {
              console.log('Invalid PR number');
              return;
            }

            // Get existing comments
            const { data: comments } = await github.rest.issues.listComments({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber,
            });

            // Find ALL ASH security scan comments
            const ashComments = comments.filter(comment => 
              comment.user.type === 'Bot' && 
              (comment.body.includes('<!-- ASH-SECURITY-SCAN-COMMENT -->') ||
               comment.body.includes('## Security Scan Results') ||
               comment.body.includes('Latest scan for commit:') ||
               comment.body.includes('ASH Security Scan Report'))
            );

            console.log(`Found ${ashComments.length} ASH security scan comments`);

            // Use the most recent ASH comment (highest ID = most recent)
            const existingComment = ashComments.length > 0 ? 
              ashComments.sort((a, b) => b.id - a.id)[0] : null;

            // Delete any duplicate/older ASH comments (keep only the most recent one)
            if (ashComments.length > 1) {
              console.log(`Cleaning up ${ashComments.length - 1} duplicate ASH comments`);
              for (const comment of ashComments.slice(1)) {
                try {
                  await github.rest.issues.deleteComment({
                    owner: context.repo.owner,
                    repo: context.repo.repo,
                    comment_id: comment.id,
                  });
                  console.log(`Deleted duplicate comment ${comment.id}`);
                } catch (error) {
                  console.log(`Failed to delete comment ${comment.id}: ${error.message}`);
                }
              }
            }

            // Add commit and timestamp info to the body
            const timestamp = new Date().toISOString().replace('T', ' ').substring(0, 19) + ' UTC';
            const shortSha = prSha ? prSha.substring(0, 7) : 'unknown';
            const enhancedBody = `**Latest scan for commit:** \`${shortSha}\` **| Updated:** ${timestamp}\n\n${commentBody}\n\n<!-- ASH-SECURITY-SCAN-COMMENT -->`;

            if (existingComment) {
              // Update existing comment
              console.log(`Updating existing comment ${existingComment.id}`);
              await github.rest.issues.updateComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                comment_id: existingComment.id,
                body: enhancedBody
              });
              console.log('Successfully updated existing ASH security scan comment');
            } else {
              // Create new comment
              console.log('No existing ASH comment found, creating new one');
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: prNumber,
                body: enhancedBody
              });
              console.log('Successfully created new ASH security scan comment');
            }

name: '[CI] Manual'
run-name: "#${{ inputs.pr_number }} - ${{ inputs.uuid }}"
on:
  workflow_dispatch:
    inputs:
      requester:
        required: true
        type: string
      comment_url:
        required: true
        type: string
      uuid:
        required: true
        type: string
      pr_number:
        required: true
        type: string
      git_sha:
        required: true
        type: string
      goal:
        required: true
        type: choice
        default: "test"
        options:
          - "build"
          - "test"
      os_distros:
        description: 'Operating System Distributions (comma-separated, e.g., al2,al2023)'
        default: "al2,al2023"
        required: false
        type: string
      k8s_versions:
        description: 'Kubernetes Versions (comma-separated, e.g., 1.29,1.30)'
        required: false
        type: string
      build_arguments:
        required: false
        type: string
      test_arguments:
        required: false
        type: string

permissions:
  pull-requests: write
  issues: write
  contents: read
  id-token: write

jobs:
  setup:
    runs-on: ubuntu-latest
    outputs:
      git_sha_short: ${{ steps.variables.outputs.git_sha_short }}
      workflow_run_url: ${{ steps.variables.outputs.workflow_run_url }}
    steps:
    - id: variables
      run: |
        echo "git_sha_short=$(echo ${{ inputs.git_sha }} | rev | cut -c-7 | rev)" >> $GITHUB_OUTPUT
        echo "workflow_run_url=https://github.com/${{ github.repository }}/actions/runs/${{ github.run_id }}" >> $GITHUB_OUTPUT

  notify-start:
    runs-on: ubuntu-latest
    needs:
      - setup
    steps:
      - uses: actions/github-script@ed597411d8f924073f98dfc5c65a23a2325f34cd # 8.0.0
        with:
          script: |
            github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: ${{ inputs.pr_number }},
              body: `@${{ inputs.requester }} roger [that](${{ inputs.comment_url }})! I've dispatched a [workflow](${{ needs.setup.outputs.workflow_run_url }}). 👍`
            });
  ci:
    uses: ./.github/workflows/ci.yaml
    needs:
      - setup
      - notify-start
    secrets: inherit
    with:
      k8s_versions: ${{ inputs.k8s_versions }}
      os_distros: ${{ inputs.os_distros }}
      git_sha: ${{ inputs.git_sha }}
      build_arguments: ${{ inputs.build_arguments }}
      test_arguments: ${{ inputs.test_arguments }}
      resource_id: "ci-${{ inputs.pr_number }}-${{ needs.setup.outputs.git_sha_short }}-${{ inputs.uuid }}"
      run_name: "ci(#${{ inputs.pr_number }}@${{ needs.setup.outputs.git_sha_short }}): ${{ inputs.uuid }}"
      goal: "${{ inputs.goal }}"

  notify-outcome:
    if: ${{ always() }}
    runs-on: ubuntu-latest
    needs:
      - setup
      - ci
    steps:
      - uses: actions/github-script@ed597411d8f924073f98dfc5c65a23a2325f34cd # 8.0.0
        with:
          script: |
            const { data } = await github.rest.actions.listJobsForWorkflowRun({
              owner: context.repo.owner,
              repo: context.repo.repo,
              run_id: context.runId
            });
            const conclusionEmojis = {
              "success": "✅",
              "skipped": "⏭️",
              "failure": "❌",
              "cancelled": "🚮"
            };
            const uniqueStepNames = new Set();
            const stepConclusionsByJob = new Map();
            const ciStepNamePrefix = "${{ needs.ci.outputs.ci_step_name_prefix }}";
            for (const job of data.jobs) {
              // look for jobs named "ci / k8sVersion / osDistro"
              if (/^ci \/ \d+\.\d+/.test(job.name)) {
                // remove the "ci /" prefix
                const jobName = job.name.substring("ci /".length).trim();
                for (const step of job.steps) {
                  if (step.name.startsWith(ciStepNamePrefix)) {
                    const stepName = step.name.substring(ciStepNamePrefix.length).trim();
                    let stepConclusions = stepConclusionsByJob.get(jobName);
                    if (!stepConclusions) {
                      stepConclusions = new Map();
                      stepConclusionsByJob.set(jobName, stepConclusions);
                    }
                    stepConclusions.set(stepName, step.conclusion);
                    uniqueStepNames.add(stepName);
                  }
                }
              }
            }
            const headers = [{
              data: 'AMI variant',
              header: true
            }];
            for (const stepName of uniqueStepNames.values()) {
              headers.push({
                  data: stepName,
                  header: true
              });
            }
            const rows = [];
            for (const stepConclusionsForJob of [...stepConclusionsByJob.entries()].sort()) {
              const job = stepConclusionsForJob[0];
              const row = [job];
              for (const step of stepConclusionsForJob[1].entries()) {
                  row.push(`${step[1]} ${conclusionEmojis[step[1]]}`);
              }
              rows.push(row);
            }
            const commentBody = core.summary
              .addRaw("@${{ inputs.requester }} the <a href=${{ needs.setup.outputs.workflow_run_url }}>workflow</a> that you <a href=${{ inputs.comment_url }}>requested</a> has completed. 🎉")
              .addTable([
                headers,
                ...rows,
              ])
              .stringify();
            github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: ${{ inputs.pr_number }},
              body: commentBody
            });

name: Lexical e2e canary test

on:
  workflow_call:

permissions: {}

jobs:
  canary:
    strategy:
      matrix:
        os: ['ubuntu-latest']
        node-version: [22.x]
        browser: ['chromium']
        editor-mode: ['rich-text']
        events-mode: ['modern-events']
    uses: ./.github/workflows/call-e2e-test.yml
    with:
      os: ${{ matrix.os }}
      node-version: ${{ matrix.node-version }}
      browser: ${{ matrix.browser }}
      editor-mode: ${{ matrix.editor-mode }}
      events-mode: ${{ matrix.events-mode }}

name: Lexical e2e test runner

on:
  workflow_call:
    inputs:
      # Make sure that all of these are present in the name of the actions/upload-artifact@v4 action below
      os: {required: true, type: string}
      node-version: {required: true, type: string}
      browser: {required: true, type: string}
      editor-mode: {required: true, type: string}
      events-mode: {required: true, type: string}
      prod: {required: false, type: boolean}
      flaky: {required: false, type: boolean} # Defaults to false: dont run flaky
      override-react-version: {required: false, type: string}

permissions: {}

jobs:
  e2e-test:
    runs-on: ${{ inputs.os }}
    continue-on-error: ${{ inputs.flaky }}
    if: (inputs.browser != 'webkit' || inputs.os == 'macos-latest') && (inputs.editor-mode != 'rich-text-with-collab' || inputs.events-mode != 'legacy-events')
    env:
      CI: true
      E2E_EDITOR_MODE: ${{ inputs.editor-mode }}
      E2E_EVENTS_MODE: ${{ inputs.events-mode }}
      OVERRIDE_REACT_VERSION: ${{ inputs.override-react-version }}
      cache_playwright_path: ${{ inputs.os == 'macos-latest' && '~/Library/Caches/ms-playwright' || inputs.os == 'windows-latest' && 'C:\Users\runneradmin\AppData\Local\ms-playwright' || '~/.cache/ms-playwright' }}
      test_results_path: 'test-results/'
      test_script: test-e2e-${{ inputs.editor-mode == 'rich-text-with-collab' && 'collab-' || '' }}${{ inputs.prod && 'prod-' || '' }}ci-${{ inputs.browser }}
    steps:
      - uses: actions/checkout@v4
      - name: Use Node.js ${{ inputs.node-version }}
        uses: actions/setup-node@v4
        with:
          node-version: ${{ inputs.node-version }}
      - uses: pnpm/action-setup@v4
        with:
          version: 9
      - name: Install required ubuntu-latest packages
        if: inputs.os == 'ubuntu-latest'
        run: |
          sudo apt-get update
          sudo apt-get install xvfb
      - name: Install dependencies
        run: pnpm install --frozen-lockfile
      - name: Install React ${{ inputs.override-react-version }}
        if: inputs.override-react-version != ''
        # This should be safe since we are caching pnpm store and not node_modules
        run: |
          node ./scripts/override-react.js --version=${{ inputs.override-react-version }}
          grep version node_modules/{react,react-dom}/package.json
      - name: Restore playwright from cache
        uses: actions/cache/restore@v4
        id: playwright-cache
        with:
          path: ${{ env.cache_playwright_path }}
          key: playwright-${{ inputs.node-version }}-${{ runner.os }}-${{ runner.arch }}-v${{ secrets.CACHE_VERSION }}-${{ hashFiles('pnpm-lock.yaml') }}
      - name: Install playwright
        run: pnpm exec playwright install
      - name: Save playwright to cache
        uses: actions/cache/save@v4
        if: steps.playwright-cache.outputs.cache-hit != 'true'
        with:
          path: ${{ env.cache_playwright_path }}
          key: ${{ steps.playwright-cache.outputs.cache-primary-key }}
      - name: Run tests
        run: pnpm run ${{ env.test_script }}
      - name: Upload Artifacts
        if: failure()
        uses: actions/upload-artifact@v4
        with:
          name: Test Results ${{ inputs.os }}-${{ inputs.browser }}-${{ inputs.editor-mode }}-${{ inputs.events-mode }}-${{ inputs.prod && 'prod' || 'dev' }}-${{ inputs.node-version }}-${{ inputs.override-react-version }}-${{ inputs.flaky && 'flaky' || ''}}
          path: ${{ env.test_results_path }}
          retention-days: 7

name: Classify mypy_primer diff

on:  # zizmor: ignore[dangerous-triggers]
  workflow_run:
    workflows:
      - Run mypy_primer
    types:
      - completed

permissions: {}

jobs:
  classify:
    name: Classify primer diff
    runs-on: ubuntu-latest
    permissions:
      contents: read
      pull-requests: write
    if: ${{ github.event.workflow_run.conclusion == 'success' }}
    steps:
      - uses: actions/checkout@v6
        with:
          sparse-checkout: scripts/primer_classifier
          persist-credentials: false

      - uses: actions/setup-python@v6
        with:
          python-version: "3.13"

      - name: Download diffs
        uses: actions/github-script@v8
        with:
          script: |
            const fs = require('fs');
            const artifacts = await github.rest.actions.listWorkflowRunArtifacts({
               owner: context.repo.owner,
               repo: context.repo.repo,
               run_id: ${{ github.event.workflow_run.id }},
            });
            const [matchArtifact] = artifacts.data.artifacts.filter((artifact) =>
              artifact.name == "mypy_primer_diffs");

            const download = await github.rest.actions.downloadArtifact({
               owner: context.repo.owner,
               repo: context.repo.repo,
               artifact_id: matchArtifact.id,
               archive_format: "zip",
            });
            fs.writeFileSync("diff.zip", Buffer.from(download.data));

      - run: unzip diff.zip
      - run: cat diff_*.txt | tee fulldiff.txt

      - name: Fetch PR code diff and description
        uses: actions/github-script@v8
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const fs = require('fs');
            const prNumber = parseInt(fs.readFileSync("pr_number.txt", { encoding: "utf8" }));
            const { data: pr } = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: prNumber,
            });
            const description = `# ${pr.title}\n\n${pr.body || ''}`;
            fs.writeFileSync("pr_description.txt", description);
            console.log(`Fetched PR #${prNumber} description (${description.length} chars)`);
            const { data: diff } = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: prNumber,
              mediaType: { format: 'diff' },
            });
            fs.writeFileSync("pr_code.diff", diff);
            console.log(`Fetched PR #${prNumber} diff (${diff.length} chars)`);

      - name: Classify diff
        run: |
          python -m scripts.primer_classifier \
            --diff-file fulldiff.txt \
            --pyrefly-diff pr_code.diff \
            --pr-description pr_description.txt \
            --suggest \
            --output-format markdown \
            | tee classification.md
        env:
          CLASSIFIER_API_KEY: ${{ secrets.PRIMER_CLASSIFIER_API_KEY }}
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}

      - name: Post classification comment
        if: ${{ hashFiles('classification.md') != '' }}
        uses: actions/github-script@v8
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const fs = require('fs')
            const body = fs.readFileSync('classification.md', { encoding: 'utf8' })
            if (body.trim()) {
              const prNumber = parseInt(fs.readFileSync("pr_number.txt", { encoding: "utf8" }))
              await github.rest.issues.createComment({
                issue_number: prNumber,
                owner: context.repo.owner,
                repo: context.repo.repo,
                body
              })
            }

name: Comment with mypy_primer diff

on:  # zizmor: ignore[dangerous-triggers]
  workflow_run:
    workflows:
      - Run mypy_primer
    types:
      - completed

permissions: {}

jobs:
  comment:
    name: Comment PR from mypy_primer
    runs-on: ubuntu-latest
    permissions:
      contents: read
      pull-requests: write
    if: ${{ github.event.workflow_run.conclusion == 'success' }}
    steps:
      - name: Download diffs
        uses: actions/github-script@v8
        with:
          script: |
            const fs = require('fs');
            const artifacts = await github.rest.actions.listWorkflowRunArtifacts({
               owner: context.repo.owner,
               repo: context.repo.repo,
               run_id: ${{ github.event.workflow_run.id }},
            });
            const [matchArtifact] = artifacts.data.artifacts.filter((artifact) =>
              artifact.name == "mypy_primer_diffs");

            const download = await github.rest.actions.downloadArtifact({
               owner: context.repo.owner,
               repo: context.repo.repo,
               artifact_id: matchArtifact.id,
               archive_format: "zip",
            });
            fs.writeFileSync("diff.zip", Buffer.from(download.data));

      - run: unzip diff.zip
      - run: |
          cat diff_*.txt | tee fulldiff.txt

      - name: Post comment
        id: post-comment
        uses: actions/github-script@v8
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const MAX_CHARACTERS = 100000
            const MAX_CHARACTERS_PER_PROJECT = MAX_CHARACTERS / 4

            const fs = require('fs')
            let data = fs.readFileSync('fulldiff.txt', { encoding: 'utf8' })

            function truncateIfNeeded(original, maxLength) {
              if (original.length <= maxLength) {
                return original
              }
              let truncated = original.substring(0, maxLength)
              // further, remove last line that might be truncated
              truncated = truncated.substring(0, truncated.lastIndexOf('\n'))
              let lines_truncated = original.split('\n').length - truncated.split('\n').length
              return `${truncated}\n\n... (truncated ${lines_truncated} lines) ...`
            }

            const projects = data.split('\n\n')
            // don't let one project dominate
            data = projects.map(project => truncateIfNeeded(project, MAX_CHARACTERS_PER_PROJECT)).join('\n\n')
            // posting comment fails if too long, so truncate
            data = truncateIfNeeded(data, MAX_CHARACTERS)

            console.log("Diff from mypy_primer:")
            console.log(data)

            let body
            if (data.trim()) {
              body = 'Diff from [mypy_primer](https://github.com/hauntsaninja/mypy_primer), showing the effect of this PR on open source code:\n```diff\n' + data + '```'
            } else {
              body = "According to [mypy_primer](https://github.com/hauntsaninja/mypy_primer), this change doesn't affect type check results on a corpus of open source code. ✅"
            }
            const prNumber = parseInt(fs.readFileSync("pr_number.txt", { encoding: "utf8" }))
            await github.rest.issues.createComment({
              issue_number: prNumber,
              owner: context.repo.owner,
              repo: context.repo.repo,
              body
            })
            return prNumber

      - name: Hide old comments
        # v0.4.0
        uses: kanga333/comment-hider@c12bb20b48aeb8fc098e35967de8d4f8018fffdf
        with:
          github_token: ${{ secrets.GITHUB_TOKEN }}
          leave_visible: 1
          issue_number: ${{ steps.post-comment.outputs.result }}

name: Label issues and PRs that need triage

on:
  schedule:
    # Run once every weekday at 9AM PT / 12PM ET
    - cron: '0 16 * * 1-5'
  workflow_dispatch:  # Allow manual triggering

permissions:
  issues: write
  pull-requests: write

jobs:
  label-issues:
    runs-on: ubuntu-latest
    steps:
      - name: Label issues that need triage
        uses: actions/github-script@v8
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            // Get current date and calculate the date 48 hours ago
            const now = new Date();
            const twoDaysAgo = new Date(now);
            twoDaysAgo.setHours(now.getHours() - 48);

            console.log(`Finding issues that need triage created before ${twoDaysAgo.toISOString()}...`);

            // Get 100 oldest issues without a Bug/Feature/Task type
            const { data: issues } = await github.rest.issues.listForRepo({
              owner: context.repo.owner,
              repo: context.repo.repo,
              state: 'open',
              type: 'none',
              per_page: 100,
              sort: 'created',
              direction: 'asc'
            });

            // Select issues that:
            // 1. Were created before the cutoff date
            // 2. Do not have the 'question' or 'needs-discussion' label
            // 3. Are not pull requests
            const oldIssues = issues.filter(issue => {
              const createdAt = new Date(issue.created_at);
              return createdAt < twoDaysAgo &&
                     !issue.labels.some((label) => label.name == 'question' || label.name == 'needs-discussion') &&
                     !issue.pull_request;
            });

            console.log(`Found ${oldIssues.length} old issues that need triage`);

            // Add 'needs-triage' label to each issue
            for (const issue of oldIssues) {
              console.log(`Adding 'needs-triage' label to issue #${issue.number}: ${issue.title}`);

              await github.rest.issues.addLabels({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: issue.number,
                labels: ['needs-triage']
              });
            }

            console.log('Finished labeling issues that need triage');
  label-prs:
    runs-on: ubuntu-latest
    steps:
      - name: Label pull requests that need triage
        uses: actions/github-script@v8
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            // Get current date and calculate the date 48 hours ago
            const now = new Date();
            const twoDaysAgo = new Date(now);
            twoDaysAgo.setHours(now.getHours() - 48);

            console.log(`Finding pull requests that need triage created before ${twoDaysAgo.toISOString()}...`);

            // Get 100 oldest pull requests
            const { data: prs } = await github.rest.pulls.list({
              owner: context.repo.owner,
              repo: context.repo.repo,
              state: 'open',
              per_page: 100,
              sort: 'created',
              direction: 'asc'
            });

            // Select non-draft pull requests that:
            // 1. Were created before the cutoff date
            // 2. Do not have the 'fb-exported' label
            // 3. Do not have a requested reviewer or assignee
            // 4. Do not have a review
            var oldPRs = [];
            for (const pr of prs) {
              const createdAt = new Date(pr.created_at);
              if (pr.draft ||
                  createdAt >= twoDaysAgo ||
                  pr.labels.some((label) => label.name == 'fb-exported') ||
                  (Array.isArray(pr.requested_reviewers) && pr.requested_reviewers.length) ||
                  (Array.isArray(pr.assignees) && pr.assignees.length)) {
                continue;
              }
              const { data: reviews } = await github.rest.pulls.listReviews({
                owner: context.repo.owner,
                repo: context.repo.repo,
                pull_number: pr.number
              });
              if (!reviews.length) {
                oldPRs.push(pr);
              }
            }

            console.log(`Found ${oldPRs.length} old pull requests that need triage`);

            // Add 'needs-triage' label to each PR
            for (const pr of oldPRs) {
              console.log(`Adding 'needs-triage' label to PR #${pr.number}: ${pr.title}`);

              await github.rest.issues.addLabels({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: pr.number,
                labels: ['needs-triage']
              });
            }

            console.log('Finished labeling pull requests that need triage');

name: (Compiler) Discord Notify

on:
  pull_request_target:
    types: [opened, ready_for_review]
    paths:
      - compiler/**
      - .github/workflows/compiler_**.yml

permissions: {}

jobs:
  check_access:
    if: ${{ github.event.pull_request.draft == false }}
    runs-on: ubuntu-latest
    outputs:
      is_member_or_collaborator: ${{ steps.check_is_member_or_collaborator.outputs.is_member_or_collaborator }}
    steps:
      - run: echo ${{ github.event.pull_request.author_association }}
      - name: Check is member or collaborator
        id: check_is_member_or_collaborator
        if: ${{ github.event.pull_request.author_association == 'MEMBER' || github.event.pull_request.author_association == 'COLLABORATOR' }}
        run: echo "is_member_or_collaborator=true" >> "$GITHUB_OUTPUT"

  check_maintainer:
    if: ${{ needs.check_access.outputs.is_member_or_collaborator == 'true' || needs.check_access.outputs.is_member_or_collaborator == true }}
    needs: [check_access]
    uses: facebook/react/.github/workflows/shared_check_maintainer.yml@main
    permissions:
      # Used by check_maintainer
      contents: read
    with:
      actor: ${{ github.event.pull_request.user.login }}

  notify:
    if: ${{ needs.check_maintainer.outputs.is_core_team == 'true' }}
    needs: check_maintainer
    runs-on: ubuntu-latest
    steps:
      - name: Discord Webhook Action
        uses: tsickert/discord-webhook@86dc739f3f165f16dadc5666051c367efa1692f4
        with:
          webhook-url: ${{ secrets.COMPILER_DISCORD_WEBHOOK_URL }}
          embed-author-name: ${{ github.event.pull_request.user.login }}
          embed-author-url: ${{ github.event.pull_request.user.html_url }}
          embed-author-icon-url: ${{ github.event.pull_request.user.avatar_url }}
          embed-title: '#${{ github.event.number }} (+${{github.event.pull_request.additions}} -${{github.event.pull_request.deletions}}): ${{ github.event.pull_request.title }}'
          embed-description: ${{ github.event.pull_request.body }}
          embed-url: ${{ github.event.pull_request.html_url }}

