      with:
       path: ${{ steps.paths.outputs.xz_INSTALL }}
       key: ${{ steps.paths.outputs.xz_CACHE_KEY }}-install
    - name: Build xz
      if: ${{ steps.paths.outputs.xz_SOURCE && ! steps.restore_xz.outputs.cache-hit }}
      run: python3 build/fbcode_builder/getdeps.py --allow-system-packages build --no-tests xz
    - name: Save xz to cache
      uses: actions/cache/save@v4
      if: ${{ steps.paths.outputs.xz_SOURCE && ! steps.restore_xz.outputs.cache-hit }}
      with:
       path: ${{ steps.paths.outputs.xz_INSTALL }}
       key: ${{ steps.paths.outputs.xz_CACHE_KEY }}-install
    - name: Restore folly from cache
      id: restore_folly
      if: ${{ steps.paths.outputs.folly_SOURCE }}
      uses: actions/cache/restore@v4
      with:
       path: ${{ steps.paths.outputs.folly_INSTALL }}
       key: ${{ steps.paths.outputs.folly_CACHE_KEY }}-install
    - name: Build folly
      if: ${{ steps.paths.outputs.folly_SOURCE && ! steps.restore_folly.outputs.cache-hit }}
      run: python3 build/fbcode_builder/getdeps.py --allow-system-packages build --no-tests folly
    - name: Save folly to cache
      uses: actions/cache/save@v4
      if: ${{ steps.paths.outputs.folly_SOURCE && ! steps.restore_folly.outputs.cache-hit }}
      with:
       path: ${{ steps.paths.outputs.folly_INSTALL }}
       key: ${{ steps.paths.outputs.folly_CACHE_KEY }}-install
    - name: Restore fizz from cache
      id: restore_fizz
      if: ${{ steps.paths.outputs.fizz_SOURCE }}
      uses: actions/cache/restore@v4
      with:
       path: ${{ steps.paths.outputs.fizz_INSTALL }}
       key: ${{ steps.paths.outputs.fizz_CACHE_KEY }}-install
    - name: Build fizz
      if: ${{ steps.paths.outputs.fizz_SOURCE && ! steps.restore_fizz.outputs.cache-hit }}
      run: python3 build/fbcode_builder/getdeps.py --allow-system-packages build --no-tests fizz
    - name: Save fizz to cache
      uses: actions/cache/save@v4
      if: ${{ steps.paths.outputs.fizz_SOURCE && ! steps.restore_fizz.outputs.cache-hit }}
      with:
       path: ${{ steps.paths.outputs.fizz_INSTALL }}
       key: ${{ steps.paths.outputs.fizz_CACHE_KEY }}-install
    - name: Build wangle
      run: python3 build/fbcode_builder/getdeps.py --allow-system-packages build --src-dir=. wangle --project-install-prefix wangle:/usr/local
    - name: Copy artifacts
      run: python3 build/fbcode_builder/getdeps.py --allow-system-packages fixup-dyn-deps --src-dir=. wangle _artifacts/mac --project-install-prefix wangle:/usr/local --final-install-prefix /usr/local
    - uses: actions/upload-artifact@v6
      with:
        name: wangle
        path: _artifacts
    - name: Test wangle
      run: python3 build/fbcode_builder/getdeps.py --allow-system-packages test --src-dir=. wangle --project-install-prefix wangle:/usr/local

name: Add issue header
# Automatically edits an issue's descriptions with a header,
# one of:
#
# - Bug report
# - Crash report
# - Feature or enhancement

on:
  issues:
    types:
      # Only ever run once
      - opened


jobs:
  add-header:
    runs-on: ubuntu-latest
    permissions:
      issues: write
    timeout-minutes: 5
    steps:
      - uses: actions/github-script@v8
        with:
          # language=JavaScript
          script: |
            // https://devguide.python.org/triage/labels/#type-labels
            const HEADERS = new Map([
              ['type-bug', 'Bug report'],
              ['type-crash', 'Crash report'],
              ['type-feature', 'Feature or enhancement'],
            ]);
            let issue_data = await github.rest.issues.get({
              issue_number: context.issue.number,
              owner: context.repo.owner,
              repo: context.repo.repo
            }).then(issue => issue.data);
            let header = '';
            for (const label_data of issue_data.labels) {
                const label_name = (typeof label_data === 'string') ? label_data : label_data.name;
                if (HEADERS.has(label_name)) {
                    header = HEADERS.get(label_name);
                    break;
                }
            }
            if (header !== '') {
              console.log(`Setting new header: ${header}`);
              await github.rest.issues.update({
                  issue_number: context.issue.number,
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  body: `# ${header}\n\n${issue_data.body.replaceAll('\r', '')}`
              });
            }

name: new-bugs-announce notifier

on:
  issues:
    types:
      - opened

permissions:
  issues: read

jobs:
  notify-new-bugs-announce:
    runs-on: ubuntu-latest
    timeout-minutes: 10
    steps:
      - uses: actions/setup-node@v6
        with:
          node-version: 20
      - run: npm install mailgun.js form-data
      - name: Send notification
        uses: actions/github-script@v8
        env:
          MAILGUN_API_KEY: ${{ secrets.MAILGUN_PYTHON_ORG_MAILGUN_KEY }}
        with:
          script: |
            const Mailgun = require("mailgun.js");
            const formData = require('form-data');
            const mailgun = new Mailgun(formData);
            const DOMAIN = "mailgun.python.org";
            const mg = mailgun.client({username: 'api', key: process.env.MAILGUN_API_KEY});
            github.rest.issues.get({
              issue_number: context.issue.number,
              owner: context.repo.owner,
              repo: context.repo.repo,
            })
            .then(function(issue) {
              const payload = {
                author : issue.data.user.login,
                issue  : issue.data.number,
                title  : issue.data.title,
                url    : issue.data.html_url,
                labels : issue.data.labels.map(label => { return label.name }).join(", "),
                assignee : issue.data.assignees.map(assignee => { return assignee.login }),
                // We need to truncate the body size, because the max size for
                // the whole payload is 16kb. We want to be safe and assume that
                // body can take up to ~8kb of space.
                body   : issue.data.body.substring(0, 8000)
              };

              const data = {
                from: "CPython Issues <github@mailgun.python.org>",
                to: "new-bugs-announce@python.org",
                subject: `[Issue ${issue.data.number}] ${issue.data.title}`,
                template: "new-github-issue",
                'o:tracking-clicks': 'no',
                'h:X-Mailgun-Variables': JSON.stringify(payload)
              };
              return mg.messages.create(DOMAIN, data)
            })
            .then(msg => console.log(msg));

name: Check issue template

on:
  issues:
    types: [opened]

jobs:
  check-template:
    runs-on: ubuntu-latest
    # comment this out when testing with https://github.com/nektos/act
    if: ${{ github.repository_owner == 'facebookresearch' }}
    steps:
      - uses: actions/checkout@v2
      - uses: actions/github-script@v3
        with:
          github-token: ${{secrets.GITHUB_TOKEN}}
          script: |
            // Arguments available:
            // - github: A pre-authenticated octokit/rest.js client
            // - context: An object containing the context of the workflow run
            // - core: A reference to the @actions/core package
            // - io: A reference to the @actions/io package
            const fs = require('fs');
            const editDistance = require(`${process.env.GITHUB_WORKSPACE}/.github/workflows/levenshtein.js`).getEditDistance
            issue = await github.issues.get({
              owner: context.issue.owner,
              repo: context.issue.repo,
              issue_number: context.issue.number,
            });
            const hasLabel = issue.data.labels.length > 0;
            if (hasLabel || issue.state === "closed") {
              // don't require template on them
              core.debug("Issue " + issue.data.title + " was skipped.");
              return;
            }

            sameAsTemplate = function(filename, body) {
              let tmpl = fs.readFileSync(`.github/ISSUE_TEMPLATE/${filename}`, 'utf8');
              tmpl = tmpl.toLowerCase().split("---").slice(2).join("").trim();
              tmpl = tmpl.replace(/(\r\n|\n|\r)/gm, "");
              let bodyr = body.replace(/(\r\n|\n|\r)/gm, "");
              let dist = editDistance(tmpl, bodyr);
              return dist < 8;
            };

            checkFail = async function(msg) {
              core.info("Processing '" + issue.data.title + "' with message: " + msg);
              await github.issues.addLabels({
                owner: context.issue.owner,
                repo: context.issue.repo,
                issue_number: context.issue.number,
                labels: ["needs-more-info"],
              });
              await github.issues.createComment({
                owner: context.issue.owner,
                repo: context.issue.repo,
                issue_number: context.issue.number,
                body: msg,
              });
            };

            const body = issue.data.body.toLowerCase().trim();

            if (sameAsTemplate("bugs.md", body) || sameAsTemplate("unexpected-problems-bugs.md", body)) {
              await checkFail(`
            We found that not enough information is provided about this issue.
            Please provide details following the [issue template](https://github.com/facebookresearch/detectron2/issues/new/choose).`)
              return;
            }

            const hasInstructions = body.indexOf("reproduce") != -1;
            const hasEnvironment = (body.indexOf("environment") != -1) || (body.indexOf("colab") != -1) || (body.indexOf("docker") != -1);
            if (hasInstructions && hasEnvironment) {
              core.debug("Issue " + issue.data.title + " follows template.");
              return;
            }

            let message = "You've chosen to report an unexpected problem or bug. Unless you already know the root cause of it, please include details about it by filling the [issue template](https://github.com/facebookresearch/detectron2/issues/new/choose).\n";
            message += "The following information is missing: ";
            if (!hasInstructions) {
              message += "\"Instructions To Reproduce the Issue and __Full__ Logs\"; ";
            }
            if (!hasEnvironment) {
              message += "\"Your Environment\"; ";
            }
            await checkFail(message);

name: Close/Lock issues after inactivity

on:
  schedule:
    - cron: "42 1 * * *"

jobs:
  close-issues-needs-more-info:
    runs-on: ubuntu-latest
    if: ${{ github.repository_owner == 'facebookresearch' }}
    steps:
      - name: Close old issues that need reply
        uses: actions/github-script@v3
        with:
          github-token: ${{secrets.GITHUB_TOKEN}}
          # Modified from https://github.com/dwieeb/needs-reply
          script: |
            // Arguments available:
            // - github: A pre-authenticated octokit/rest.js client
            // - context: An object containing the context of the workflow run
            // - core: A reference to the @actions/core package
            // - io: A reference to the @actions/io package
            const kLabelToCheck = "needs-more-info";
            const kInvalidLabel = "invalid/unrelated";
            const kDaysBeforeClose = 7;
            const kMessage = "Requested information was not provided in 7 days, so we're closing this issue.\n\nPlease open new issue if information becomes available. Otherwise, use [github discussions](https://github.com/facebookresearch/detectron2/discussions) for free-form discussions."

            issues = await github.issues.listForRepo({
              owner: context.repo.owner,
              repo: context.repo.repo,
              state: 'open',
              labels: kLabelToCheck,
              sort: 'updated',
              direction: 'asc',
              per_page: 30,
              page: 1,
            });
            issues = issues.data;
            if (issues.length === 0) {
              core.info('No more issues found to process. Exiting.');
              return;
            }
            for (const issue of issues) {
              if (!!issue.pull_request)
                continue;
              core.info(`Processing issue #${issue.number}`);

              let updatedAt = new Date(issue.updated_at).getTime();
              const numComments = issue.comments;
              const comments = await github.issues.listComments({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: issue.number,
                per_page: 30,
                page: Math.floor((numComments - 1) / 30) + 1, // the last page
              });
              const lastComments = comments.data
                .map(l => new Date(l.created_at).getTime())
                .sort();
              if (lastComments.length > 0) {
                updatedAt = lastComments[lastComments.length - 1];
              }

              const now = new Date().getTime();
              const daysSinceUpdated = (now - updatedAt) / 1000 / 60 / 60 / 24;

              if (daysSinceUpdated < kDaysBeforeClose) {
                core.info(`Skipping #${issue.number} because it has been updated in the last ${daysSinceUpdated} days`);
                continue;
              }
              core.info(`Closing #${issue.number} because it has not been updated in the last ${daysSinceUpdated} days`);
              await github.issues.createComment({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: issue.number,
                  body: kMessage,
              });
              const newLabels = numComments <= 2 ? [kInvalidLabel, kLabelToCheck] : issue.labels;
              await github.issues.update({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: issue.number,
                labels: newLabels,
                state: 'closed',
              });
            }

  lock-issues-after-closed:
    runs-on: ubuntu-latest
    if: ${{ github.repository_owner == 'facebookresearch' }}
    steps:
      - name: Lock closed issues that have no activity for a while
        uses: dessant/lock-threads@v2
        with:
          github-token: ${{ github.token }}
          issue-lock-inactive-days: '300'
          process-only: 'issues'
          issue-exclude-labels: 'enhancement,bug,documentation'

name: Copybara PR Handler

on:
  push:
    branches:
      - main
  workflow_dispatch:
    inputs:
      pr_number:
        description: 'PR number to close (for testing)'
        required: true
        type: string
      commit_sha:
        description: 'Commit SHA reference (optional, for testing)'
        required: false
        type: string

jobs:
  close-imported-pr:
    runs-on: ubuntu-latest
    permissions:
      pull-requests: write
      issues: write
      contents: read

    steps:
      - name: Check for Copybara commits and close PRs
        uses: actions/github-script@v8
        with:
          github-token: ${{ secrets.ADK_TRIAGE_AGENT }}
          script: |
            // Check if this is a manual test run
            const isManualRun = context.eventName === 'workflow_dispatch';

            let prsToClose = [];

            if (isManualRun) {
              // Manual testing mode
              const prNumber = parseInt(context.payload.inputs.pr_number);
              const commitSha = context.payload.inputs.commit_sha || context.sha.substring(0, 7);

              console.log('=== MANUAL TEST MODE ===');
              console.log(`Testing with PR #${prNumber}, commit ${commitSha}`);

              prsToClose.push({ prNumber, commitSha });
            } else {
              // Normal mode: process commits from push event
              const commits = context.payload.commits || [];
              console.log(`Found ${commits.length} commit(s) in this push`);

              // Process each commit
              for (const commit of commits) {
                const sha = commit.id;
                const committer = commit.committer.name;
                const message = commit.message;

                console.log(`\n--- Processing commit ${sha.substring(0, 7)} ---`);
                console.log(`Committer: ${committer}`);

                // Check if this is a Copybara commit
                if (committer !== 'Copybara-Service') {
                  console.log('Not a Copybara commit, skipping');
                  continue;
                }

                // Extract PR number from commit message
                // Pattern: "Merge https://github.com/google/adk-python/pull/3333"
                const prMatch = message.match(/Merge https:\/\/github\.com\/google\/adk-python\/pull\/(\d+)/);

                if (!prMatch) {
                  console.log('No PR number found in Copybara commit message');
                  continue;
                }

                const prNumber = parseInt(prMatch[1]);
                const commitSha = sha.substring(0, 7);

                prsToClose.push({ prNumber, commitSha });
              }
            }

            // Process PRs to close
            for (const { prNumber, commitSha } of prsToClose) {
              console.log(`\n--- Processing PR #${prNumber} ---`);

              // Get PR details to check if it's open
              let pr;
              try {
                pr = await github.rest.pulls.get({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  pull_number: prNumber
                });
              } catch (error) {
                console.log(`PR #${prNumber} not found or inaccessible:`, error.message);
                continue;
              }

              // Only close if PR is still open
              if (pr.data.state !== 'open') {
                console.log(`PR #${prNumber} is already ${pr.data.state}, skipping`);
                continue;
              }

              const author = pr.data.user.login;

              try {
                // Add comment with commit reference
                await github.rest.issues.createComment({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: prNumber,
                  body: `Thank you @${author} for your contribution! 🎉\n\nYour changes have been successfully imported and merged via Copybara in commit ${commitSha}.\n\nClosing this PR as the changes are now in the main branch.`
                });

                // Close the PR
                await github.rest.pulls.update({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  pull_number: prNumber,
                  state: 'closed'
                });

                console.log(`Successfully closed PR #${prNumber}`);
              } catch (error) {
                console.log(`Error closing PR #${prNumber}:`, error.message);
              }
            }

            if (isManualRun) {
              console.log('\n=== TEST COMPLETED ===');
            } else {
              console.log('\n--- Finished processing all commits ---');
            }

