name: Issue Comment

on:
  issue_comment:
    types: [created]

permissions:
  pull-requests: write
  issues: write
  contents: write
  actions: read

jobs:
  dispatch:
    # Only run for comments on pull requests AND when the comment starts with "/ci"
    if: >
      github.event.issue.pull_request != null &&
      startsWith(github.event.comment.body, '/ci')
    runs-on: ubuntu-latest
    outputs:
      dispatched: ${{ steps.dispatch.outputs.dispatched }}
      event_types: ${{ steps.dispatch.outputs.event_types }}
      correlation_id: ${{ steps.dispatch.outputs.correlation_id }}
      trigger_comment_id: ${{ steps.dispatch.outputs.trigger_comment_id }}
      ack_comment_id: ${{ steps.ack.outputs.comment_id }}
    steps:
      - name: Guardrail — allow only members/collaborators
        id: guard
        uses: actions/github-script@v8
        with:
          script: |
            const allowed = ['MEMBER','OWNER','COLLABORATOR'];
            const assoc = context.payload.comment.author_association;
            if (!allowed.includes(assoc)) {
              core.notice(`Ignoring /ci from ${context.payload.comment.user.login} (author_association=${assoc}).`);
              core.setOutput('skip', 'true');
            }

      - name: Trigger repository dispatch
        id: dispatch
        if: steps.guard.outputs.skip != 'true'
        uses: actions/github-script@v8
        with:
          script: |
            const owner = context.repo.owner;
            const repo = context.repo.repo;
            const pull_number = context.payload.issue.number;
            const comment = context.payload.comment;

            // Fetch current PR state
            const { data: pr } = await github.rest.pulls.get({ owner, repo, pull_number });

            // Add reaction so folks know we saw it
            try {
              await github.rest.reactions.createForIssueComment({
                owner,
                repo,
                comment_id: comment.id,
                content: 'rocket'
              });
            } catch (e) {
              core.info('Could not add reaction (likely due to permissions). Continuing.');
            }

            const labels = (pr.labels ?? []).map(label => label.name);
            const directCiLabels = labels.filter(label => label.startsWith('ci-'));
            const hasCiAll = directCiLabels.includes('ci-all');
            const dedupe = new Set(
              directCiLabels.filter(label => label !== 'ci-all')
            );

            if (!hasCiAll && dedupe.size === 0) {
              core.notice('No ci-* labels found on the pull request; nothing to dispatch.');
              core.setOutput('dispatched', 'false');
              core.setOutput('event_types', '');
              return;
            }

            const correlation_id = `id-${comment.id}-${Date.now().toString(36)}`;

            const clientPayload = {
              correlation_id,
              pull_number,
              pr_ref: `refs/pull/${pull_number}/merge`,
              pr_head_ref: pr.head.ref,
              pr_head_sha: pr.head.sha,
              pr_base_ref: pr.base.ref,
              pr_base_sha: pr.base.sha,
              trigger_comment_id: comment.id,
              trigger_comment_user: comment.user.login,
            };

            const eventTypes = hasCiAll
              ? ['ci-all']
              : Array.from(dedupe);
            for (const eventType of eventTypes) {
              await github.rest.repos.createDispatchEvent({
                owner,
                repo,
                event_type: eventType,
                client_payload: { ...clientPayload, ci_label: eventType }
              });
              core.notice(`Dispatched '${eventType}' event for PR #${pull_number}.`);
            }

            core.setOutput('dispatched', 'true');
            core.setOutput('event_types', eventTypes.join(','));
            core.setOutput('correlation_id', correlation_id);
            core.setOutput('trigger_comment_id', String(comment.id));

      - name: Acknowledge in thread (optional)
        if: steps.guard.outputs.skip != 'true' && steps.dispatch.outputs.dispatched == 'true'
        id: ack
        uses: actions/github-script@v8
        env:
          EVENT_TYPES: ${{ steps.dispatch.outputs.event_types }}
          CORRELATION_ID: ${{ steps.dispatch.outputs.correlation_id }}
        with:
          script: |
            const eventTypes = (process.env.EVENT_TYPES || '')
              .split(',')
              .map(label => label.trim())
              .filter(Boolean);
            const formatted = eventTypes.map(label => `\`repository_dispatch:${label}\``).join(', ');
            const { owner, repo } = context.repo;
            const issue_number = context.payload.issue.number;
            const body = [
              `✅ CI trigger requested by @${context.payload.comment.user.login}.`,
              `Fired ${formatted}.`,
              '',
              `_Collecting run links for correlation \`${process.env.CORRELATION_ID}\`…_`
            ].join('\n');
            const { data: comment } = await github.rest.issues.createComment({
              owner, repo, issue_number,
              body
            });
            core.setOutput('comment_id', String(comment.id));

      - name: Notify missing ci label
        if: steps.guard.outputs.skip != 'true' && steps.dispatch.outputs.dispatched != 'true'
        uses: actions/github-script@v8
        with:
          script: |
            const { owner, repo } = context.repo;
            const issue_number = context.payload.issue.number;
            await github.rest.issues.createComment({
              owner,
              repo,
              issue_number,
              body: `⚠️ CI trigger ignored because the pull request has no \`ci-*\` labels (e.g. \`ci-apo\`, \`ci-calc-x\`). Add the desired labels and try \`/ci\` again.`
            });

  watch:
    needs: dispatch
    if: needs.dispatch.outputs.dispatched == 'true'
    runs-on: ubuntu-latest
    timeout-minutes: 180
    steps:
      - name: Track dispatched runs and update comment
        uses: actions/github-script@v8
        env:
          CORRELATION_ID: ${{ needs.dispatch.outputs.correlation_id }}
          ACK_COMMENT_ID: ${{ needs.dispatch.outputs.ack_comment_id }}
          TRIGGER_COMMENT_ID: ${{ needs.dispatch.outputs.trigger_comment_id }}
        with:
          script: |
            const owner = context.repo.owner;
            const repo = context.repo.repo;
            const correlationId = process.env.CORRELATION_ID;
            if (!correlationId) {
              core.warning('No correlation id supplied; nothing to watch.');
              return;
            }

            const ackCommentId = Number(process.env.ACK_COMMENT_ID || 0);
            if (!ackCommentId) {
              core.warning('No comment id available for updates; skipping watch.');
              return;
            }
            const triggerCommentId = Number(process.env.TRIGGER_COMMENT_ID || 0);
            if (!triggerCommentId) {
              core.warning('No trigger comment id available; skipping watch.');
              return;
            }

            const prefix = `🚀 CI Watcher for correlation ${correlationId} triggered by comment ${triggerCommentId}`;
            core.notice(`Watching workflow runs for correlation '${correlationId}' using comment ${ackCommentId}.`);

            function fmt(run) {
              const status = run.status;
              const conclusion = run.conclusion;
              const badge = status === 'completed'
                ? (conclusion === 'success' ? '🟢' : conclusion === 'failure' ? '🔴' : '🟡')
                : (status === 'in_progress' ? '🟣' : '⚪️');
              const title = run.display_title || run.name || `run ${run.id}`;
              const statusText = status === 'completed' ? `${status}/${conclusion}` : status;
              return `- ${badge} [${title}](${run.html_url}) — \`${statusText}\``;
            }

            const signatureOf = runs =>
              runs
                .map(run => `${run.id}:${run.status}/${run.conclusion || ''}`)
                .sort()
                .join('|');

            const deadlineMs = Date.now() + 175 * 60 * 1000; // 175 minutes
            let found = [];

            async function searchOnce() {
              const runs = await github.paginate(
                github.rest.actions.listWorkflowRunsForRepo,
                { owner, repo, event: 'repository_dispatch', per_page: 100 }
              );
              const cutoff = new Date(Date.now() - 60 * 60 * 1000); // last hour
              return runs.filter(run => {
                const createdAt = new Date(run.created_at);
                const title = String(run.display_title || run.name || '');
                return createdAt >= cutoff && title.includes(correlationId);
              });
            }

            while (Date.now() < deadlineMs) {
              found = await searchOnce();
              if (found.length > 0) {
                core.notice(`Discovered ${found.length} workflow run(s) for correlation '${correlationId}'.`);
                break;
              }
              core.notice(`No runs found yet for correlation '${correlationId}'; retrying shortly.`);
              await new Promise(res => setTimeout(res, 10000));
            }

            if (found.length === 0) {
              core.notice(`Watcher timed out with no runs for correlation '${correlationId}'; notifying thread.`);
              await github.rest.issues.updateComment({
                owner,
                repo,
                comment_id: ackCommentId,
                body: [
                  prefix,
                  `⚠️ I couldn't find any workflow runs for correlation \`${correlationId}\`.`,
                  `They may be delayed or misconfigured.`
                ].join('\n')
              });
              return;
            }

            const runIds = new Set(found.map(run => run.id));
            let lastSignature = '';

            async function refreshRuns() {
              const ids = Array.from(runIds);
              const refreshed = [];
              for (const id of ids) {
                const { data } = await github.rest.actions.getWorkflowRun({
                  owner,
                  repo,
                  run_id: id
                });
                refreshed.push(data);
              }
              return refreshed;
            }

            async function updateCommentIfChanged(runs, allDone) {
              const signature = signatureOf(runs);
              if (signature === lastSignature) {
                // Run statuses unchanged; skipping comment update.
                return;
              }
              lastSignature = signature;
              core.notice(`Updating comment ${ackCommentId} with ${runs.length} run status entries (allDone=${allDone}).`);
              await github.rest.issues.updateComment({
                owner,
                repo,
                comment_id: ackCommentId,
                body: [
                  prefix,
                  `🏃‍♀️ Tracking ${runs.length} workflow run(s):`,
                  '',
                  ...runs.map(fmt),
                  '',
                  allDone ? '✅ All runs completed.' : '_Still running…_'
                ].join('\n')
              });
            }

            await updateCommentIfChanged(found, found.every(run => run.status === 'completed'));

            while (Date.now() < deadlineMs) {
              const latest = await searchOnce();
              for (const run of latest) {
                if (!runIds.has(run.id)) {
                  runIds.add(run.id);
                  core.notice(`Detected additional run ${run.id} (${run.name || run.display_title || 'unnamed'}) for correlation '${correlationId}'.`);
                }
              }
              const current = await refreshRuns();
              const allDone = current.every(run => run.status === 'completed');
              await updateCommentIfChanged(current, allDone);
              if (allDone) {
                core.notice(`All runs for correlation '${correlationId}' completed; stopping watcher.`);
                break;
              }
              await new Promise(res => setTimeout(res, 60000));
            }

            if (Date.now() >= deadlineMs) {
              core.warning(`Watcher hit the deadline while monitoring correlation '${correlationId}'.`);
            }

name: Auto-label when user responds
permissions:
  issues: write

on:
  issue_comment:
    types: [created]

env:
  TRIAGERS: '["int19h","karthiknadig","ericsnowcurrently","fabioz", "gramster", "StellaHuang95", "AdamYoblick"]'

jobs:
  run-check:
    runs-on: ubuntu-latest
    if: contains(github.event.issue.labels.*.name, 'waiting for response') && !contains(github.event.issue.labels.*.name, 'user responded')
    steps:
      - name: Add/Remove labels when user responds
        uses: actions/github-script@v6
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const payload = context.payload;
            const commentAuthor = payload.comment.user.login;
            const isTeamMember = ${{ env.TRIAGERS }}.includes(commentAuthor);
            if (!isTeamMember) {
              const issue_number = payload.issue.number;              
              await github.rest.issues.removeLabel({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: issue_number,
                name: 'waiting for response'
              });
              await github.rest.issues.addLabels({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: issue_number,
                labels: ['user responded']
              });
            }

name: VRT | Comment on PR
on:
  workflow_run:
    workflows: ['VRT PR']
    types:
      - completed

env:
  NX_PARALLEL: 4 # ubuntu-latest = 4-core CPU / 16 GB of RAM | macos-14-xlarge (arm) = 6-core CPU / 14 GB of RAM
  NX_PREFER_TS_NODE: true
  NX_VERBOSE_LOGGING: true

jobs:
  run_vr_diff:
    runs-on: ubuntu-latest
    if: ${{ github.repository_owner == 'microsoft' }} && ${{ github.event.workflow_run.event == 'pull_request' && github.event.workflow_run.conclusion == 'success' }}
    permissions:
      # necessary to write comments to the PR from the vr-approval-cli
      pull-requests: write
      id-token: write
      contents: read
      actions: read
    steps:
      - uses: actions/checkout@v6
        with:
          sparse-checkout: |
            .github

      # downloaded artifacts will contain screenshots from affected project including 'screenshots-report.json' which contains proper image mappings for affected project
      # - see @{link file://./../scripts/prepare-vr-screenshots-for-upload.js#45}
      # - see @{link file://./pr-vrt.yml#56}

      - uses: actions/download-artifact@v7
        with:
          name: vrscreenshot
          path: ./screenshots
          run-id: ${{ github.event.workflow_run.id }}
          github-token: ${{ secrets.GITHUB_TOKEN }}

      - name: Check if visual regression should be run (affected projects)
        uses: actions/github-script@v8
        id: should_run_vrt
        with:
          script: |
            const { readFileSync } = require('node:fs');
            const json = JSON.parse(readFileSync('screenshots/screenshots-report.json','utf-8'));
            const result = Object.keys(json).length > 0 ? true : false;
            return result;
          result-encoding: string

      - name: Login via Azure CLI
        if: ${{ steps.should_run_vrt.outputs.result == 'true' }}
        uses: azure/login@a457da9ea143d694b1b9c7c869ebb04ebe844ef5 # v2.3.0
        with:
          client-id: ${{ secrets.AZURE_VRT_CLIENT_ID }}
          tenant-id: ${{ secrets.AZURE_TENANT_ID }}
          subscription-id: ${{ secrets.AZURE_SUBSCRIPTION_ID }}

      - uses: actions/download-artifact@v7
        if: ${{ steps.should_run_vrt.outputs.result == 'true' }}
        with:
          name: pr-number
          path: ./results
          run-id: ${{ github.event.workflow_run.id }}
          github-token: ${{ secrets.GITHUB_TOKEN }}

      - name: Run VR Approval CLI
        if: ${{ steps.should_run_vrt.outputs.result == 'true' }}
        uses: actions/github-script@v8
        env:
          # this is explicity needed as github token is not available in CLI context
          GITHUB_API_TOKEN: ${{ secrets.GITHUB_TOKEN }}
          PRINCIPAL_CLIENT_ID: ${{ secrets.AZURE_VRT_CLIENT_ID }}
        with:
          script: |
            const run = require('./.github/scripts/validate-pr-number');
            const pull_number = run({filePath:'results/pr.txt'});

            const result = await github.rest.pulls.get({
              owner: context.payload.workflow_run.repository.owner.login,
              repo: context.payload.workflow_run.repository.name,
              pull_number,
            });

            const pr = result.data;

            if (pr.head.sha !== context.payload.workflow_run.head_commit.id) {
              console.log(
                "PR head sha does not match the workflow run head commit id. " +
                "There has probably been a push to the PR, so we will not run the VR Diff for the last iteration. " +
                "Exiting the script."
              );
              process.exit(0);
            }

            const headOwner = pr.head.repo.owner.login;
            const baseOwner = pr.base.repo.owner.login;

            const data = {
              GITHUB_RUN_ID: context.payload.workflow_run.id,
              GITHUB_REF: `refs/pull/${pr.number}/merge`,

              GITHUB_SHA: pr.head.sha,
              GITHUB_HEAD_REF: headOwner !== baseOwner ? `${headOwner}:${pr.head.ref}` : pr.head.ref,

              GITHUB_REPOSITORY: context.payload.workflow_run.repository.full_name,

              GITHUB_BASE_REF: pr.base.ref,
              GITHUB_WORKFLOW: context.payload.workflow_run.name
            };

            Object.keys(data).forEach(key => {
              process.env[key] = data[key];
            });

            console.log("Metadata", data);

            const { execSync } = require('child_process');

            try {
              execSync(`npx vr-approval-cli@0.5.1 create-policy \
                --nonBlockingPipelines '{"301":{"pipelineStatus": "PENDING","pipelineName": "Fluent UI"}}' \
                --clientType FLUENTUI`, { stdio: 'inherit' });

              execSync(`npx vr-approval-cli@0.5.1 run-diff \
                --screenshotsDirectory ./screenshots \
                --buildType pr \
                --ciDefinitionId 'vrt-baseline.yml' \
                --clientType "FLUENTUI" \
                --groupName "Fluent UI" \
                --locationPrefix 'fluentui-github' \
                --locationPostfix 'vrscreenshots-github' \
                --threshold '0.04' \
                --pipelineId '301' \
                --cumThreshold '1'`, { stdio: 'inherit' });
            } catch (error) {
              console.error("Error running vr-approval-cli commands:", error.message);
              process.exit(1);
            }

# This workflow is used to add new issues to GitHub Kiota Project

name: Add Issue or PR to project
on:
  issues:
    types:
      - opened
  pull_request:
    types:
      - opened
    branches:
      - "main"
  workflow_dispatch:

jobs:
  track_issue:
    if: github.actor != 'dependabot[bot]' && github.event.pull_request.head.repo.fork == false
    runs-on: ubuntu-latest
    steps:
      - name: Generate token
        id: generate_token
        uses: actions/create-github-app-token@v2
        with:
          app-id: ${{ secrets.GRAPHBOT_APP_ID }}
          private-key: ${{ secrets.GRAPHBOT_APP_PEM }}

      - name: Check if issue has language specified
        env:
          ISSUE_BODY: ${{github.event.issue.body}}
        run: |
          language=$(awk '/SDK language/{flag=1;next} /Describe/{flag=0} flag' <<< "$ISSUE_BODY" | tr -d '[:space:]')
          allowedList="PHP Python Go TypeScript Csharp Java PowerShell Ruby"
          if [[ $allowedList =~ (^|[[:space:]])$language($|[[:space:]]) ]]; then
            echo "$language is in allowed list";
            echo 'LANGUAGE='$language >> $GITHUB_ENV;
            echo 'SELECTED_LANGUAGE='$language >> $GITHUB_ENV;
          else
            echo "$language is not allowed";
            echo 'SELECTED_LANGUAGE=Multiple Languages' >> $GITHUB_ENV;
          fi

      - name: Get project data
        env:
          GITHUB_TOKEN: ${{ steps.generate_token.outputs.token }}
          ORGANIZATION: microsoft
          PROJECT_NUMBER: 220
        run: |
          gh api graphql -f query='
            query($org: String!, $number: Int!) {
              organization(login: $org){
                projectV2(number: $number) {
                  id
                  fields(first:20) {
                    nodes {
                      ... on ProjectV2SingleSelectField {
                        id
                        name
                        options {
                          id
                          name
                        }
                      }
                    }
                  }
                }
              }
            }' -f org=$ORGANIZATION -F number=$PROJECT_NUMBER > project_data.json

          echo 'PROJECT_ID='$(jq '.data.organization.projectV2.id' project_data.json) >> $GITHUB_ENV
          echo 'LANGUAGE_FIELD_ID='$(jq '.data.organization.projectV2.fields.nodes[] | select(.name== "Language") | .id' project_data.json) >> $GITHUB_ENV
          LANGUAGE_OPTION_ID=$(jq --arg lang "$SELECTED_LANGUAGE" '.data.organization.projectV2.fields.nodes[] | select(.name== "Language") | .options[] | select(.name==$lang) | .id' project_data.json)
          echo "LANGUAGE_OPTION_ID=$LANGUAGE_OPTION_ID" >> $GITHUB_ENV

      - name: Add Issue or PR to project
        env:
          GITHUB_TOKEN: ${{ steps.generate_token.outputs.token }}
          ISSUE_ID: ${{ github.event_name == 'issues' && github.event.issue.node_id || github.event.pull_request.node_id }}
        run: |
          item_id="$( gh api graphql -f query='
            mutation($project:ID!, $issue:ID!) {
              addProjectV2ItemById(input: {projectId: $project, contentId: $issue}) {
                item {
                  id
                }
              }
            }' -f project=$PROJECT_ID -f issue=$ISSUE_ID --jq '.data.addProjectV2ItemById.item.id')"

          echo 'ITEM_ID='$item_id >> $GITHUB_ENV

      - name: Set Language to Project
        env:
          GITHUB_TOKEN: ${{ steps.generate_token.outputs.token }}
        run: |
          gh api graphql -f query='
            mutation (
              $project: ID!
              $item: ID!
              $language_field: ID!
              $language_value: String!
            ) {
              set_status: updateProjectV2ItemFieldValue(input: {
                projectId: $project
                itemId: $item
                fieldId: $language_field
                value: {singleSelectOptionId: $language_value}
              }) {
                projectV2Item {
                  id
                  }
              }
            }' -f project=$PROJECT_ID -f item=$ITEM_ID -f language_field=$LANGUAGE_FIELD_ID -f language_value=${{ env.LANGUAGE_OPTION_ID }} --silent

      - name: Get label for selected language in repository
        if: ${{ env.SELECTED_LANGUAGE != 'Multiple Languages'}}
        env:
          GITHUB_TOKEN: ${{ steps.generate_token.outputs.token }}
        run: |
          gh api graphql -f query='
            query($repoOwner: String!, $repoName: String!) {
              repository(owner: $repoOwner, name: $repoName) {
                id,
                labels(first: 100) {
                  nodes{
                    id,
                    name
                  }
                }
              }
            }' -f repoOwner=${{github.repository_owner}} -f repoName=${{github.event.repository.name}} > issue_data.json

          echo 'LANGUAGELABEL_ID='$(jq --arg lang "$SELECTED_LANGUAGE" '.data.repository.labels.nodes[] | select(.name==$lang) | .id' issue_data.json) >> $GITHUB_ENV

      - name: Add label to issue
        if: ${{ env.SELECTED_LANGUAGE != 'Multiple Languages'}}
        env:
          GITHUB_TOKEN: ${{ steps.generate_token.outputs.token }}
          ISSUE_ID: ${{ github.event_name == 'issues' && github.event.issue.node_id || github.event.pull_request.node_id }}
        run: |
          gh api graphql -f query='
            mutation (
              $issue: ID!
              $label: ID!
            ) {
              addLabelsToLabelable(input: {
                labelableId: $issue
                labelIds : [$label]
              }) {
                clientMutationId
              }
            }' -f issue=$ISSUE_ID -f label=$LANGUAGELABEL_ID --silent

name: "Auto-assign milestone for Bug Bash template issues"

on:
  issues:
    types: [opened]

permissions:
  issues: write
  contents: read

env:
  TARGET_MILESTONE: "2025-10"

jobs:
  set-milestone:
    runs-on: ubuntu-latest
    if: >
      github.event.issue.state == 'open' &&
      contains(join(github.event.issue.labels.*.name, ','), 'Bug-Bash') &&
      contains(join(github.event.issue.labels.*.name, ','), 'Azure.Mcp.Server') &&
      contains(github.event.issue.body, '<!-- TEMPLATE: bug-bash-v1 -->')
    steps:
      - name: Apply milestone if missing
        uses: actions/github-script@v8
        with:
          script: |
            const owner = context.repo.owner;
            const repo = context.repo.repo;
            const issue_number = context.issue.number;

            if (context.payload.issue.milestone) {
              core.info('Issue already has a milestone. Skipping.');
              return;
            }

            const targetTitle = process.env.TARGET_MILESTONE;
            const milestones = await github.paginate(
              github.rest.issues.listMilestones,
              { owner, repo, state: "open", per_page: 100 }
            );
            const ms = milestones.find(m => m.title === targetTitle);
            if (!ms) {
              core.warning(`Milestone "${targetTitle}" not found. Create it first.`);
              return;
            }

            await github.rest.issues.update({
              owner, repo, issue_number, milestone: ms.number
            });
            core.info(`Milestone "${targetTitle}" applied to #${issue_number}.`);

name: "Check client side changes"
on:
  push:
    branches:
      - main
    paths:
      - 'docs/src/api/**/*'
      - 'packages/playwright-core/src/client/**/*'
      - 'packages/playwright-core/src/utils/isomorphic/**/*'
      - 'packages/playwright/src/matchers/matchers.ts'
      - 'packages/protocol/src/protocol.yml'
jobs:
  check:
    name: Check
    runs-on: ubuntu-24.04
    if: github.repository == 'microsoft/playwright'
    steps:
      - uses: actions/checkout@v6
      - uses: actions/create-github-app-token@v2
        id: app-token
        with:
          app-id: ${{ vars.PLAYWRIGHT_APP_ID }}
          private-key: ${{ secrets.PLAYWRIGHT_PRIVATE_KEY }}
          repositories: |
            playwright
            playwright-python
            playwright-java
            playwright-dotnet
      - name: Create GitHub issue
        uses: actions/github-script@v8
        with:
          github-token: ${{ steps.app-token.outputs.token }}
          script: |
            const currentPlaywrightVersion = require('./package.json').version.match(/\d+\.\d+/)[0];
            const { data } = await github.rest.git.getCommit({
              owner: context.repo.owner,
              repo: context.repo.repo,
              commit_sha: context.sha,
            });
            const commitHeader = data.message.split('\n')[0];
            const prMatch = commitHeader.match(/#(\d+)/);
            const formattedCommit = prMatch 
              ? `https://github.com/microsoft/playwright/pull/${prMatch[1]}`
              : `https://github.com/${context.repo.owner}/${context.repo.repo}/commit/${context.sha} (${commitHeader})`;

            const title = '[Ports]: Backport client side changes for ' + currentPlaywrightVersion;
            for (const repo of ['playwright-python', 'playwright-java', 'playwright-dotnet']) {
              const { data: issuesData } = await github.rest.search.issuesAndPullRequests({
                q: `is:issue is:open repo:microsoft/${repo} in:title "${title}"`
              })
              let issueNumber = null;
              let issueBody = '';
              if (issuesData.total_count > 0) {
                issueNumber = issuesData.items[0].number
                issueBody = issuesData.items[0].body
              } else {
                const { data: issueCreateData } = await github.rest.issues.create({
                  owner: context.repo.owner,
                  repo: repo,
                  title,
                  body: 'Please backport client side changes: \n',
                });
                issueNumber = issueCreateData.number;
                issueBody = issueCreateData.body;
              }
              const newBody = issueBody.trimEnd() + `
              - [ ] ${formattedCommit}`;
              const data = await github.rest.issues.update({
                owner: context.repo.owner,
                repo: repo,
                issue_number: issueNumber,
                body: newBody
              })
            }

name: Label external pull requests

on:
  pull_request_target:
    types: [opened, reopened]

# Minimal permissions required to read repo metadata and add labels
permissions:
  pull-requests: write
  contents: read

jobs:
  label-external:
    runs-on: ubuntu-slim
    steps:
      - name: Label PRs from contributors without write access
        uses: actions/github-script@ed597411d8f924073f98dfc5c65a23a2325f34cd # v8.0.0
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const pr = context.payload.pull_request;
            if (!pr) {
              console.log('No pull_request payload found - nothing to do.');
              return;
            }

            const owner = context.repo.owner;
            const repo = context.repo.repo;
            const username = pr.user && pr.user.login;
            if (!username) {
              console.log('PR author not found - exiting.');
              return;
            }

            const privileged = ['admin', 'maintain', 'write'];

            try {
              const resp = await github.rest.repos.getCollaboratorPermissionLevel({
                owner,
                repo,
                username
              });
              const permission = resp.data && resp.data.permission;
              console.log(`User ${username} permission: ${permission}`);

              if (!privileged.includes(permission)) {
                console.log(`Adding 'external' label to PR #${pr.number}`);
                await github.rest.issues.addLabels({
                  owner,
                  repo,
                  issue_number: pr.number,
                  labels: ['external']
                });
              } else {
                console.log(`User ${username} has write or higher permission (${permission}) - skipping label.`);
              }
            } catch (err) {
              // 404 typically means the user is not a collaborator
              if (err.status === 404) {
                console.log(`User ${username} is not a collaborator - adding 'external' label`);
                await github.rest.issues.addLabels({
                  owner,
                  repo,
                  issue_number: pr.number,
                  labels: ['external']
                });
              } else {
                console.log(`Error checking user permission: ${err.message}`);
              }
            }

name: Check if the commit is part of a merged PR

on:
  workflow_call:
    outputs:
      is_merged_pr:
        description: "Whether the current push came from a merged PR"
        value: ${{ jobs.check-pr.outputs.is_merged_pr }}
      pr_head_sha:
        description: "The head SHA of the merged PR"
        value: ${{ jobs.check-pr.outputs.pr_head_sha }}

jobs:
  check-pr:
    runs-on: ubuntu-latest
    outputs:
      is_merged_pr: ${{ steps.parse-check-pr.outputs.is_merged_pr }}
      pr_head_sha: ${{ steps.parse-check-pr.outputs.pr_head_sha }}
    steps:
      - name: Check if this commit is from a merged PR
        id: check-pr
        uses: actions/github-script@v7
        with:
          result-encoding: string
          script: |
            const commitSha = context.sha;
            const { data: prs } = await github.rest.repos.listPullRequestsAssociatedWithCommit({
              owner: context.repo.owner,
              repo: context.repo.repo,
              commit_sha: commitSha
            });

            if (!prs.length) {
              core.info('No PRs associated with this commit.');
              return JSON.stringify({ is_merged_pr: false, pr_head_sha: '' });
            }

            const mergedPr = prs.find(pr => pr.merged_at !== null);

            if (!mergedPr) {
              core.info('PRs found, but none were merged.');
              return JSON.stringify({ is_merged_pr: false, pr_head_sha: '' });
            }

            core.info(`Found merged PR head SHA: ${mergedPr.head.sha}`);
            return JSON.stringify({ is_merged_pr: true, pr_head_sha: mergedPr.head.sha });

      - name: Parse outputs
        id: parse-check-pr
        shell: bash
        run: |
          echo "Parsing result: ${{ steps.check-pr.outputs.result }}"
          echo "is_merged_pr=$(jq -r '.is_merged_pr' <<< '${{ steps.check-pr.outputs.result }}')" >> $GITHUB_OUTPUT
          echo "pr_head_sha=$(jq -r '.pr_head_sha' <<< '${{ steps.check-pr.outputs.result }}')" >> $GITHUB_OUTPUT

