                      }
                    }
                  }
                }
              }
              if (toolSummary.length > 0) {
                lines.push("Tools/Commands:");
                lines.push(...toolSummary);
                if (toolCounts.total > 20) {
                  lines.push(`  ... and ${toolCounts.total - 20} more`);
                }
                lines.push("");
